use super::*;
use letibot_sessionlog::hub::Hub;
use letibot_sessionlog::protocol::Caps;
use letibot_sessionlog::testing;

fn app() -> App {
    App::new(RenderConfig {
        width: 80,
        color: false,
        ..RenderConfig::default()
    })
}

fn decision_with(kinds: &[letibot_sessionlog::event::OptionKind]) -> OpenDecision {
    use letibot_sessionlog::event::DecisionOption;
    OpenDecision {
        req_id: "d1".into(),
        kind: "permission".into(),
        call_id: None,
        access: String::new(),
        summary: "edit a file".into(),
        target: String::new(),
        write_targets: Vec::new(),
        detail: String::new(),
        options: kinds
            .iter()
            .map(|k| DecisionOption {
                option_id: match k {
                    letibot_sessionlog::event::OptionKind::AllowOnce => "allow_once",
                    letibot_sessionlog::event::OptionKind::AllowSession => "allow_session",
                    letibot_sessionlog::event::OptionKind::AllowAlways => "allow_always",
                    letibot_sessionlog::event::OptionKind::RejectOnce => "deny",
                    letibot_sessionlog::event::OptionKind::RejectAlways => "deny_always",
                }
                .to_string(),
                label: "x".into(),
                kind: *k,
            })
            .collect(),
        choices: vec![],
        because: String::new(),
        advice: None,
        // The fixture is this session's own call — see `SubagentAsk` for the card a
        // child's gate posts here instead.
        subagent: None,
        deadline: None,
        on_timeout: letibot_sessionlog::event::OnTimeout::Deny,
        asked_ts: 0,
    }
}

/// **The card states why it is asking, in the words of whoever is stuck.**
///
/// `because` is the model's own line on a question — *"what you are stuck on and
/// why the answer changes what you do"* — and this head carried it on
/// `OpenDecision` from the day the field existed and never drew it. So the person
/// was given a question with no answer to *why are you asking me this*, which is
/// the only thing that decides whether the question is worth their time.
#[test]
fn the_card_states_why_it_is_asking_in_the_speakers_own_words() {
    use letibot_sessionlog::event::OptionKind;
    let a = app();

    // Nothing to say, so nothing said: §13.2b in both directions — a `because:`
    // row with an empty string is a row of nothing, and the card is not entitled
    // to it.
    let bare = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    let drawn = a.decision_lines(&bare, 100).join("\n");
    assert!(!drawn.contains("because"), "{drawn}");

    let mut d = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    d.because = "the answer changes which migration I write".into();
    let drawn = a.decision_lines(&d, 100).join("\n");
    assert!(
        drawn.contains("because: the answer changes which migration I write"),
        "{drawn}"
    );
    // Labelled with its speaker, and in the same dim register every other
    // borrowed sentence on this card uses — the oracle's verdict included,
    // because both are evidence rather than the question. Checked on a head
    // that emits colour, since the layout tests deliberately do not.
    let painted = App::new(RenderConfig {
        width: 100,
        color: true,
        ..RenderConfig::default()
    });
    let line = painted
        .decision_lines(&d, 100)
        .into_iter()
        .find(|l| l.contains("because:"))
        .expect("the row");
    assert!(line.contains(sgr::DIM), "not in the dim register: {line:?}");
    // And it sits with the rest of the evidence, above the ladder — read before
    // the choice is made, which is the only time it can inform one.
    let because_at = drawn.find("because:").unwrap();
    let ladder_at = drawn.find("allow_once").unwrap();
    assert!(because_at < ladder_at, "{drawn}");
}

/// **A card that is a subagent's call says so, and names the child.**
///
/// The operator's ruling is that a subagent's ask surfaces at the root's head — *"who
/// asks subagents permissions? i think they should surface to the parent head all the way
/// to the root obviously"*. R58 gives a child no head, so its card arrives on THIS
/// session's screen, and **an unlabelled card is answered for the wrong thing**: the
/// question and the ladder are the same either way, and this clause is the only thing
/// that says whose call it is.
#[test]
fn the_card_says_when_the_call_is_a_subagents_and_names_it() {
    use letibot_sessionlog::event::{OptionKind, SubagentAsk};
    let a = app();

    // This session's own call: no clause at all. A `None` that still drew a line would be
    // furniture on every ordinary card.
    let mine = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    let drawn = a.decision_lines(&mine, 100).join("\n");
    assert!(!drawn.contains("a subagent's call"), "{drawn}");

    let mut child = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    child.subagent = Some(SubagentAsk {
        handle: "s-sub-3".into(),
        task: "count the rows the store never reads".into(),
        root: "s-root".into(),
    });
    let drawn = a.decision_lines(&child, 100).join("\n");
    // The handle — what `task_result` collects by and what a head attaches to — and the
    // task, so two children of one session are told apart.
    assert!(drawn.contains("a subagent's call — s-sub-3"), "{drawn}");
    assert!(
        drawn.contains("count the rows the store never reads"),
        "{drawn}"
    );
    // **Above the ladder**, so it is read on the same pass of the eye as the question:
    // under the wall it would be read after the answer was already chosen.
    let clause = drawn.find("a subagent's call").unwrap();
    let ladder = drawn.find("allow_once").unwrap();
    assert!(clause < ladder, "{drawn}");
    // In the faint register, like every other clause on this card. Checked on a head that
    // emits colour, since these layout tests deliberately do not.
    let painted = App::new(RenderConfig {
        width: 100,
        color: true,
        ..RenderConfig::default()
    });
    let line = painted
        .decision_lines(&child, 100)
        .into_iter()
        .find(|l| l.contains("a subagent's call"))
        .expect("the row");
    assert!(line.contains(sgr::DIM), "not in the dim register: {line:?}");
    // A child whose task the daemon never sent draws the handle alone, rather than a
    // dangling separator after it.
    let mut bare = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    bare.subagent = Some(SubagentAsk {
        handle: "s-sub-4".into(),
        task: String::new(),
        root: "s-root".into(),
    });
    let drawn = a.decision_lines(&bare, 100).join("\n");
    assert!(drawn.contains("a subagent's call — s-sub-4"), "{drawn}");
    assert!(
        !drawn.contains("— s-sub-4 ·"),
        "a task nobody sent was invented: {drawn}"
    );
}

/// **§11.7: the card says WHY it is asking, and only where the reason is true.**
///
/// R18's last wording item. The headline says what the tool **declares** (`wants exec
/// access`) and the line above it is layer A's reading of the **action** (`auto (a read
/// inside the boundary)`), and nothing joined them — so *"the classifier decided this
/// needed no asking"* read as being argued with by the card going up anyway. The operator,
/// asleep at the time: an operator who cannot tell that apart from a question they should
/// have been asked is the shape that cost three 300-second refusals in one night.
///
/// **Two assertions, and the second is the one that keeps the sentence honest.** An
/// `exec`-declaring call that asks carries the clause. A `read`-declaring one **must not**:
/// a read is asked about because of a rule, a path or a mode, so a sentence blaming its
/// declaration would be false on the very card carrying it — which is exactly what
/// `because: workspace: /` was, a fact named after one thing and read from another.
#[test]
fn the_card_says_the_declared_access_is_what_asks_and_only_when_it_is() {
    use letibot_sessionlog::event::OptionKind;
    let a = app();

    let mut exec = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    exec.access = "exec".into();
    let drawn = a.decision_lines(&exec, 100).join("\n");
    assert!(
        drawn.contains("the access is what asks"),
        "§11.7: an exec call that asks must say why it is asking:\n{drawn}"
    );

    // The falsification direction. A read that is asked about is asked about for some
    // other reason, and the clause would be a lie on it.
    let mut read = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    read.access = "read".into();
    let drawn = a.decision_lines(&read, 100).join("\n");
    assert!(
        !drawn.contains("the access is what asks"),
        "the clause is only true of a declaration that ASKS, and a read's does not:\n{drawn}"
    );

    // A daemon older than the field sends an empty access. No clause: the head does not
    // know, and will not guess.
    let older = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    let drawn = a.decision_lines(&older, 100).join("\n");
    assert!(!drawn.contains("the access is what asks"), "{drawn}");
}

/// **A card nobody took to an oracle says so, and a card that did does not.**
///
/// The two silences are different facts and they rendered identically: under
/// `/mode supervised` the question printed above the ladder is *do you agree with
/// the model*, and a card with no verdict on it makes *no oracle was consulted*
/// and *the oracle was asked and said nothing* the same screen. The operator hit
/// the live half of it — an oracle answered and its verdict was unreadable, and
/// the card said so — while the card nobody had asked said exactly the same
/// nothing.
#[test]
fn a_card_that_was_never_taken_to_an_oracle_says_so_and_one_that_was_does_not() {
    use letibot_sessionlog::event::OptionKind;
    let a = app();
    let asked = "no oracle was consulted for this one — the judgement is yours alone";

    // Not supervised, or supervised with no advisor installed: nothing was asked,
    // and the card says which of the two silences this is.
    let d = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    let drawn = a.decision_lines(&d, 100).join("\n");
    assert!(drawn.contains(asked), "{drawn}");

    // An oracle answered, however badly: the verdict is drawn and the sentence is
    // not, so "asked" and "not asked" are two screens.
    let mut d = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    d.advice = Some(letibot_sessionlog::event::ModelAdvice {
        // The case the operator saw: the oracle was consulted and could not
        // produce a verdict, which the daemon poses as a verdict anyway.
        consulted: true,
        would: "unavailable".into(),
        by: "adjudicator".into(),
        basis: "the verdict could not be read".into(),
        cites: Vec::new(),
        latency_ms: 4_000,
        unsure: None,
    });
    let drawn = a.decision_lines(&d, 100).join("\n");
    assert!(
        !drawn.contains(asked),
        "an oracle was asked, so the sentence is false: {drawn}"
    );
    assert!(drawn.contains("model says unavailable"), "{drawn}");

    // **A question is not a gate, so it says neither.** Nothing is ever consulted
    // for one, and a line about oracles on a card offering plain-text choices is
    // noise in the register a reader is taught to skim.
    let mut q = decision_with(&[]);
    q.kind = "question".into();
    let drawn = a.decision_lines(&q, 100).join("\n");
    assert!(!drawn.contains(asked), "a question said it: {drawn}");
    assert!(
        !drawn.contains("model says"),
        "nor claimed a verdict: {drawn}"
    );
}

/// **A glob typed after the option id is the rule's coverage.**
///
/// > *"please add globbing to my answers somehow too"*
#[test]
fn an_answer_can_carry_the_operators_own_glob() {
    use letibot_sessionlog::event::OptionKind;
    let d = decision_with(&[
        OptionKind::AllowOnce,
        OptionKind::AllowAlways,
        OptionKind::RejectOnce,
    ]);

    // The bare id still answers, and asks for no pattern.
    assert_eq!(
        match_option(&d, "allow_once"),
        OptionChoice::One {
            option_id: "allow_once".into(),
            pattern: None,
            note: None
        }
    );
    // A prefix still answers when it names exactly one option, which is how
    // people actually type.
    assert_eq!(
        match_option(&d, "d"),
        OptionChoice::One {
            option_id: "deny".into(),
            pattern: None,
            note: None
        }
    );

    // And the glob rides after it, verbatim: a pattern is a path, so it is not
    // lowercased the way the option id is.
    assert_eq!(
        match_option(&d, "allow_always crates/**/Cargo.toml"),
        OptionChoice::One {
            option_id: "allow_always".into(),
            pattern: Some("crates/**/Cargo.toml".into()),
            note: None
        }
    );

    // **A glob on anything but `allow_always` is refused, not dropped.**
    // Somebody who typed `allow_once src/**` meant the rule to cover `src/**`;
    // granting one call instead is an answer they did not give. `Unnamed` leaves
    // the line in the composer where they can see it.
    assert_eq!(match_option(&d, "allow_once src/**"), OptionChoice::Unnamed);
    assert_eq!(match_option(&d, "deny src/**"), OptionChoice::Unnamed);
}

/// **An ambiguous prefix is refused, and the candidates are named.**
///
/// Typing `allow` used to answer `allow_once` — silently, out of
/// `allow_once`/`allow_session`/`allow_always`, because `.find(starts_with)` takes the
/// first hit in list order. Which of three grants the operator gave is the whole
/// content of the answer, and list position is not something they said. This is a
/// gate: a grant invented by position is an answer nobody gave, and it writes an
/// audit row naming an option the operator can see they did not type.
///
/// Refused means **nothing is answered** — not the typed prefix's first guess, and not
/// the marked row either. The line stays in the composer to be finished, the card
/// stays up, and the sentence says both ways out.
#[test]
fn an_ambiguous_option_prefix_is_refused_with_the_candidates_named() {
    use letibot_sessionlog::event::OptionKind;
    let d = decision_with(&[
        OptionKind::AllowOnce,
        OptionKind::AllowSession,
        OptionKind::AllowAlways,
        OptionKind::RejectOnce,
    ]);
    assert_eq!(
        match_option(&d, "allow"),
        OptionChoice::Ambiguous {
            word: "allow".into(),
            candidates: vec![
                "allow_once".into(),
                "allow_session".into(),
                "allow_always".into()
            ]
        }
    );
    // One character further and it is an answer again — and the case fold does not
    // decide which of these is ambiguous.
    assert_eq!(
        match_option(&d, "allow_a"),
        OptionChoice::One {
            option_id: "allow_always".into(),
            pattern: None,
            note: None
        }
    );
    assert_eq!(
        match_option(&d, "ALLOW_S"),
        OptionChoice::One {
            option_id: "allow_session".into(),
            pattern: None,
            note: None
        }
    );
    // An exact id is never ambiguous, however many of its siblings start the same
    // way, and neither is a line that names nothing at all.
    assert_eq!(
        match_option(&d, "allow_once"),
        OptionChoice::One {
            option_id: "allow_once".into(),
            pattern: None,
            note: None
        }
    );
    assert_eq!(match_option(&d, "nope"), OptionChoice::Unnamed);
    assert_eq!(match_option(&d, ""), OptionChoice::Unnamed);

    // The sentence names them and says what to do next.
    let said = ambiguous_option_line(
        "allow",
        &[
            "allow_once".into(),
            "allow_session".into(),
            "allow_always".into(),
        ],
    );
    for id in ["allow_once", "allow_session", "allow_always"] {
        assert!(said.contains(id), "{said}");
    }
    assert!(said.contains("`allow`"), "{said}");
    assert!(said.contains("finish typing"), "{said}");
    assert!(said.contains('↑'), "{said}");
    // A card long enough to overflow the line says how many there are instead of
    // silently dropping half the candidates.
    let many: Vec<String> = (0..9).map(|i| format!("opt_{i}")).collect();
    let long = ambiguous_option_line("opt", &many);
    assert!(long.contains("9 options"), "{long}");
    assert!(long.contains('…'), "{long}");
}

/// **And the refusal answers nothing, in the head rather than in the matcher.**
///
/// The matcher saying `Ambiguous` is not enough: `submit` is what turns a keypress
/// into an `Action`, and a refusal that still answered the marked row would hand the
/// daemon a grant the operator never chose. So: no action, the words still in the
/// composer, the ask still open, and the candidates on the notice line.
#[test]
fn an_ambiguous_prefix_answers_nothing_and_keeps_the_words() {
    use letibot_sessionlog::event::{OnTimeout, OptionKind};
    let mut a = app();
    a.open.push(decision_with(&[
        OptionKind::AllowOnce,
        OptionKind::AllowSession,
        OptionKind::AllowAlways,
        OptionKind::RejectOnce,
    ]));
    a.open[0].on_timeout = OnTimeout::Deny;
    let pushed = a.open.len();

    assert_eq!(
        a.submit("allow".into()),
        None,
        "an ambiguous name must answer nothing at all"
    );
    // The card is still open, the words are still theirs, and the notice names the
    // three they might have meant — rather than the courtesy line, which would mean
    // the marked row had been answered for them.
    assert_eq!(a.open.len(), pushed, "the ask was answered anyway");
    assert_eq!(a.input(), "allow");
    let said = a.notice.clone().unwrap_or_default();
    for id in ["allow_once", "allow_session", "allow_always"] {
        assert!(said.contains(id), "{said}");
    }
    assert!(
        !said.contains("answered the ask"),
        "the marked row was answered under an ambiguous name: {said}"
    );

    // Finishing the word answers it. The ask stays in `open` until the daemon says
    // it settled — the head does not remove it on the strength of its own submit.
    a.set_composer("allow_session");
    assert_eq!(
        a.submit("allow_session".into()),
        Some(Action::Answer {
            req_id: "d1".into(),
            option_id: "allow_session".into(),
            pattern: None,
            note: None
        })
    );
}

/// **A line that names nothing is still the mid-typing courtesy.** The refusal above
/// must not swallow the case it was built beside: a permission that arrives under
/// somebody's half-thought holds their words and answers the marked row, so their
/// Enter is not a keystroke thrown away.
#[test]
fn a_line_that_names_nothing_holds_the_words_and_answers_the_marked_row() {
    use letibot_sessionlog::event::OptionKind;
    let mut a = app();
    a.open.push(decision_with(&[
        OptionKind::AllowOnce,
        OptionKind::RejectOnce,
    ]));
    let action = a.submit("why did the cache miss?".into());
    assert!(
        matches!(action, Some(Action::Answer { ref option_id, .. }) if option_id == "allow_once"),
        "the marked row is the answer: {action:?}"
    );
    assert_eq!(a.input(), "why did the cache miss?", "the words are held");
    assert!(
        a.notice
            .as_deref()
            .unwrap_or("")
            .contains("answered the ask"),
        "and it says which of the two things just happened: {:?}",
        a.notice
    );
}

/// **`deny_and_tell` can be told something.** Its label is *"Deny, and tell
/// the model why"* and nothing carried the why: the head had no field, the
/// wire had no field, and typing it was REFUSED by `match_option` — the line
/// stayed in the composer and nothing was answered at all. The operator:
/// *"deny and tell doesnt work - there is no input for the 'tell' part"*.
#[test]
fn deny_and_tell_carries_the_operators_words() {
    use letibot_sessionlog::event::OptionKind;
    let d = decision_with(&[
        OptionKind::AllowOnce,
        OptionKind::AllowAlways,
        OptionKind::RejectAlways,
    ]);

    // Keyed on the KIND, not the id: the daemon calls this option
    // `deny_and_tell` and this fixture calls it `deny_always`, and the rule
    // is about the option that writes a standing refusal either way.
    //
    // The words ride after the id, verbatim — a sentence for a reader, so it
    // is not lowercased the way the option id is.
    assert_eq!(
        match_option(&d, "deny_always Use the scratch dir, not /tmp."),
        OptionChoice::One {
            option_id: "deny_always".into(),
            pattern: None,
            note: Some("Use the scratch dir, not /tmp.".into())
        }
    );
    // Bare still answers, and carries nothing rather than claiming a reason.
    assert_eq!(
        match_option(&d, "deny_always"),
        OptionChoice::One {
            option_id: "deny_always".into(),
            pattern: None,
            note: None
        }
    );
    // The two trailing-word options do not borrow each other's field: a glob
    // is a rule and a reason is a sentence, and putting one where the other
    // goes would be a rule nobody wrote or a sentence nobody reads.
    assert_eq!(
        match_option(&d, "allow_always src/**"),
        OptionChoice::One {
            option_id: "allow_always".into(),
            pattern: Some("src/**".into()),
            note: None
        }
    );
    // And everything else still refuses trailing words rather than dropping
    // them.
    assert_eq!(
        match_option(&d, "allow_once because I said so"),
        OptionChoice::Unnamed
    );

    // The card says where to type it, which it never did.
    let a = app();
    assert!(
        a.decision_lines(&d, 100)
            .iter()
            .any(|l| l.contains("`deny_and_tell <why>`")),
        "{:?}",
        a.decision_lines(&d, 100)
    );
    let plain = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    assert!(
        !a.decision_lines(&plain, 100)
            .iter()
            .any(|l| l.contains("deny_and_tell")),
        "and only when the option is on offer"
    );
}

/// The hint only appears when the option it describes is on offer.
#[test]
fn the_glob_hint_is_absent_when_no_rule_can_be_written() {
    use letibot_sessionlog::event::OptionKind;
    let a = app();
    let with = decision_with(&[OptionKind::AllowOnce, OptionKind::AllowAlways]);
    let without = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    assert!(
        a.decision_lines(&with, 100)
            .iter()
            .any(|l| l.contains("allow_always <glob>")),
        "an always-allow on offer says how to scope it"
    );
    assert!(
        !a.decision_lines(&without, 100)
            .iter()
            .any(|l| l.contains("<glob>")),
        "a request with no rule to write must not advertise one"
    );
}

/// **The command is on a line of its own, and the taxonomy is not in front of
/// it.** The operator's report: *"no possible to see wtf was the command i
/// supposed to approve"* — because the summary carried the target inside a
/// sentence, layer A's reading was appended to that sentence, and a long
/// command was then wrapped into the middle of the wall.
#[test]
fn the_command_being_approved_gets_its_own_line() {
    use letibot_sessionlog::event::OptionKind;
    let a = app();
    let mut d = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    let cmd = "cargo test -p letibot-tools --test clauses -- --nocapture";
    d.summary = format!("`bash` wants exec access to `{cmd}`");
    d.target = cmd.to_string();
    d.detail = "ask — intents [execute_code] over [host_other]".into();
    let lines = a.decision_lines(&d, 100);

    // The command, alone on its line, indented — not embedded in the question.
    let own = lines
        .iter()
        .find(|l| l.contains(cmd))
        .unwrap_or_else(|| panic!("the command is not shown at all: {lines:#?}"));
    assert_eq!(own.trim(), cmd, "the command shares its line with prose");

    // The question above it names the tool and the access, and does NOT repeat
    // the command or carry layer A's vocabulary.
    assert!(
        lines[0].contains("`bash` wants exec access"),
        "{}",
        lines[0]
    );
    assert!(
        !lines[0].contains(cmd),
        "the command is back in the headline: {}",
        lines[0]
    );
    assert!(
        !lines[0].contains("intents"),
        "the taxonomy is back on top: {}",
        lines[0]
    );

    // And layer A is still there, under it, for whoever wants it.
    assert!(
        lines.iter().any(|l| l.contains("intents [execute_code]")),
        "the deterministic reading was dropped rather than demoted: {lines:#?}"
    );
}

/// **§11.7: the card says why it is asking, when the declaration is the reason.**
///
/// The card printed two statements that looked like a contradiction — the headline's
/// `wants exec access` (the tool's declared access) and the dim line under it, layer
/// A's reading of the *action* (`auto (a read inside the boundary)`) — and nothing
/// joined them, so *"the classifier decided this needed no asking"* read as being
/// argued with by the card going up anyway. That shape cost three 300-second
/// refusals in one night (`head-parity` R18); the missing clause is the access.
///
/// **And it is absent where the access is not what asks**, which is the half that
/// keeps it worth reading: a `read` call is asked about because of a rule, a path or
/// a mode, so a sentence about its declaration would be false on the very card
/// carrying it. An empty `access` is a daemon older than the field, and the head does
/// not guess.
#[test]
fn the_card_says_the_declared_access_is_what_asks() {
    use letibot_sessionlog::event::OptionKind;
    let a = app();
    let says = |access: &str| {
        let mut d = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
        d.summary = "`bash` wants exec access to `cargo test`".into();
        d.target = "cargo test".into();
        d.detail = "auto — intents [read_file] — auto (a read inside the boundary)".into();
        d.access = access.into();
        a.decision_lines(&d, 200).join("\n")
    };

    let exec = says("exec");
    assert!(exec.contains("the access is what asks"), "{exec}");
    assert!(
        exec.contains("a tool declared to `exec`"),
        "the clause names the declaration the headline already named: {exec}"
    );
    // Under the two statements it joins, because that is what it joins.
    let at_clause = exec.find("the access is what asks").unwrap();
    let at_detail = exec.find("intents [read_file]").unwrap();
    assert!(at_detail < at_clause, "{exec}");
    // …and in their register: evidence beside the question, not a second question.
    let painted = App::new(RenderConfig {
        width: 200,
        color: true,
        ..RenderConfig::default()
    });
    let mut d = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
    d.access = "exec".into();
    let line = painted
        .decision_lines(&d, 200)
        .into_iter()
        .find(|l| l.contains("the access is what asks"))
        .expect("the row");
    assert!(line.contains(sgr::DIM), "not in the dim register: {line:?}");

    // **Absent where the access is not what asks** — a read call, a write call, a
    // network call, and a daemon that did not say.
    for other in ["read", "write", "network", ""] {
        let drawn = says(other);
        assert!(
            !drawn.contains("the access is what asks"),
            "an access of {other:?} is not why anything is being asked: {drawn}"
        );
        // The card is still a card.
        assert!(drawn.contains("allow_once"), "{drawn}");
    }
    // And a question never carries it: nothing is consulted for one, and its `access`
    // is whatever the ask's class happens to be rather than a declaration anyone
    // decided on.
    let mut q = decision_with(&[]);
    q.kind = "question".into();
    q.access = "exec".into();
    q.choices = vec!["a".into()];
    assert!(
        !a.decision_lines(&q, 200)
            .join("\n")
            .contains("the access is what asks"),
        "a question is not a gate and says nothing about declarations"
    );
}

/// A summary some other builder wrote is shown whole rather than mangled: the
/// head takes the target off the end only when the end IS the target.
#[test]
fn a_summary_that_does_not_end_in_its_target_is_left_alone() {
    assert_eq!(
        ask_without_target("`bash` wants exec access to `ls -la`", "ls -la").as_deref(),
        Some("`bash` wants exec access")
    );
    assert_eq!(
        ask_without_target("something else entirely", "ls -la"),
        None
    );
    assert_eq!(
        ask_without_target("`web_search` wants network access", ""),
        None
    );
}

/// **`/cells` sends the rows this head drew, with the operator's message.**
///
/// The model can ask for a screen (`harness what=screen`); this is the other
/// direction, and it is captured at Enter rather than when the turn gets round
/// to it — by then the screen has moved.
#[test]
fn cells_sends_the_screen_with_the_message() {
    let mut a = app();
    // Draw once, so the head has a size and a frame. Nothing is sent before
    // that: an unrendered head has no cells, and an empty block would read as a
    // blank terminal.
    assert!(
        matches!(a.submit("/cells look at this".into()), None),
        "a head that has drawn nothing must refuse rather than send emptiness"
    );
    let _ = a.screen(100, 12);

    let Some(Action::Prompt(text)) = a.submit("/cells look at this".into()) else {
        panic!("/cells did not send");
    };
    assert!(text.starts_with("look at this\n\n"), "{text}");
    assert!(text.contains("100x12"), "the head's real size: {text}");
    // Delimited at both ends, so the model can see where the picture stops.
    assert!(
        text.contains(CELLS_OPEN) && text.contains(CELLS_CLOSE),
        "{text}"
    );

    // And the transcript shows the words plus one line, not the screen again.
    let folded = fold_cells(&text).expect("a cells message folds");
    assert!(folded.starts_with("look at this"), "{folded}");
    assert!(folded.contains("rows of this screen (100x12)"), "{folded}");
    assert!(
        !folded.contains(CELLS_OPEN),
        "the marker leaked into the fold: {folded}"
    );
    assert_eq!(folded.lines().count(), 2, "one message, one note: {folded}");
    // An ordinary message is left exactly alone.
    assert_eq!(fold_cells("just a message"), None);
    // The rows themselves, not a summary of them.
    let drawn = a.screen(100, 12);
    let last = drawn.last().expect("a frame has rows");
    assert!(
        text.contains(last.as_str()),
        "the rows are not in the message"
    );

    // The pending row holds what was SENT, byte for byte — that is what the
    // transcript's user item will match when it lands.
    let echo = a.pending_prompts.last().expect("the message is echoed");
    assert_eq!(echo, &text);
    // And it is DRAWN folded: the operator's words and one line, never a copy
    // of the screen inside the screen.
    // **Unfolded**, because this test is about what the words ARE — the fold's own
    // behaviour is pinned by `an_echo_is_one_elided_headline…` below.
    let drawn = queued_lines(echo, &a.cfg, QUEUED, true);
    assert!(
        drawn.iter().any(|l| l.contains("look at this")),
        "{drawn:#?}"
    );
    assert!(
        drawn.iter().any(|l| l.contains("rows of this screen")),
        "{drawn:#?}"
    );
    assert!(
        drawn.len() < 6,
        "the queued row is painting the whole screen: {} lines",
        drawn.len()
    );
}

fn path_fixture() -> std::path::PathBuf {
    static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let d = std::env::temp_dir().join(format!(
        "lb-paths-{}-{}",
        std::process::id(),
        SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
    ));
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(d.join("stroppy/build")).unwrap();
    std::fs::write(d.join("stroppy/build/stroppy"), "").unwrap();
    std::fs::write(d.join("README.md"), "").unwrap();
    std::fs::write(d.join("README.old"), "").unwrap();
    std::fs::write(d.join(".hidden"), "").unwrap();
    std::fs::write(d.join("my file.txt"), "").unwrap();
    d
}

/// **A `!` line's word completes as a file name**, the way a shell's does — the
/// operator's `! ./stroppy/build/stroppy`, typed out whole because nothing offered it.
#[test]
fn a_bang_lines_word_completes_against_the_workspace() {
    let d = path_fixture();
    let ws = d.to_str().unwrap();
    let line = |t: &str| complete_path_word(t, ws);
    // A path in command position: one directory, then the next, then the file.
    assert_eq!(
        line("! ./st"),
        Some(PathCompletion::Line("! ./stroppy/".into()))
    );
    assert_eq!(
        line("! ./stroppy/build/st"),
        Some(PathCompletion::Line("! ./stroppy/build/stroppy ".into()))
    );
    // An argument completes as a file; two matches extend to what they share.
    match line("! cat REA") {
        Some(PathCompletion::Choices { line, names }) => {
            assert_eq!(line, "! cat README.");
            assert_eq!(names, vec!["README.md".to_string(), "README.old".into()]);
        }
        other => panic!("{other:?}"),
    }
    // A space in a name is escaped, as a shell would need it.
    assert_eq!(
        line("! cat my"),
        Some(PathCompletion::Line("! cat my\\ file.txt ".into()))
    );
    // Hidden names only when asked for.
    assert_eq!(
        line("! cat .hi"),
        Some(PathCompletion::Line("! cat .hidden ".into()))
    );
    assert!(
        matches!(line("! ls "), Some(PathCompletion::Choices { names, .. }) if !names.iter().any(|n| n.starts_with('.')))
    );
    // The command word, spelled as a word, is the history's to complete, not a file's.
    assert_eq!(line("! REA"), None);
    // Nothing matches, a quote or a `$` in the word: left to the line completions.
    assert_eq!(line("! cat zzz"), None);
    assert_eq!(line("! cat \"REA"), None);
    assert_eq!(line("! cat $HO"), None);
    let _ = std::fs::remove_dir_all(&d);
}

/// The same, through the keys: Tab completes the composer, and the choices are drawn
/// in the completion row while the line is unchanged.
#[test]
fn tab_on_a_bang_line_completes_the_path_and_shows_the_choices() {
    let d = path_fixture();
    let mut a = app();
    a.wiring.workspace = d.to_str().unwrap().into();
    typed(&mut a, "! cat ./stro");
    a.key(Key::Tab);
    assert_eq!(a.input(), "! cat ./stroppy/");
    a.key(Key::Tab);
    assert_eq!(a.input(), "! cat ./stroppy/build/");
    let mut b = app();
    b.wiring.workspace = d.to_str().unwrap().into();
    typed(&mut b, "! cat REA");
    b.key(Key::Tab);
    assert_eq!(b.input(), "! cat README.");
    let screen = b.screen(100, 20).join("\n");
    assert!(
        screen.contains("README.md") && screen.contains("README.old"),
        "{screen}"
    );
    let _ = std::fs::remove_dir_all(&d);
}

/// **The window title is the session's name and the folder**, follows a rename, falls
/// back to the short id for an untitled session, and carries no control character from
/// a hostile title — the terminal would execute it.
#[test]
fn the_window_title_names_the_session_and_follows_a_rename() {
    let mut a = app();
    assert_eq!(
        a.window_title(),
        "letibot",
        "before a session there is only the program"
    );
    a.apply(hello(
        "s-1791387240666068000",
        vec![brief("s-1791387240666068000", "", false)],
        Hub::new("s-1791387240666068000").snapshot(),
    ));
    // After the hello, which carries the daemon's own workspace.
    a.wiring.workspace = "/Users/dead/Projects/thing".into();
    let untitled = a.window_title();
    assert!(
        untitled.starts_with("thing · "),
        "the folder leads until there is a name: {untitled}"
    );
    assert!(!untitled.contains("leticode"), "{untitled}");
    a.apply(ServerFrame::Event(env(
        1,
        SessionEvent::SessionRenamed {
            title: "port the parser".into(),
        },
    )));
    assert_eq!(a.window_title(), "port the parser · thing");
    a.apply(ServerFrame::Event(env(
        2,
        SessionEvent::SessionRenamed {
            title: "evil\u{1b}]0;pwned\u{7}\u{9b}31m title".into(),
        },
    )));
    let written = crate::backend::terminal::window_title_text(&a.window_title());
    assert!(
        !written.chars().any(|c| c.is_control()),
        "a control character would reach the terminal: {written:?}"
    );
    assert!(written.starts_with("evil]0;pwned"), "{written:?}");
}

#[test]
fn queued_prompts_behind_a_running_turn_are_one_message() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "also fix the parser");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::Prompt("also fix the parser".into()))
    );
    typed(&mut a, "and add a test for it");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::Prompt("and add a test for it".into()))
    );
    assert_eq!(
        a.pending_prompts,
        vec!["also fix the parser\nand add a test for it".to_string()],
        "one echo, the way the engine holds one message"
    );
    // Idle submits land each as their own row within a tick, so they stay
    // separate entries.
    a.apply(ServerFrame::Event(env(2, testing::turn_finished("t1"))));
    typed(&mut a, "fresh question");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::Prompt("fresh question".into()))
    );
    assert_eq!(a.pending_prompts.len(), 2);
}

/// **The shape that actually happens on this box, and it retired nothing.**
///
/// Measured 2026-09-23 on the live head: six `queued ·` echoes, one per paragraph
/// of the R27 instruction, every one of them answered — and the row that answered
/// them was their JOIN. Six sends while the head did not think a turn was running
/// became six separate entries (`App::submit`'s coalescing is conditional on the head
/// thinking a turn is RUNNING, which is `turn_busy`'s question — see it for why the state
/// name was the wrong instrument), the engine merged them into ONE user item joined by
/// newlines, and against a whole-string rule every comparison was *no*.
///
/// Then the seventh thing: the operator's next message was sent while a turn WAS
/// running, so the head appended it to the last entry — making an entry that is a
/// *superset* of one row and a *prefix* of another. Every one of these three shapes
/// is here, in one test, against the text lengths the real session had.
#[test]
fn the_engine_join_of_several_prompts_retires_every_echo_it_answered() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // The first six: idle submits (the turn state is not Running), so they stay
    // separate entries.
    let six = [
        "THE OPERATOR'S RULING, and it came with a split",
        "My reasoning for why that split is right",
        "One consequence to build in rather than discover",
        "What is still yours to rule",
        "And two corrections you owe your own documentation",
        "Finally, one thing I did NOT establish",
    ];
    for p in six {
        typed(&mut a, p);
        a.key(Key::Enter);
    }
    assert_eq!(a.pending_prompts.len(), 6, "one entry per send");

    // Then a seventh send while the turn IS running: the head joins it onto the
    // last entry, which is the whole reason one entry can be a superset of one
    // row and a prefix of another.
    a.apply(ServerFrame::Event(env(2, testing::turn_started("t2"))));
    let seventh = "The operator is looking at six queued echoes";
    typed(&mut a, seventh);
    a.key(Key::Enter);
    assert_eq!(a.pending_prompts.len(), 6, "joined, not pushed");
    assert_eq!(
        a.pending_prompts[5],
        format!("{}\n{seventh}", six[5]),
        "the last entry is the sixth prompt with the seventh under it"
    );

    // The row the six landed as: the engine's join, one item, six lines.
    a.record_item(
        "s.0",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: six.join("\n"),
            }],
        },
    );
    assert_eq!(
        a.pending_prompts,
        vec![seventh.to_string()],
        "all six are answered by that one row; only the seventh is still owed"
    );

    // And the seventh's own row, which is where its echo goes.
    a.record_item(
        "s.1",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: seventh.to_string(),
            }],
        },
    );
    assert!(
        a.pending_prompts.is_empty(),
        "every echo is retired: {:?}",
        a.pending_prompts
    );

    // The screen agrees — no `queued` tag left anywhere.
    let screen = a.screen(120, 40).join("\n");
    assert!(!screen.contains("queued"), "{screen}");
}

/// **The negative assertion: a prompt is not retired by a row that merely
/// CONTAINS it.**
///
/// This is the failure that matters, and it is the one the whole-line rule
/// exists against. leticl's wording: a prompt `second thing` must not be retired
/// by a row reading `first thing\nsecond thing-guess`, or the head swallows a
/// prompt the daemon has not answered — the operator's sentence, gone from the
/// screen with nothing else holding it.
///
/// Three ways to be *contained but not a line*, because they fail differently: a
/// row that continues the echo's text, a row that precedes it, and a row that
/// holds the echo's words inside one longer line.
#[test]
fn a_row_that_only_contains_the_prompt_does_not_retire_it() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // **No turn**, deliberately: `App::submit` joins consecutive sends onto one
    // entry only while it thinks a turn is running, and these two have to be two
    // entries for the rule under test to be about matching and not about joining.
    typed(&mut a, "second thing");
    a.key(Key::Enter);
    typed(&mut a, "fourth thing");
    a.key(Key::Enter);
    assert_eq!(a.pending_prompts.len(), 2, "two entries, two sends");

    for row in [
        // The echo is the FIRST LINE of a longer row: contained, not a line.
        "second thing-guess\nand another line",
        // The echo is preceded by other text in the same line.
        "first thing\nsecond thing and more",
        // The echo's words are inside one longer line.
        "first thing\nprefixed second thing suffixed",
    ] {
        a.record_item(
            "s.contains",
            TranscriptItem::User {
                speaker: Default::default(),
                parts: vec![UserPart::Text { text: row.into() }],
            },
        );
        assert_eq!(
            a.pending_prompts,
            vec!["second thing".to_string(), "fourth thing".to_string()],
            "`{row}` contains the echo and did not answer it"
        );
    }

    // And the answer that IS one — a whole line — retires exactly that one.
    a.record_item(
        "s.4",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "something else\nsecond thing".into(),
            }],
        },
    );
    assert_eq!(
        a.pending_prompts,
        vec!["fourth thing".to_string()],
        "the second is a whole line of that row, so it landed"
    );
}

/// **R33: an echo is ONE elided headline, and the usual key opens it.**
///
/// The operator, looking at letibot with three of their own messages queued:
/// *"three giant messages queued"* — a 63-row pane filled with the reader's own words,
/// the conversation pushed off the screen. *"It is a thing waiting, not content to
/// read — the reader wrote it and does not need it read back."*
///
/// The unit of the count is **screen rows**, not source lines, because that is what
/// the reader is paying: the model writes one enormous paragraph, and `+0 lines`
/// beside a row that fills the pane answers the wrong question.
#[test]
fn an_echo_is_one_elided_headline_until_it_is_unfolded() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // A message the length of the R31 instruction: 30 lines, ~9.6k characters — the
    // real row that filled the operator's pane.
    let long: String = (0..30)
        .map(|i| format!("paragraph {i} {}", "word ".repeat(40)))
        .collect::<Vec<_>>()
        .join("\n");
    typed(&mut a, &long);
    a.key(Key::Enter);

    let rows = a.screen(120, 60);
    let echo: Vec<&String> = rows
        .iter()
        .filter(|l| l.contains("queued ·") || l.contains("… +"))
        .collect();
    assert_eq!(echo.len(), 1, "the echo is one row, not thirty: {rows:#?}");
    assert!(echo[0].contains("queued · paragraph 0"), "{echo:?}");
    assert!(
        echo[0].contains("· /t opens it"),
        "the seam names the key that opens it: {echo:?}"
    );
    assert!(
        a.pending_prompts[0].starts_with("paragraph 0"),
        "the queue holds the words, not the rendering"
    );
    assert_eq!(
        a.pending_prompts[0], long,
        "byte for byte: the fold is a rendering and nothing else"
    );

    // **And the usual key opens it.** `/t` is this head's unfold-the-long-rows verb;
    // a reader who wants the long things shown whole asks once.
    a.command("t");
    let open = a.screen(120, 200);
    assert!(
        open.iter().filter(|l| l.contains("paragraph 29")).count() >= 1,
        "`/t` must show the rest of it"
    );
    assert!(
        !open.iter().any(|l| l.contains("/t opens it")),
        "and the seam goes with it"
    );
    assert_eq!(a.pending_prompts[0], long, "still byte for byte");
}

/// **A short echo is one row with no seam at all**, because there is nothing hidden —
/// a row carrying `… +0 lines` would be furniture.
#[test]
fn a_short_echo_has_no_seam() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    typed(&mut a, "a short one");
    a.key(Key::Enter);
    let rows = a.screen(120, 40);
    assert!(
        rows.iter().any(|l| l.contains("queued · a short one")),
        "{rows:#?}"
    );
    assert!(
        !rows.iter().any(|l| l.contains("opens it")),
        "nothing is hidden, so nothing is claimed: {rows:#?}"
    );
}

/// **An echo queued AFTER the snapshot keeps saying `queued`.**
///
/// The mark is not a property of the session or of the text — it is a property of one
/// echo's history, and a prompt typed after the snapshot has a row coming that no
/// snapshot has replaced. Marking by time-of-load rather than per echo would take the
/// honest word away from every prompt the operator sends next.
#[test]
fn an_echo_queued_after_the_snapshot_still_says_queued() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    typed(&mut a, "before the snapshot");
    a.key(Key::Enter);
    // A resync whose rows do not carry it.
    let mut snap = Hub::new("s").snapshot();
    snap.seq = 9;
    a.apply(hello("s", vec![brief("s", "one", false)], snap));
    assert_eq!(a.unconfirmed, vec!["before the snapshot".to_string()]);

    // Now one sent after.
    typed(&mut a, "after the snapshot");
    a.key(Key::Enter);
    assert_eq!(
        a.unconfirmed,
        vec!["before the snapshot".to_string()],
        "the new echo is not marked by a snapshot that predates it"
    );
    let screen = a.screen(140, 30).join("\n");
    assert!(
        screen.contains("unconfirmed · before the snapshot"),
        "{screen}"
    );
    assert!(screen.contains("queued · after the snapshot"), "{screen}");
}

/// **An unconfirmed echo whose row lands INSIDE A MERGED ITEM leaves the set.**
///
/// This is the leak leticl measured on its own head, and the structural reason is the
/// same here: the set is keyed by the echo's text and the landing row's text is the
/// engine's JOIN, so `unconfirmed` could never be cleared by comparing texts. It wants
/// an **intersection** — keep the marks whose echo is still in the queue — which is
/// what `retire_pending` now does, and the first version of this fix got the
/// intersection's TIMING wrong (before the loop rather than after), which is the same
/// leak with the opposite sign. Both are pinned here.
#[test]
fn an_unconfirmed_echo_retires_when_its_row_lands_inside_a_merged_item() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    typed(&mut a, "one of mine");
    a.key(Key::Enter);
    typed(&mut a, "and another");
    a.key(Key::Enter);
    // A snapshot that carries neither, so both are unconfirmed.
    let mut snap = Hub::new("s").snapshot();
    snap.seq = 4;
    a.apply(hello("s", vec![brief("s", "one", false)], snap));
    assert_eq!(a.unconfirmed.len(), 2, "{:?}", a.unconfirmed);

    // **The row that lands is the JOIN of both**, which is what the engine appends
    // for consecutive queued prompts.
    a.record_item(
        "s.0",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "one of mine\nand another".into(),
            }],
        },
    );
    assert!(a.pending_prompts.is_empty(), "{:?}", a.pending_prompts);
    assert!(
        a.unconfirmed.is_empty(),
        "a mark outlived the echo it was on: {:?}",
        a.unconfirmed
    );
}

/// **The live path and the snapshot path retire the same things.**
///
/// `App::record_item` read only the FIRST text part while `App::load` read every one,
/// so the same row could stand down one echo on one path and not the other — leticl
/// measured exactly this on its own head (*"the live arm read only the FIRST text part
/// where the snapshot path reads every part"*). Two ways into one rule is two rules;
/// this is the assertion that they are one.
#[test]
fn the_live_and_snapshot_paths_retire_the_same_echoes() {
    // Two echoes, so the two paths can differ about one without the whole thing
    // passing.
    let setup = || {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        typed(&mut a, "first of mine");
        a.key(Key::Enter);
        typed(&mut a, "second of mine");
        a.key(Key::Enter);
        a
    };
    let row = || TranscriptItem::User {
        speaker: Default::default(),
        parts: vec![UserPart::Text {
            text: "first of mine\nsecond of mine".into(),
        }],
    };

    let mut live = setup();
    live.record_item("s.0", row());
    let mut snap = setup();
    let mut s = Hub::new("s").snapshot();
    s.seq = 3;
    s.items.push(letibot_sessionlog::view::SnapshotItem {
        item_id: "s.0".into(),
        kind: "user".into(),
        ledger_head: "beef".into(),
        ts: 0,
        item: Some(row()),
    });
    snap.apply(hello("s", vec![brief("s", "one", false)], s));

    assert_eq!(
        live.pending_prompts, snap.pending_prompts,
        "the two paths disagreed about what a row answered"
    );
    assert!(
        live.pending_prompts.is_empty(),
        "{:?}",
        live.pending_prompts
    );
}

/// **A line is spent once**, which is the property the old equality rule gave
/// and which a rule that retires every matching entry would lose: two prompts that
/// say the same thing stay queued separately until each of their rows lands.
#[test]
fn one_row_does_not_retire_two_identical_prompts() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // No turn: see the note in the test above about the head's own joining.
    typed(&mut a, "say it twice");
    a.key(Key::Enter);
    typed(&mut a, "say it twice");
    a.key(Key::Enter);
    assert_eq!(a.pending_prompts.len(), 2);
    a.record_item(
        "s.0",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "say it twice".into(),
            }],
        },
    );
    assert_eq!(
        a.pending_prompts,
        vec!["say it twice".to_string()],
        "one landing row answers one of the two"
    );
}

/// **A blank line is not a claim.** A piece that is empty carries no words, so it
/// cannot say whether a prompt landed — and a row of blank lines must not retire
/// the queue by matching them.
#[test]
fn blank_lines_claim_nothing() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "a real prompt");
    a.key(Key::Enter);
    a.record_item(
        "s.0",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "\n\n\n".into(),
            }],
        },
    );
    assert_eq!(a.pending_prompts, vec!["a real prompt".to_string()]);
}

/// The piece arithmetic itself, where it is easier to read than through an `App`.
#[test]
fn strip_landed_reads_lines_not_strings() {
    fn go(entry: &str, row: &str) -> Option<String> {
        let lines: Vec<&str> = row.split('\n').collect();
        let mut claimed = vec![false; lines.len()];
        let mut cursor = 0;
        strip_landed(entry, &lines, &mut claimed, &mut cursor)
    }
    // Equality, by lines.
    assert_eq!(go("one", "one"), Some(String::new()));
    assert_eq!(go("one\ntwo", "one\ntwo"), Some(String::new()));
    // The row is the front run of the echo.
    assert_eq!(go("one\ntwo", "one"), Some("two".into()));
    // The row is a middle and a tail run.
    assert_eq!(go("one\ntwo\nthree", "two\nthree"), Some("one".into()));
    // Contained but not a line: untouched, every one of them.
    assert_eq!(go("two", "one\ntwo-guess"), None);
    assert_eq!(go("two", "one\nxtwo x"), None);
    assert_eq!(go("two", "one\ntwo is a longer line"), None);
    // A blank piece claims nothing, so an echo of blank lines is not retired by
    // a row of blank lines.
    assert_eq!(go("\n", "\n\n"), None);
}

#[test]
fn up_recalls_the_queued_line_for_editing_and_takes_it_back() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "also fix the parser");
    a.key(Key::Enter);
    typed(&mut a, "and add a test for it");
    a.key(Key::Enter);
    assert_eq!(a.pending_prompts.len(), 1);
    // Up with an empty composer: the queue comes back, the take-back rides.
    assert_eq!(a.key(Key::Up), Some(Action::WithdrawPrompts));
    assert_eq!(a.input(), "also fix the parser\nand add a test for it");
    assert!(a.pending_prompts.is_empty(), "recalled, not held");
    // The operator edits and sends; the edited line queues fresh, and the
    // daemon's take-back means it replaces the original rather than
    // stacking onto it.
    typed(&mut a, " — no, just the parser");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::Prompt(
            "also fix the parser\nand add a test for it — no, just the parser".into()
        ))
    );
    assert_eq!(a.pending_prompts.len(), 1);
}

#[test]
fn up_with_a_half_typed_line_still_belongs_to_the_editor() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "queued one");
    a.key(Key::Enter);
    typed(&mut a, "half a thought");
    assert_eq!(a.key(Key::Up), None, "the editor keeps its own Up");
    // What the editor does with it is the editor's own readline semantics,
    // unchanged here: Up at the top row walks its submitted-line history,
    // which replaces the half-typed line — same as main, same as any shell.
    // The queue's part in this is only the negative one: no take-back rode
    // along, and the mirror still holds what the daemon still holds.
    assert_eq!(a.input(), "queued one");
    assert_eq!(a.pending_prompts.len(), 1, "the queue is untouched");
}

#[test]
fn a_landing_row_retires_its_echo_and_a_piece_strips_the_front() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "first");
    a.key(Key::Enter);
    typed(&mut a, "second");
    a.key(Key::Enter);
    assert_eq!(a.pending_prompts, vec!["first\nsecond".to_string()]);
    // The whole coalesced message lands: the echo stands down whole.
    a.record_item(
        "s.0",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "first\nsecond".into(),
            }],
        },
    );
    assert!(a.pending_prompts.is_empty());
    // A notice split the run, so the pieces land around it: the front piece
    // strips itself off the echo, the rest waits for its own row.
    typed(&mut a, "third");
    a.key(Key::Enter);
    typed(&mut a, "fourth");
    a.key(Key::Enter);
    a.record_item(
        "s.1",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "third".into(),
            }],
        },
    );
    assert_eq!(a.pending_prompts, vec!["fourth".to_string()]);
    a.record_item(
        "s.2",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "fourth".into(),
            }],
        },
    );
    assert!(a.pending_prompts.is_empty());
}

/// **The waiting words sit below the working, and move up when the daemon takes them** — two
/// operator reports, and they are the two halves of one rule.
///
/// *"queued above thinking"* (their screen, 2026-10-05) is the half that was wrong. Their
/// words, and directly under them the running turn's reasoning — and nothing answers those
/// words, because the daemon has not been given them, so nothing under them may look like an
/// answer. While nothing has taken them they belong at the tail, and the reply to the
/// PREVIOUS prompt is above them, where it belongs.
///
/// *"a message was queued to harnessd, delivered to model, reply started streaming above the
/// queued message and then some tick goes off and queued message dequeued and rendered
/// rightfully above the reply. pure ui desync."* is the half that must not come back — and it
/// is why the move happens at the moment the daemon TAKES the words: from then on the echo is
/// above the pane by construction, so no reply to it can appear over it.
///
/// **The move is asserted as a move, because the move is the ruling.** What is deliberately
/// not asserted is that the frame is the same frame — it is not, and it must not be: the two
/// facts are different facts, and the frame is the one place that says which one holds.
#[test]
fn a_queued_echo_waits_below_the_working_until_the_daemon_takes_it() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    // The reply starts streaming FIRST, which is the latency the whole defect is about:
    // `Delta` carries its text and `TranscriptAppended` carries only an id.
    a.apply(ServerFrame::Event(env(
        2,
        testing::delta("t1", "R2 the reply being streamed now"),
    )));
    typed(&mut a, "Q2 the message queued mid-turn");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::Prompt("Q2 the message queued mid-turn".into()))
    );
    let before = a.screen(100, 24);
    let before_text = before.join("\n");
    assert!(
        before_text.contains("▌ queued · Q2 the message queued mid-turn"),
        "{before_text}"
    );
    let echo = before
        .iter()
        .position(|l| l.contains("queued · Q2 the message"))
        .expect("the echo is on the screen");
    let reply = before
        .iter()
        .position(|l| l.contains("R2 the reply"))
        .expect("the reply is on the screen");
    assert!(
        reply < echo,
        "**the waiting words are BELOW the working**: the daemon has not taken them, so the \
             reply to the PREVIOUS prompt must not read as an answer to them — and the operator read \
             exactly that as *queued above thinking*:\n{before_text}"
    );

    // The daemon appends the row at its step boundary and announces it.
    a.apply(ServerFrame::Event(env(3, testing::appended("s.9", "user"))));
    let after = a.screen(100, 24);
    let after_text = after.join("\n");
    assert!(
        after_text.contains("▌ Q2 the message queued mid-turn"),
        "the row is drawn in the echo's place, from the words the head already had: \
             {after_text}"
    );
    // **And it no longer claims to be queued.** This assertion used to be `before == after` —
    // *not one row changes across the announcement* — and that was true only while the bound
    // row wore the same `queued` mark as the echo, which is the very thing R2 forbids: the
    // daemon had the words and the model could already be answering them. The rows beneath do
    // not move; the mark does, because the row has landed. The operator's own order, which is
    // what this test now pins: *"my message | your line | and only then unqueued."*
    assert!(
        // The MARK, not the word: this fixture's own message text contains *queued*, so a
        // bare `contains("queued")` would pass on the words and say nothing about the label.
        !after_text.contains("▌ queued · ") && !after_text.contains("▌ unconfirmed · "),
        "the announced row still carries a queued claim: {after_text}"
    );
    // **And the move is the ruling.** From this moment the words are above the reply, which is
    // the half of the report that must not come back: *"reply started streaming above the
    // queued message … pure ui desync."*
    let words_after = after
        .iter()
        .position(|l| l.contains("Q2 the message"))
        .expect("the words are on the screen");
    let reply_after = after
        .iter()
        .position(|l| l.contains("R2 the reply"))
        .expect("the reply is on the screen");
    assert!(
        words_after < reply_after,
        "once the daemon has taken the words they sit ABOVE the reply, so no reply to them can \
             appear over them:\n{after_text}"
    );
    // **The move is a move and not a second drawing.** Whatever else changes, the reader's own
    // sentence is on the screen exactly once, in each frame.
    assert_eq!(
        before_text.matches("Q2 the message").count(),
        1,
        "{before_text}"
    );
    assert_eq!(
        after_text.matches("Q2 the message").count(),
        1,
        "{after_text}"
    );
}

/// **The prompt is on the screen before the reply to it — requirement R2.**
///
/// Two channels with different latencies. Assistant text arrives as `Delta`,
/// carrying its text, and renders as it streams; a user row arrives as
/// `TranscriptAppended` — an id and a kind, **no text** — and only later as
/// `TranscriptContent`. So the reply is always faster to display than the prompt
/// that caused it: the operator watched their own sentence sit under the answer
/// to it, tagged `queued`, and then jump above it when the body finally landed.
///
/// The row is drawn from the echo the head already holds, in the row's own place,
/// from the announcement.
#[test]
fn a_queued_prompt_is_drawn_in_the_transcript_the_moment_its_row_is_announced() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "also fix the parser");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::Prompt("also fix the parser".into()))
    );
    // Before anything lands: the echo, tagged as what it is.
    let screen = a.screen(100, 24).join("\n");
    assert!(screen.contains("queued · also fix the parser"), "{screen}");

    // The daemon appends the row at its step boundary and announces it. No text
    // on the event — the head's own echo is all there is.
    a.apply(ServerFrame::Event(env(2, testing::appended("s.9", "user"))));
    // And the model's reply starts streaming, which is what used to reach the
    // screen first.
    a.apply(ServerFrame::Event(env(
        3,
        testing::delta("t1", "I'll fix the parser."),
    )));

    let screen = a.screen(100, 24).join("\n");
    let prompt = screen
        .find("also fix the parser")
        .unwrap_or_else(|| panic!("the prompt is not on the screen: {screen}"));
    let reply = screen
        .find("I'll fix the parser")
        .unwrap_or_else(|| panic!("the reply is not on the screen: {screen}"));
    assert!(
        prompt < reply,
        "the reply is above the prompt that caused it: {screen}"
    );
    // **And once.** The row is carrying the words now, so the tail echo must not
    // draw them a second time.
    assert_eq!(
        screen.matches("also fix the parser").count(),
        1,
        "the prompt is on the screen twice: {screen}"
    );

    // The body arrives and confirms the binding: the row becomes a settled user
    // block, in place, and the echo goes with it.
    a.apply(ServerFrame::Event(env(
        4,
        testing::content("s.9", "also fix the parser"),
    )));
    assert!(
        a.pending_prompts.is_empty(),
        "confirmed, so the echo retires"
    );
    assert!(a.bound_prompts.is_empty(), "and the binding is spent");
    let screen = a.screen(100, 24).join("\n");
    assert!(
        !screen.contains("queued"),
        "the row is settled and still says queued: {screen}"
    );
    assert_eq!(screen.matches("also fix the parser").count(), 1, "{screen}");
    // Still above the reply, now from its own body.
    assert!(
        screen.find("also fix the parser").unwrap() < screen.find("I'll fix the parser").unwrap(),
        "{screen}"
    );
}

/// **Not every announced `User` row is this head's prompt — the hazard.**
///
/// A harness steering notice and a §5.7 salvage notice are the same item shape as
/// a prompt (`harnessd::harness` says so in as many words), and so is another
/// attached head's prompt. The announcement carries nothing that tells them apart,
/// so the binding is a guess and **the retire waits for content matched by text**:
/// a head that retired on the announcement would lose the echo of a prompt still
/// sitting in the hub's queue, and the operator would watch their own sentence
/// vanish off the screen.
#[test]
fn a_notice_announced_while_a_prompt_is_queued_does_not_retire_its_echo() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "also fix the parser");
    a.key(Key::Enter);

    // A steering notice is appended — the SAME shape as a prompt, and it steals
    // the optimistic binding, because the announcement cannot say it is not ours.
    a.apply(ServerFrame::Event(env(2, testing::appended("s.9", "user"))));
    assert!(
        a.bound_prompts.contains_key("s.9"),
        "the guess is made; there is nothing else to guess from"
    );
    // Content arrives and contradicts it: this row was never this head's words.
    a.apply(ServerFrame::Event(env(
        3,
        testing::content("s.9", "the spec changed - RFC 2812 rather than 1459"),
    )));
    assert_eq!(
        a.pending_prompts,
        vec!["also fix the parser".to_string()],
        "the announcement retired an echo whose prompt is still queued"
    );
    assert!(a.bound_prompts.is_empty(), "the wrong guess is dropped");
    // And both correct themselves: the notice renders from its own content, and
    // the operator's words are back at the tail, still saying `queued`, which is
    // still true.
    let screen = a.screen(100, 24).join("\n");
    assert!(screen.contains("RFC 2812"), "{screen}");
    assert!(
        screen.contains("queued · also fix the parser"),
        "the operator's own words left the screen: {screen}"
    );
    assert_eq!(screen.matches("also fix the parser").count(), 1, "{screen}");
}

/// **Two prompts in the air bind two rows, in the order they were sent.**
///
/// Oldest-first, and never an echo already bound: two rows announced while both
/// are queued must not both wear the first prompt's words. Idle submits land each
/// as their own entry (`queued_prompts_behind_a_running_turn_are_one_message`
/// covers the coalesced case), and both rows are in flight until their bodies
/// arrive.
#[test]
fn two_queued_prompts_bind_the_two_announcements_in_order() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    typed(&mut a, "first");
    a.key(Key::Enter);
    typed(&mut a, "second");
    a.key(Key::Enter);
    assert_eq!(
        a.pending_prompts,
        vec!["first".to_string(), "second".to_string()]
    );

    a.apply(ServerFrame::Event(env(
        1,
        testing::appended("s.10", "user"),
    )));
    a.apply(ServerFrame::Event(env(
        2,
        testing::appended("s.11", "user"),
    )));
    assert_eq!(
        a.bound_prompts.get("s.10").map(String::as_str),
        Some("first")
    );
    assert_eq!(
        a.bound_prompts.get("s.11").map(String::as_str),
        Some("second")
    );
    let screen = a.screen(100, 24).join("\n");
    // **Both rows are on the screen and neither claims to be queued** — they were announced, so
    // what the head owes is their bodies, not their rows. See [`echo_mark`]. The assertion this
    // replaces counted `queued · first` and `queued · second`, which was true only while a bound
    // row wore the echo's own mark.
    assert_eq!(screen.matches("▌ first").count(), 1, "{screen}");
    assert_eq!(screen.matches("▌ second").count(), 1, "{screen}");
    assert!(
        !screen.contains("▌ queued · "),
        "an announced row still claims to be queued: {screen}"
    );
    assert!(
        screen.find("first").unwrap() < screen.find("second").unwrap(),
        "the rows are drawn in the order they were announced: {screen}"
    );
}

/// **A binding dies with the row it was for.** A snapshot replaces every row, and
/// a binding whose row is gone has nothing left to stand for — otherwise the echo
/// would be suppressed at the tail for ever, on the strength of a row nobody has
/// any more.
#[test]
fn a_snapshot_keeps_only_the_bindings_whose_rows_are_still_bodyless() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    typed(&mut a, "still queued");
    a.key(Key::Enter);
    a.apply(ServerFrame::Event(env(2, testing::appended("s.9", "user"))));
    assert!(a.bound_prompts.contains_key("s.9"));

    // A resync of the same session whose rows do not include that one.
    let mut snap = Hub::new("s").snapshot();
    snap.seq = 5;
    snap.items.push(letibot_sessionlog::view::SnapshotItem {
        item_id: "s.10".into(),
        kind: "user".into(),
        ledger_head: "beef".into(),
        ts: 0,
        item: Some(TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "from the snapshot".into(),
            }],
        }),
    });
    a.apply(hello("s", vec![brief("s", "one", false)], snap));
    assert!(
        a.bound_prompts.is_empty(),
        "a row that is gone takes its guess with it"
    );
    assert_eq!(
        a.pending_prompts,
        vec!["still queued".to_string()],
        "and the words are still this head's to show"
    );
    let screen = a.screen(100, 24).join("\n");
    assert!(
        screen.contains("still queued"),
        "the echo is suppressed by a binding nothing can see: {screen}"
    );
    // **And it says `unconfirmed`, not `queued`** — R16's third mark.
    //
    // This test WAS the case the mark is for, and it asserted the wrong word until
    // the mark existed: a snapshot arrived, it did not carry this echo's row, and the
    // head went on saying *queued* — a claim about the daemon's queue that it can no
    // longer support, because it cannot tell *still coming* from *replaced by a fork*.
    // The operator, from leticl's screen and true here: an echo the head cannot resolve
    // must stop saying `queued`, *"which is a claim the head can actually support"*.
    assert!(
        screen.contains("unconfirmed · still queued"),
        "a snapshot that does not carry the row must stop claiming the daemon owes it: \
             {screen}"
    );
    assert_eq!(a.unconfirmed, vec!["still queued".to_string()]);

    // **And it retires the ordinary way when its row does land**, taking its mark
    // with it — the intersection. `unconfirmed` is a mark ON an echo, not a copy of
    // its text, so an echo that stands down must not leave the mark behind for ever.
    a.record_item(
        "s.11",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "still queued".into(),
            }],
        },
    );
    assert!(a.pending_prompts.is_empty());
    assert!(
        a.unconfirmed.is_empty(),
        "the mark outlived the echo it was on: {:?}",
        a.unconfirmed
    );
}

/// **R37: `Conversation` is the conversation and nothing the head did to produce it.**
///
/// The operator: *"and i want a special mode that hides tool calls and thinking
/// completely."* Measured before it was built: the ladder's bottom rung was `Terse`,
/// *"assistant text and tool outcomes only"* — so **terse still drew every tool row**, and
/// there was no rung that gave the conversation alone.
///
/// Asserted as a difference against `Terse` rather than as a list, because the list is
/// what a later edit forgets: the same fixture is drawn twice, once per rung, and what is
/// gone is exactly the working.
#[test]
fn the_conversation_rung_shows_the_conversation_and_nothing_else() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // One exchange of each kind: the operator's words, the model's answer, its reasoning,
    // a tool call with its result, and a head arrival.
    for (seq, event) in [
        (1, testing::appended("s.0", "user")),
        (2, testing::content("s.0", "please read the file")),
        (
            3,
            SessionEvent::TranscriptAppended {
                item_id: "s.1".into(),
                kind: "reasoning".into(),
                ledger_head: String::new(),
            },
        ),
        (
            4,
            SessionEvent::TranscriptContent {
                item_id: "s.1".into(),
                item: Box::new(letibot_transcript::TranscriptItem::Reasoning {
                    text: "I should look at the file first".into(),
                    field: letibot_transcript::ReasoningField::ReasoningContent,
                    truncated: false,
                }),
            },
        ),
        (5, testing::appended("s.2", "assistant")),
        (
            6,
            SessionEvent::TranscriptContent {
                item_id: "s.2".into(),
                item: Box::new(letibot_transcript::TranscriptItem::Assistant {
                    text: "the file says a thing".into(),
                    tool_calls: Vec::new(),
                    truncated: false,
                }),
            },
        ),
        (7, testing::appended("s.3", "tool_result")),
        (
            8,
            SessionEvent::TranscriptContent {
                item_id: "s.3".into(),
                item: Box::new(letibot_transcript::TranscriptItem::ToolResult {
                    call_id: "c1".into(),
                    name: "bash".into(),
                    outcome: letibot_transcript::ToolOutcome::Ok,
                    payload: "MAGIC-TOOL-PAYLOAD".into(),
                    edit: None,
                    origin: None,
                    media: None,
                }),
            },
        ),
        (
            9,
            SessionEvent::HeadAttached {
                head_id: "h2".into(),
                kind: "tui".into(),
                identity: "somebody".into(),
            },
        ),
    ] {
        a.apply(ServerFrame::Event(env(seq, event)));
    }
    a.visibility = Visibility::of(Profile::LOUD);
    let loud = a.screen(100, 40).join("\n");
    assert!(loud.contains("please read the file"), "{loud}");
    assert!(loud.contains("the file says a thing"), "{loud}");

    // **And the same fixture under the new rung.** The conversation is all that is left.
    a.visibility = Visibility::of(Profile::CONVERSATION);
    a.invalidate_history();
    let quiet = a.screen(100, 40).join("\n");
    assert!(
        quiet.contains("please read the file"),
        "the operator's own words are the conversation: {quiet}"
    );
    assert!(
        quiet.contains("the file says a thing"),
        "and so is the model's answer: {quiet}"
    );
    for hidden in [
        "MAGIC-TOOL-PAYLOAD",
        "I should look at the file first",
        "bash",
        "h2",
    ] {
        assert!(
            !quiet.contains(hidden),
            "`{hidden}` is the working and must not be drawn: {quiet}"
        );
    }
    // **And the name is on the screen.** R29's remedy rule takes the form R37 gives it:
    // the MODE is named rather than a placeholder per hidden row — which is the thing the
    // operator asked to be rid of.
    assert!(
        quiet.contains("conversation"),
        "the rung must be named on the screen: {quiet}"
    );
    // **It is a view.** Switching back draws every row again, including the span it was
    // on, and nothing was dropped from the head's own copy.
    // **And the reasoning under the new rung is hidden by the RUNGS, not by the fold.**
    // Two different mechanisms want it off the screen — `thinking: folded` folds the
    // block, and this rung removes it — so the assertion above is only worth anything if
    // the fold is open. Otherwise it passes for the wrong reason, which is the defect
    // this test exists against.
    a.visibility = Visibility::of(Profile::LOUD);
    a.reasoning = Fold::Open;
    a.invalidate_history();
    let loud_open = a.screen(100, 200).join("\n");
    assert!(
        loud_open.contains("I should look at the file first"),
        "the fold is open, so the text is reachable: {loud_open}"
    );
    a.visibility = Visibility::of(Profile::CONVERSATION);
    a.invalidate_history();
    assert!(
        !a.screen(100, 200)
            .join("\n")
            .contains("I should look at the file first"),
        "and the rung is what removes it, with the fold open"
    );

    // **It is a view.** Switching back draws every row again, including the span it was
    // on, and nothing was dropped from the head's own copy.
    a.visibility = Visibility::of(Profile::LOUD);
    a.invalidate_history();
    let back = a.screen(100, 200).join("\n");
    assert!(
        back.contains("MAGIC-TOOL-PAYLOAD") && back.contains("I should look at the file first"),
        "a rung is a view: switching back must restore every row\n{back}"
    );
    // **Four ITEMS**: the operator's message, the reasoning, the answer and the result.
    // A `HeadAttached` is a note rather than a row, which is why the assertion is four —
    // the first draft said five and the failure named the miscount rather than the
    // mechanism, which is the useful direction.
    assert_eq!(a.items.len(), 4, "nothing left the head's copy");
    // **And an arrival is a fact the head holds, not a row it draws.** `HeadAttached` is
    // counted on every rung and drawn only at `Loud`, which is what the rung's own doc
    // says — so the assertion is the COUNT, because a rung that dropped the fact rather
    // than the row would make the header wrong about how many heads are on the session.
    // The seat's own snapshot carries no heads, so the one that is counted here is the
    // arrival the fixture sent — held where it is not drawn, which is what this asserts.
    assert_eq!(a.heads, 1, "the arrival is held even where it is not drawn");
}

/// **What this rung may NOT hide, and each for its own reason** (R37).
///
/// Three, and only one of them is about this head's taste: warnings were ruled by
/// `Verbosity::Terse`'s own docstring, decision cards make the session unanswerable if
/// they go, and liveness is this rung's specific risk — *a ten-minute tool-heavy turn
/// draws nothing at all*.
#[test]
fn the_conversation_rung_hides_no_warning_no_card_and_no_liveness() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // A warning, which is a fact the daemon chose to interrupt with.
    a.apply(ServerFrame::Event(env(
        1,
        SessionEvent::Warning {
            code: "context_wall".into(),
            detail: "WARNING-MAGIC-SENTENCE".into(),
            compaction: None,
        },
    )));
    // A turn in flight, with a tool call whose output is arriving.
    a.apply(ServerFrame::Event(env(2, testing::turn_started("t1"))));
    a.apply(ServerFrame::Event(env(
        3,
        SessionEvent::ToolStarted {
            turn_id: "t1".into(),
            call_id: "c1".into(),
            name: "bash".into(),
            access: "exec".into(),
        },
    )));
    a.apply(ServerFrame::Event(env(
        4,
        testing::tool_progress("c1", "still going"),
    )));
    // And a gate card waiting for an answer.
    a.apply(ServerFrame::Event(env(
        5,
        SessionEvent::DecisionRequested {
            write_targets: Vec::new(),
            req_id: "r1".into(),
            kind: "permission".into(),
            call_id: Some("c1".into()),
            access: String::new(),
            summary: "run the thing".into(),
            target: String::new(),
            detail: String::new(),
            options: Vec::new(),
            choices: Vec::new(),
            because: String::new(),
            advice: None,
            subagent: None,
            deadline: None,
            on_timeout: letibot_sessionlog::event::OnTimeout::Deny,
        },
    )));
    a.visibility = Visibility::of(Profile::CONVERSATION);
    a.invalidate_history();
    let frame = a.screen(100, 40);
    let all = frame.join("\n");
    assert!(
        all.contains("WARNING-MAGIC-SENTENCE"),
        "a warning is not on the ladder: {all}"
    );
    assert!(
        all.contains("?") && all.contains("permission"),
        "the decision card is the question the session is waiting on: {all}"
    );
    // **Liveness.** With the tool rows hidden, the only thing on screen that says a turn
    // is running is the composer's border — so it must still say so, and the elapsed
    // time with it. R13: a reader who cannot tell working from wedged is the confusion
    // this document has spent the day correcting in its own instruments.
    assert!(
        all.contains("Responding"),
        "the turn's own status line must survive the rung: {all}"
    );
}

/// **R37's consequence for R36**: a rung that hides rows can hide the one the reader is
/// holding, and the view moves to the nearest surviving row **and says so**.
#[test]
fn a_rung_that_hides_the_held_row_moves_the_view_and_says_so() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // A transcript whose rows alternate: conversation, tool result, conversation, …
    for i in 0..30u64 {
        let (a_id, b_id) = (format!("s.a{i}"), format!("s.b{i}"));
        a.apply(ServerFrame::Event(env(
            i * 4 + 1,
            testing::appended(&a_id, "assistant"),
        )));
        a.apply(ServerFrame::Event(env(
            i * 4 + 2,
            testing::content(&a_id, &format!("answer {i}")),
        )));
        a.apply(ServerFrame::Event(env(
            i * 4 + 3,
            testing::appended(&b_id, "tool_result"),
        )));
        a.apply(ServerFrame::Event(env(
            i * 4 + 4,
            SessionEvent::TranscriptContent {
                item_id: b_id,
                item: Box::new(letibot_transcript::TranscriptItem::ToolResult {
                    call_id: format!("c{i}"),
                    name: "bash".into(),
                    outcome: letibot_transcript::ToolOutcome::Ok,
                    payload: "tool payload".into(),
                    edit: None,
                    origin: None,
                    media: None,
                }),
            },
        )));
    }
    a.screen(100, 30);
    // **The anchor is put on a TOOL row deliberately**, because that is the case being
    // tested and a wheel notch lands wherever the arithmetic takes it — the first draft
    // scrolled and happened to stop on an assistant row, so the re-anchor never fired and
    // the test asserted that a thing which had not happened had not said anything.
    let tool_row = a
        .items
        .iter()
        .position(|it| it.kind == "tool_result")
        .expect("the fixture has tool rows");
    a.anchor = Some(Held {
        item_id: a.items[tool_row].item_id.clone(),
        ordinal: tool_row,
        into: 0,
    });
    let held = a.anchor.clone().expect("a held row");

    // Switch to the rung, which hides every other row here — and the assertion that the
    // held row IS one of them comes after the switch, because `hidden_by_rung` is a
    // question about the rung and asking it under `Normal` answers `false` for
    // everything. (The first draft asked it before the switch and passed on the wrong
    // side of the same mistake.)
    a.visibility = Visibility::of(Profile::CONVERSATION);
    assert!(
        a.hidden_by_rung(held.ordinal),
        "the fixture must hold a hidden row"
    );
    a.reanchor_off_hidden();
    let now = a
        .anchor
        .clone()
        .expect("still holding, on a row that shows");
    assert!(
        !a.hidden_by_rung(now.ordinal),
        "the view is holding a row the rung hides: {now:?}"
    );
    assert!(
        a.notice.as_deref().is_some_and(|n| n.contains("hides")),
        "and it says so rather than jumping quietly: {:?}",
        a.notice
    );
    // **The nearest** surviving row, not an arbitrary one: within one row of where the
    // reader was, since this fixture hides every other row.
    let distance = (now.ordinal as isize - held.ordinal as isize).unsigned_abs();
    assert!(
        distance <= 1,
        "the view jumped {distance} rows instead of to the neighbour: {held:?} -> {now:?}"
    );
}

/// **The rung is a rung**: the ladder cycles through it, and the verb says which rung is
/// on. The name is letibot's to choose and both heads use it (R37) — this pins the
/// spelling so it cannot drift into a second word for one view.
#[test]
fn the_ladder_cycles_through_the_conversation_rung_by_name() {
    assert_eq!(Verbosity::Conversation.as_str(), "conversation");
    let mut v = Verbosity::Conversation;
    for want in ["terse", "normal", "loud", "conversation"] {
        v = v.next();
        assert_eq!(v.as_str(), want);
    }
    // And only the one rung is a scope.
    assert!(Verbosity::Conversation.hides_the_working());
    for r in [Verbosity::Terse, Verbosity::Normal, Verbosity::Loud] {
        assert!(!r.hides_the_working(), "{r:?}");
    }
    // `keeps` is the item-level question, and it is the same line: the conversation in,
    // everything the head made out.
    use letibot_transcript::{ReasoningField, TranscriptItem as T};
    let user = T::User {
        speaker: Default::default(),
        parts: vec![letibot_transcript::UserPart::Text { text: "hi".into() }],
    };
    let answer = T::Assistant {
        text: "hello".into(),
        tool_calls: Vec::new(),
        truncated: false,
    };
    let thought = T::Reasoning {
        text: "hmm".into(),
        field: ReasoningField::ReasoningContent,
        truncated: false,
    };
    for kept in [&user, &answer] {
        assert!(Verbosity::Conversation.keeps(kept), "{kept:?}");
    }
    assert!(!Verbosity::Conversation.keeps(&thought));
    // And the registers keep everything, which is what makes this a rung rather than a
    // change to the ladder's meaning.
    for r in [Verbosity::Terse, Verbosity::Normal, Verbosity::Loud] {
        assert!(r.keeps(&thought), "{r:?}");
    }
}

/// **R36: a scrolled viewport holds while the transcript grows under it.**
///
/// The operator: *"scroll must be preserved - if i scrolled i want my view to hold,
/// regardless of the new stuff below."* And the case that matters, which the row does not
/// say and the operator added: **they scroll to read something WHILE a turn is running.**
/// A scroll that holds on a still transcript and creeps on a live one is the bug they
/// will actually meet, so there is a running turn throughout — rows arriving above and
/// below, a tool row growing as its output lands, and an elision changing a row's height
/// under the viewport.
///
/// **What is asserted is the frame**, not a line count: R36's whole point is that a count
/// is derived and anything above changing height invalidates it, so a test that pinned
/// the count would be pinning the defect. The one line excluded is the banner that says
/// how much is below the reader — that number is *supposed* to change, and it is the
/// disclosure rather than the view.
#[test]
fn a_scrolled_viewport_holds_while_the_transcript_grows() {
    fn visible(a: &mut App) -> Vec<String> {
        a.screen(100, 30)
            .into_iter()
            .filter(|l| !l.contains("holding your place"))
            .collect()
    }

    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // A conversation to scroll in, with a turn running so the live pane draws at the
    // same time as history arrives.
    for i in 0..40u64 {
        a.apply(ServerFrame::Event(env(
            i * 2 + 1,
            testing::appended(&format!("s.{i}"), "assistant"),
        )));
        a.apply(ServerFrame::Event(env(
            i * 2 + 2,
            testing::content(&format!("s.{i}"), &format!("row {i} says a thing")),
        )));
    }
    a.apply(ServerFrame::Event(env(200, testing::turn_started("t1"))));
    a.screen(100, 30);

    // **Six notches, not a page.** A page is the whole window here — the fixture is 84
    // body lines and the window is 25 — so a page up reaches the top and leaves no row
    // above the anchor to grow. The requirement's case is a reader who scrolled to read
    // *something*, not one who scrolled to the beginning.
    for _ in 0..6 {
        a.key(Key::WheelUp);
        a.screen(100, 30);
    }
    assert!(!a.following(), "six notches up did not leave the stream");
    let held = a.anchor.clone().expect("a held row");
    assert!(
        held.ordinal > 0,
        "the fixture scrolled to the very top, so there is no row above the anchor to \
             grow: {held:?}"
    );
    let under = visible(&mut a);
    let top_before = a.view_top;

    // 1. **Rows arrive BELOW the anchor** — the ordinary case: a turn commits what it
    //    has done and the transcript grows under a reader who is reading.
    for i in 100..108u64 {
        a.apply(ServerFrame::Event(env(
            i,
            testing::appended(&format!("s.new{i}"), "assistant"),
        )));
        a.apply(ServerFrame::Event(env(
            i + 1000,
            testing::content(&format!("s.new{i}"), "new content below the reader"),
        )));
    }
    assert_eq!(
        visible(&mut a),
        under,
        "content arriving below moved the held view"
    );
    assert_eq!(a.anchor, Some(held.clone()), "and moved the held row");

    // 2. **A row ABOVE the anchor grows** — R29's remedy line, a note, a tail that
    //    expanded. This is the case a line count cannot survive: every line below it
    //    shifts, and a count moves with them.
    {
        let first = a.items.first_mut().expect("a first row");
        first.kind = "assistant".into();
        first.item = Some(letibot_transcript::TranscriptItem::Assistant {
            text: "row 0 says a thing\nand three more lines\nthat were not there \
                       before\nat all"
                .into(),
            tool_calls: Vec::new(),
            truncated: false,
        });
    }
    a.invalidate_history();
    assert_eq!(
        visible(&mut a),
        under,
        "a row above the anchor gaining lines moved the held view"
    );
    assert_eq!(a.anchor, Some(held.clone()), "and moved the held row");

    // 3. **A tool row GROWS as its output lands**, under the running turn — the third
    //    way a line count creeps, and the one the live case is for.
    a.apply(ServerFrame::Event(env(
        3000,
        SessionEvent::ToolStarted {
            turn_id: "t1".into(),
            call_id: "c1".into(),
            name: "bash".into(),
            access: "exec".into(),
        },
    )));
    a.apply(ServerFrame::Event(env(
        3003,
        testing::tool_progress("c1", "30 lines so far"),
    )));
    a.apply(ServerFrame::Event(env(
        3001,
        SessionEvent::TranscriptAppended {
            item_id: "s.grow".into(),
            kind: "tool_result".into(),
            ledger_head: String::new(),
        },
    )));
    a.apply(ServerFrame::Event(env(
        3002,
        SessionEvent::TranscriptContent {
            item_id: "s.grow".into(),
            item: Box::new(letibot_transcript::TranscriptItem::ToolResult {
                call_id: "c1".into(),
                name: "bash".into(),
                outcome: letibot_transcript::ToolOutcome::Ok,
                payload: (0..30)
                    .map(|i| format!("output line {i}"))
                    .collect::<Vec<_>>()
                    .join("\n"),
                edit: None,
                origin: None,
                media: None,
            }),
        },
    )));
    let grown = a.screen(100, 30);
    assert_eq!(
        a.anchor,
        Some(held.clone()),
        "a growing tool row moved the held row"
    );
    assert!(
        grown.iter().any(|l| l.contains("holding your place")),
        "the screen must still say the viewport is held: {grown:#?}"
    );
    // The window's own lines are the ones it drew before, minus that banner.
    let window: Vec<String> = grown
        .into_iter()
        .filter(|l| !l.contains("holding your place"))
        .collect();
    assert_eq!(window, under, "a growing tool row moved the held view");

    // 4. **The hold is a PLACE, not a count**: the window's top line is where it was,
    //    which a count could not have kept with 38 lines added below it.
    assert_eq!(
        a.view_top, top_before,
        "the window's top line moved; a hold is a place, not a count"
    );
    assert!(a.body_len > 84, "nothing was added to the body at all");

    // 5. **Nothing that arrived returned the reader to the stream.** Only an explicit
    //    act does, and it is the one the banner names.
    assert!(!a.following());
    a.key(Key::Esc);
    assert!(a.following(), "esc did not resume following");
    assert_eq!(
        a.scroll, 0,
        "resuming following left a scroll behind: {}",
        a.scroll
    );
}

/// **R36 across the replacements**: a resync, a snapshot on `hello`, a compaction.
///
/// This is where the row said it *would* break — *"a `resync`, a snapshot on `hello`, and
/// a compaction all replace the rows wholesale. If the anchored row survives, the view
/// holds. If it was summarised away, SAY SO rather than jumping."*
///
/// Both halves, because they are different obligations: a replacement that **carries**
/// the row has to hold the view, and one that **takes it away** has to say so — silently
/// jumping to the bottom would lose the reader's place twice, once to the replacement and
/// once to the head.
#[test]
fn a_replacement_holds_the_view_or_says_the_row_is_gone() {
    /// A snapshot holding `ids`, as the daemon sends one on `hello` or a resync.
    fn snapshot_with(ids: &[&str]) -> letibot_sessionlog::view::Snapshot {
        let mut snap = Hub::new("s").snapshot();
        snap.seq = 9;
        snap.items = ids
            .iter()
            .map(|id| letibot_sessionlog::view::SnapshotItem {
                item_id: (*id).to_string(),
                kind: "assistant".into(),
                ledger_head: "beef".into(),
                ts: 0,
                item: Some(letibot_transcript::TranscriptItem::Assistant {
                    text: format!("row {id} says a thing"),
                    tool_calls: Vec::new(),
                    truncated: false,
                }),
            })
            .collect();
        snap
    }

    fn scrolled() -> App {
        let mut a = app();
        a.apply(hello(
            "s",
            vec![brief("s", "one", false)],
            Hub::new("s").snapshot(),
        ));
        for i in 0..40u64 {
            a.apply(ServerFrame::Event(env(
                i * 2 + 1,
                testing::appended(&format!("s.{i}"), "assistant"),
            )));
            a.apply(ServerFrame::Event(env(
                i * 2 + 2,
                testing::content(&format!("s.{i}"), &format!("row {i} says a thing")),
            )));
        }
        a.screen(100, 30);
        for _ in 0..6 {
            a.key(Key::WheelUp);
            a.screen(100, 30);
        }
        assert!(!a.following(), "the fixture never scrolled");
        a
    }

    // ---- the row SURVIVES the replacement ----
    let mut a = scrolled();
    let held = a.anchor.clone().expect("a held row");
    // A snapshot that carries every row, which is what a plain resync of an unchanged
    // session is.
    let ids: Vec<String> = a.items.iter().map(|i| i.item_id.clone()).collect();
    let ids: Vec<&str> = ids.iter().map(String::as_str).collect();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        snapshot_with(&ids),
    ));
    a.screen(100, 30);
    assert_eq!(
        a.anchor,
        Some(held.clone()),
        "a replacement that carries the row moved the view"
    );
    assert!(
        !a.notes
            .iter()
            .any(|(_, n)| matches!(n, Note::Warned(w) if w.code == "anchor_lost")),
        "and it said nothing, because nothing was lost"
    );

    // ---- the row is GONE, and it is said ----
    let mut b = scrolled();
    let lost = b.anchor.clone().expect("a held row");
    // A replacement that carries only the FIRST few rows — which is what a compaction
    // looks like from here: the old transcript is gone, and a much shorter one stands in.
    // A replacement that carries the LAST twenty rows: the reader's row is gone and the
    // transcript is still long enough to be holding a place in, which is the shape a
    // compaction leaves behind — a summary in place of the old head, the recent tail
    // carried as itself.
    let tail: Vec<String> = (20..40).map(|i| format!("s.{i}")).collect();
    let tail: Vec<&str> = tail.iter().map(String::as_str).collect();
    b.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        snapshot_with(&tail),
    ));
    let frame = b.screen(100, 30);
    let said = b
        .notes
        .iter()
        .find_map(|(_, n)| match n {
            Note::Warned(w) if w.code == "anchor_lost" => Some(w.detail.clone()),
            _ => None,
        })
        .expect("a row that is gone must be said, not jumped over");
    assert!(
        said.contains(&lost.item_id),
        "the sentence names the row that went: {said}"
    );
    assert!(
        said.contains("follows the stream again"),
        "and carries the act that undoes the hold: {said}"
    );
    // **And it reaches the reader where they are looking.** The note lives at the seam
    // at the end of the replacement, which is *below* a reader who is holding a row near
    // the top — so the transient line above the composer carries it too, and that is the
    // one this asserts. A disclosure the reader cannot see is not a disclosure.
    assert!(
        b.notice
            .as_deref()
            .is_some_and(|n| n.contains(&lost.item_id)),
        "the reader must be told on screen, not only at a seam below them: {:?}",
        b.notice
    );
    let _ = frame;
    // **It lands on the nearest surviving row**, not at the bottom: the ordinal it held
    // is the only ordering both sides of a replacement agree on.
    let now = b.anchor.clone().expect("still holding, on its neighbour");
    assert!(
        now.ordinal < b.items.len(),
        "the hold was dropped instead of moved: {now:?}"
    );
    assert!(
        now.ordinal <= lost.ordinal,
        "the view jumped past where the reader was: {:?} from {:?}",
        now,
        lost
    );
    assert!(!b.following(), "the reader was thrown back into following");
}

/// **R17: a head knows whether it has every row the daemon says it has.**
///
/// `seq` is the log's position, dense and assigned by the daemon alone — and this
/// head assigned it unconditionally (`self.seq = env.seq`), which is exactly what
/// makes a delivered row and a dropped one look the same. Measured 2026-09-22: a
/// prompt that was **in the ledger and acted on** never reached this head's screen,
/// and nothing in this head could have said so.
///
/// Three obligations, and the third is why the second is not enough: **say** it (a
/// note in the conversation, not a transient line — this is a fact about the
/// session), **repair** it (`/resync` exists for precisely this), and **count** it.
/// A gap repaired silently is indistinguishable from a session that never had one,
/// so the operator learns nothing about a daemon, a socket or a compaction that is
/// losing rows — which is the same argument `/status`'s `unreadable` bucket makes,
/// and this is the sixth of that family.
#[test]
fn a_gap_in_the_log_is_said_repaired_and_counted() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    assert_eq!(a.gaps, 0, "a head that has missed nothing says zero");

    // Two events are lost on the socket: 2 and 3 never arrive, and 4 does.
    a.apply(ServerFrame::Event(env(
        4,
        testing::delta("t1", "the answer to a prompt this head never saw"),
    )));
    assert_eq!(a.gaps, 1, "the gap is counted");
    assert_eq!(a.seq, 4, "and the read mark still follows what was read");
    // **Said in the conversation**, where it scrolls with everything else, and
    // naming the range so two gaps are two lines rather than one deduped one.
    let notes = a.notes_lines().join("\n");
    assert!(notes.contains("log_gap"), "nothing said the gap: {notes}");
    assert!(
        notes.contains("2..3"),
        "the lost seqs are not named: {notes}"
    );
    // **And repaired.** A resync is the one thing that can put the head back in
    // step, and the head cannot do it itself: the daemon owns the transcript.
    assert!(
        a.queued.iter().any(|x| matches!(x, Action::Resync)),
        "the gap was noted and not repaired"
    );

    // A second gap is a second line, not the first one restated.
    a.apply(ServerFrame::Event(env(9, testing::delta("t1", "later"))));
    assert_eq!(a.gaps, 2);
    let notes = a.notes_lines().join("\n");
    assert!(notes.contains("5..8"), "{notes}");

    // **Continuity is silent.** Ten events in a row say nothing at all, which is
    // the property that makes the line worth reading when it does appear.
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    for seq in 1..=10 {
        a.apply(ServerFrame::Event(env(seq, testing::turn_started("t1"))));
    }
    assert_eq!(a.gaps, 0);
    assert!(a.notes.is_empty(), "{:?}", a.notes);
    // And it is on the status screen, beside the five counters it belongs with.
    // A tall frame: `/status` is a long list and the row has to be reached rather
    // than scrolled for in a test.
    a.command("status");
    let status = a.screen(100, 100).join("\n");
    assert!(status.contains("gaps"), "no gap row on /status: {status}");
}

/// **R17's other two numbers: a body with no row, and a daemon that is ahead.**
///
/// `gaps` is the wire losing events. These are the two that look identical to it
/// from inside and are not it:
///
/// * **`orphan_bodies`** — the row was announced, a snapshot replaced the rows
///   without it, and its words arrive with nowhere to go. `record_item` used to
///   `return` in silence, which is why the trailer of a lost row was that there
///   was no trailer. The row is not in `items`, so there is not even a
///   placeholder to notice; this count is the whole of what is left of it.
/// * **`behind`** — nothing is lost and nothing is orphaned, and the head is not
///   current: the events are in a queue, on a socket, or in this head's own
///   channel. This is the state the operator measured from outside on 2026-09-22
///   and could not name, and it is the reason a screen cannot be trusted to say
///   whether the session has gone quiet or the head has stopped being told.
#[test]
fn a_body_with_no_row_and_a_daemon_that_is_ahead_are_both_counted() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));

    // A body for a row this head never had: counted, said, and drawn nowhere —
    // there is nothing to draw it on.
    a.record_item(
        "s.gone",
        TranscriptItem::User {
            speaker: Default::default(),
            parts: vec![UserPart::Text {
                text: "a prompt that fell out of a snapshot".into(),
            }],
        },
    );
    assert_eq!(a.orphan_bodies, 1);
    let notes = a.notes_lines().join("\n");
    assert!(notes.contains("orphan_body"), "{notes}");
    assert!(
        notes.contains("s.gone"),
        "the note does not name the row: {notes}"
    );
    // **And it is not in the conversation**, because there is no row for it.
    let screen = a.screen(100, 40).join("\n");
    assert!(
        !screen.contains("a prompt that fell out of a snapshot"),
        "a body with no row was drawn anyway: {screen}"
    );

    // **A daemon that answers from further along than this head has read.** The
    // head is at seq 1 and the command's effect is visible at 9, so eight events
    // are in flight and none are lost — the head is behind, which is a different
    // fact and is why it is a different number.
    a.apply(ServerFrame::Accepted {
        client_request_id: "r1".into(),
        seq: 9,
        note: letibot_sessionlog::protocol::NOTE_PROMPT_QUEUED.into(),
    });
    assert_eq!(a.behind, 8, "the distance the daemon stated was not kept");
    assert_eq!(
        a.gaps, 0,
        "being behind is not a gap, and must never move it"
    );
    assert!(
        !a.queued.iter().any(|x| matches!(x, Action::Resync)),
        "being behind is not a reason to resync"
    );

    // A redelivery — a seq at or below this head's own — is not a distance.
    a.apply(ServerFrame::Accepted {
        client_request_id: "r2".into(),
        seq: 1,
        note: letibot_sessionlog::protocol::NOTE_PROMPT_QUEUED.into(),
    });
    assert_eq!(a.behind, 0);
}

/// **R16: an echo whose prompt landed under a transcript that was then replaced.**
///
/// Measured on this head 2026-09-22: three prompts still rendering `queued ·`
/// while the tree was clean, no turn was running, and the work they asked for was
/// already committed. R2 says exactly why the mark can outlive the fact — an echo
/// binds to an announced row and retires on `TranscriptContent` **matched by
/// text** — and a compaction **replaces the transcript**, so the row those echoes
/// were waiting for was summarised away and the retiring event never arrives.
///
/// The fix is at the fork and it is exact rather than approximate: the echoes that
/// were in the air **when the fork began** are resolved, and the ones queued after
/// it are left alone, because those belong to the new transcript and their rows
/// are still coming. Both halves are asserted here, and the second matters as much
/// as the first: retiring an echo whose row has not landed takes a sentence off
/// the screen, which is §4.2's defect with a new cause.
///
/// **Why the shape is "mark on the way in, resolve on the way out".** A fork
/// announces itself twice — `auto_compact` *before* it happens and `compacted`
/// *after* — and only the first of those can say what was in the air. A manual
/// `/compact` has no "before" warning at all, so the head takes its own mark as
/// it sends the request. Both are the head's own bookkeeping on facts it already
/// has; no daemon change is involved.
#[test]
fn a_compaction_resolves_the_echoes_it_supersedes() {
    let hub = Hub::new("s");
    let att = hub.attach("tui", "test", Caps::default(), 0);
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", true)],
        Hub::new("s").snapshot(),
    ));
    hub.publish(testing::turn_started("t1"));
    feed(&mut a, &hub, &att.head_id);
    assert!(a.turn_busy(), "the premise: a turn is running");

    // The operator types and sends. The hub takes the prompt as a follow-up user
    // item and the head echoes it — the R2 window, and the only place the words
    // exist until the step boundary.
    typed(&mut a, "also fix the parser");
    assert!(matches!(a.key(Key::Enter), Some(Action::Prompt(_))));
    let queued = a.screen(100, 24).join("\n");
    assert!(queued.contains("queued · also fix the parser"), "{queued}");

    // **The fork, in the order the daemon publishes it.** `auto_compact` says the
    // conversation is about to be replaced; `compacted` says it has been; and the
    // new base arrives as rows. The prompt's own row was in the transcript that
    // was summarised away, so no `TranscriptContent` for it ever comes — which is
    // the defect, and it is this test's own premise.
    hub.publish(SessionEvent::Warning {
        code: "auto_compact".into(),
        detail: "938065 of 999999 tokens resident — compacting now".into(),

        compaction: None,
    });
    hub.publish(SessionEvent::Warning {
        code: "compacted".into(),
        detail: "compacted: 940188 → 9181 tokens, on transcript s#t25".into(),

        compaction: None,
    });
    hub.publish(SessionEvent::TranscriptAppended {
        item_id: "s#t25.0".into(),
        kind: "system".into(),
        ledger_head: String::new(),
    });
    hub.record_item(
        "s#t25.0",
        TranscriptItem::System {
            text: "This conversation was compacted: everything said before this point \
                       is replaced by the summary below…"
                .into(),
            origin: letibot_transcript::SystemOrigin::Update,
        },
    );
    feed(&mut a, &hub, &att.head_id);

    // **The mark is gone, and it is gone because the fork resolved it.** The
    // prompt's words are still in the conversation — as prose in the summary — and
    // what left the screen is the claim that the daemon had not taken them yet.
    let after = a.screen(100, 24).join("\n");
    assert!(
        !after.contains("queued ·"),
        "the mark outlived the transcript it was waiting for: {after}"
    );
    assert!(
        a.pending_prompts.is_empty(),
        "the echo is still held: {:?}",
        a.pending_prompts
    );

    // **And one queued after the fork is left alone**, because its row is still
    // coming. This is the half that must not be lost, and the next fork is what
    // takes it — proving the mark is re-taken per fork rather than spent once.
    typed(&mut a, "and now the next thing");
    assert!(matches!(a.key(Key::Enter), Some(Action::Prompt(_))));
    let still = a.screen(100, 24).join("\n");
    assert!(still.contains("queued · and now the next thing"), "{still}");

    hub.publish(SessionEvent::Warning {
        code: "auto_compact".into(),
        detail: "compacting again".into(),

        compaction: None,
    });
    hub.publish(SessionEvent::Warning {
        code: "compacted".into(),
        detail: "compacted again".into(),

        compaction: None,
    });
    feed(&mut a, &hub, &att.head_id);
    let last = a.screen(100, 24).join("\n");
    assert!(
        !last.contains("queued ·"),
        "the second fork left its own echoes behind: {last}"
    );

    // **A manual fork takes its mark on the way out**, because the daemon only
    // says `compacted` — after the fact — for one the head asked for.
    let mut b = app();
    b.session_id = "s".into();
    b.pending_prompts.push("typed while the turn ran".into());
    assert_eq!(b.command("compact"), Some(Action::Compact));
    assert_eq!(
        b.fork_pending,
        vec!["typed while the turn ran".to_string()],
        "a manual compaction marked nothing"
    );
    b.apply(ServerFrame::Event(env(
        1,
        SessionEvent::Warning {
            code: "compacted".into(),
            detail: "compacted".into(),

            compaction: None,
        },
    )));
    assert!(
        b.pending_prompts.is_empty(),
        "the manual fork resolved nothing"
    );
}

/// **A refusal the harness made is one dim line, not a wall in red.**
///
/// The operator's report, about a `bash` one-liner the normaliser could not
/// read: *"i get what it tries to do, but it just throws up on my chat"*. Every
/// word of that explanation is addressed to the model, it was already on the
/// screen as the tool's own result one row above, and nothing in it is
/// answerable — no adjudicator was consulted and no grant lifts it.
#[test]
fn a_refusal_nobody_made_is_quiet_and_one_line() {
    let mut a = app();
    let long = "this command's meaning does not exist yet, so nothing can decide \
                    about it. The grammar read 315 bytes and 7 stage(s) and could not \
                    resolve:\n  parameter_expansion at 1:2 (bytes 2..4) decides the \
                    assignment: \"$$\"\n      `$$` decides what the variable will hold, \
                    and its value is not in this text.";
    let hub = Hub::new("s");
    let att = hub.attach("tui", "test", Caps::default(), 0);
    hub.publish(letibot_sessionlog::event::SessionEvent::DenialRaised {
        request_id: "adj-s-1789462738453908838-0001".into(),
        turn_id: "t1".into(),
        call_id: "c1".into(),
        tool: "bash".into(),
        summary: "`bash` wants exec access to `p=$$; for i in 1 2 3; do read -r ppid; done`".into(),
        baseline: "ask — intents [execute_code]".into(),
        by: "boundary:normaliser".into(),
        basis: long.into(),
        tier: "adjudicable".into(),
        outcome: "not_run".into(),
        repeat_count: 1,
        breaker_open: false,
        grant: "Nothing was executed and nothing changed. No grant applies.".into(),
    });
    feed(&mut a, &hub, &att.head_id);

    // A first refusal says nothing here at all: the refused call is a row in
    // the transcript one line below, with the same sentence on it.
    assert!(
        a.notes.is_empty(),
        "a single refusal is stated twice: {:?}",
        a.notes
    );

    // A SECOND attempt at the same direction is a fact about the session that
    // the row cannot carry, so that one does speak.
    let hub = Hub::new("s2");
    let att = hub.attach("tui", "test", Caps::default(), 0);
    hub.publish(letibot_sessionlog::event::SessionEvent::DenialRaised {
        request_id: "adj-2".into(),
        turn_id: "t1".into(),
        call_id: "c2".into(),
        tool: "bash".into(),
        summary: "`bash` wants exec access to `p=$$`".into(),
        baseline: "ask — intents [execute_code]".into(),
        by: "boundary:normaliser".into(),
        basis: long.into(),
        tier: "adjudicable".into(),
        outcome: "not_run".into(),
        repeat_count: 2,
        breaker_open: false,
        grant: "No grant applies.".into(),
    });
    let mut a = app();
    feed(&mut a, &hub, &att.head_id);
    let note = a.notes.last().expect("a repeat is worth saying");
    let lines = note_lines(&a.cfg, &note.1);
    // One sentence, so at most a wrap of one. The thing being measured is that
    // it is not a paragraph per unresolved construct.
    assert!(
        lines.len() <= 2,
        "a wall again, {} lines: {lines:#?}",
        lines.len()
    );
    let l = lines.join(" ");
    let l = &l;
    assert!(l.contains("bash not_run"), "{l}");
    assert!(
        l.contains("meaning does not exist yet"),
        "the gist survived: {l}"
    );
    // Not the paragraph, not the id, not the loud register.
    assert!(
        !l.contains("parameter_expansion"),
        "the model's detail leaked: {l}"
    );
    assert!(!l.contains("adj-s-"), "an id nobody can use: {l}");
    assert!(!l.contains('!'), "still shouting: {l}");
}

/// **A refusal's reasoning folds, and the envelope never shows.** Both halves
/// of *"it just throws up on my chat"*: layer A's reason is a document, and the
/// row under it was carrying the marker the model reads.
#[test]
fn a_reason_that_is_a_document_folds_to_its_first_sentence() {
    assert!(is_envelope("<<<TOOL_ERROR 5ebfdef6>>>"));
    assert!(is_envelope("  <<<END_TOOL_ERROR 5ebfdef6>>>  "));
    assert!(
        !is_envelope("< < <TOOL_ERROR 5ebfdef6>>>"),
        "a neutralised body line"
    );
    assert!(!is_envelope("error: could not find `Cargo.toml`"));

    let doc = "this command's meaning does not exist yet, so nothing can decide \
                   about it. The grammar read 315 bytes and could not resolve:\n  \
                   parameter_expansion at 1:2 decides the assignment";
    let gist = first_sentence(doc);
    assert_eq!(
        gist,
        "this command's meaning does not exist yet, so nothing can decide about it."
    );
    assert!(!gist.contains("parameter_expansion"));
    // A reason that IS a sentence is left exactly alone.
    let one = "the workspace has no writable backend";
    assert_eq!(first_sentence(one), one);
}

/// Type into the composer the way a person does, one key at a time. There is
/// no `input` field to assign any more, and that is the point: the composer
/// is a state machine with undo batching and a paste ledger, and a test that
/// reaches past it is not testing what runs.
fn typed(a: &mut App, text: &str) {
    for c in text.chars() {
        a.key(Key::Char(c));
    }
}

// ─────────────────────────── `!term`, the pane ───────────────────────────

/// Open a pane the way the operator does, and feed it the bytes a program would draw.
///
/// The submit is a real key path — typed characters and an Enter — rather than a
/// constructed `Action`, because the recognition at the composer is half of what these
/// tests are about.
fn pane(a: &mut App, bytes: &[u8]) -> Action {
    typed(a, "!term mc");
    let opened = a.key(Key::Enter).expect("the verb opens a pane");
    a.apply(ServerFrame::TermOutput {
        bytes: bytes.to_vec(),
    });
    opened
}

/// **`!term <command>` is the pane, and nothing else stops being what it was.**
///
/// The verb is a **whole word**: `!terminal x` and `!terms x` are ordinary `!` lines, which
/// is what they always were, and `! ls .` is untouched. A recogniser is only honest next to
/// what it must NOT take, which is why the contrast cases are in the same test.
///
/// **And this is the refusal no longer firing.** `! mc` is refused by name
/// (`letibot_tools::exec::terminal`) because a plain `!` run's pty is a *capture* — one
/// transcript row and `/dev/null` on stdin — so a screen program draws into a row and waits
/// for a keystroke that cannot arrive. `!term mc` never reaches that path: it is a different
/// action, on a different frame, to a different daemon half, and the refusal's own remedy
/// now names the verb.
#[test]
fn a_term_line_opens_the_pane_and_an_ordinary_bang_line_is_still_a_shell_command() {
    let mut a = app();
    assert_eq!(
        pane(&mut a, b"mc"),
        Action::TermOpen {
            line: "!term mc".into()
        }
    );
    assert!(a.pane_open());

    for line in ["!terminal x", "!terms x", "!term-x", "! ls ."] {
        let mut b = app();
        typed(&mut b, line);
        assert_eq!(
            b.key(Key::Enter),
            Some(Action::OperatorShell { line: line.into() }),
            "`{line}` is not the verb and is still the operator's shell line"
        );
        assert!(!b.pane_open(), "`{line}` opened a pane");
    }

    // **The verb with nothing after it ATTACHES**, and it is not a request for `$SHELL`
    // either: it is the pane this session already has. The head opens the rectangle and sends
    // the bare line; the daemon answers with what is running and with the screen it kept —
    // see `a_bare_term_line_attaches_and_the_daemon_says_what_is_running`.
    let mut c = app();
    typed(&mut c, "!term");
    assert_eq!(
        c.key(Key::Enter),
        Some(Action::TermOpen {
            line: "!term".into()
        }),
        "a bare `!term` is an attach, and the line goes over as typed"
    );
    assert!(
        c.pane_open(),
        "the rectangle is up before the daemon answers"
    );
    assert_eq!(c.input(), "", "the line left the composer — it was sent");
}

/// **A bare `!term` attaches: the rectangle comes up, the daemon says what is running, and
/// the screen it kept is drawn in it.**
///
/// This is the operator's way back, and the whole of it is three facts:
///
/// * the head sends the **bare verb** — it does not know what is running, and cannot: the
///   program is the session's and the line that started it may have been typed by another
///   head, or by this one before a session switch;
/// * the daemon answers with [`ServerFrame::TermAttached`], and the head **says** what it
///   was told — *"saying what is running in it"* is the requirement, and a screen alone
///   does not say it (`mc`'s panels look like `mc`'s panels);
/// * and the bytes that follow are the **daemon's replay** of a screen the head never drew,
///   which is what proves the attach rather than a redraw: the pane the head is holding was
///   created empty a moment ago, so everything on it came from the daemon.
#[test]
fn a_bare_term_line_attaches_and_the_daemon_says_what_is_running() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    // One frame first: a pane's rectangle is the last frame's, which is all this layer
    // knows until it draws one.
    let _ = a.screen(80, 24);

    typed(&mut a, "!term");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::TermOpen {
            line: "!term".into()
        })
    );
    assert!(a.pane_open());
    // **Nothing has been drawn yet** — the rectangle is empty because the head has never
    // seen this program. That is the state the replay has to fill.
    assert!(
        !a.screen(80, 24).iter().any(|r| r.contains("mc's screen")),
        "the head cannot have this screen: it never drew it"
    );

    a.apply(ServerFrame::TermAttached {
        command: "mc /etc".into(),
    });
    assert!(
        a.notice
            .as_deref()
            .is_some_and(|n| n.contains("!term mc /etc")),
        "the operator is told what is running in the pane they attached to: {:?}",
        a.notice
    );
    a.apply(ServerFrame::TermOutput {
        bytes: b"\x1b[2J\x1b[Hmc's screen\r\n".to_vec(),
    });
    assert!(
        a.screen(80, 24).iter().any(|r| r.contains("mc's screen")),
        "the daemon's replay is drawn in the rectangle: {:?}",
        a.screen(80, 24)
    );

    // **And the line the daemon named is what an ending names**, not the bare verb the head
    // typed: the row a person reads has to say which pane ended. (The reason is the daemon's
    // own sentence; this fixture uses the one a deliberate close gets, which is the daemon's
    // wording since protocol 34 — see `harnessd`'s `Terminals::CLOSED`.)
    a.apply(ServerFrame::TermEnded {
        reason: "you closed the terminal".into(),
    });
    assert!(
        a.screen(80, 24)
            .iter()
            .any(|r| r.contains("!term mc /etc") && r.contains("you closed the terminal")),
        "the ending names the pane the daemon said was running: {:?}",
        a.screen(80, 24)
    );
}

/// **A session with no pane says so, and the sentence is a row.**
///
/// The other half of the attach: `!term` with nothing running is not silence and not a
/// rectangle left standing empty — the daemon answers with the same `TermEnded` every pane
/// that could not start uses, and the head files it like any other ending.
#[test]
fn attaching_to_a_session_with_no_pane_says_so() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    let _ = a.screen(80, 24);
    typed(&mut a, "!term");
    assert!(a.key(Key::Enter).is_some());
    assert!(a.pane_open());
    a.apply(ServerFrame::TermEnded {
        reason: "this session has no pane to attach to — `!term COMMAND` starts one. \
                     Nothing was attached."
            .into(),
    });
    assert!(!a.pane_open(), "the rectangle comes back");
    assert!(
        a.screen(80, 24)
            .iter()
            .any(|r| r.contains("no pane to attach to")),
        "and the daemon's sentence is a row: {:?}",
        a.screen(80, 24)
    );
}

/// **The pane takes the conversation's rectangle and gives it back, exactly.**
///
/// This is the whole of *"the conversation's rectangle given to the program with the
/// composer keeping its rows"*, and the property `letibot_ui::ansi::pane_rows` keeps:
/// the pane is resized to the rectangle it is given and returns **exactly** that many rows.
/// So the header keeps its line, the chrome under the pane keeps its rows, and nothing above
/// the pane moves when it opens.
///
/// Asserted against the frame this head drew **without** a pane, at the same size and the
/// same state — so the comparison is not against a hand-written expectation of what the
/// chrome looks like, which would rot, but against the frame the pane is supposed to be
/// occupying a slice of.
#[test]
fn the_pane_keeps_the_header_the_composer_and_the_status_their_rows() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    shell_row(&mut a, 1, "u1", "user", operator_row("! ls -la"));
    shell_row(
        &mut a,
        3,
        "u2",
        "user",
        operator_row("what is in this tree?"),
    );

    let before = a.screen(80, 24);
    pane(&mut a, b"\x1b[2J\x1b[Hhello from mc\r\n");
    let during = a.screen(80, 24);
    // **`size().0`, and not `rows()`** — on this screen `rows()` hands back the cells of
    // every row (`Chunks<Cell>`), and the number the pane was given is the size. The
    // rectangle is what this test is about, so it is asked for by name.
    let room = a.term.as_ref().expect("a pane").screen.size().0;

    assert_eq!(
        during.len(),
        before.len(),
        "the frame is the terminal's height, pane or no pane"
    );
    assert_eq!(during[0], before[0], "the header keeps its row");
    assert_eq!(
        &during[1 + room..],
        &before[1 + room..],
        "the composer and the status keep their rows"
    );
    assert!(
        during.iter().any(|r| r.contains("hello from mc")),
        "the program is drawn in the rectangle: {during:?}"
    );
    assert!(!before.iter().any(|r| r.contains("hello from mc")));
    assert!(room >= 1, "the pane got a rectangle");
}

/// **The pane's rows are exactly `room`, at every size** — the property `vt-one` is
/// preserving, asserted from the head's side rather than from the screen's.
#[test]
fn the_pane_draws_exactly_the_rows_it_is_given() {
    for h in [8usize, 24, 40] {
        let mut a = app();
        a.session_id = "s".into();
        shell_row(&mut a, 1, "u1", "user", operator_row("! ls -la"));
        pane(&mut a, b"\x1b[2Jone\r\ntwo\r\n");
        let frame = a.screen(80, h);
        assert_eq!(frame.len(), h, "a {h}-row terminal is a {h}-row frame");
        let room = a.term.as_ref().unwrap().screen.size().0;
        assert_eq!(
            a.term.as_ref().unwrap().screen.size().1,
            80 - 2 * App::gutter(80),
            "the pane is the conversation's own width, gutter excluded"
        );
        assert!(
            room <= h,
            "the pane cannot be taller than the frame: {room} of {h}"
        );
    }
}

/// **Keys are forwarded as bytes, and the way out is not one of them.**
///
/// The pane's keyboard is the program's, and what reaches it is the bytes the operator's
/// terminal sent — **not this head's reading of them**. `ESC O A` is the application-cursor
/// spelling of *up*, and a head that decoded it into `Key::Up` and re-encoded it would send
/// `ESC [ A`, a different string to a program that asked for the first. The assertion is on
/// the bytes, including a control byte and half a UTF-8 character.
///
/// **`ctrl-\` (0x1c) is found in that stream before anything is forwarded**, so the program
/// never receives it and cannot trap it. It is also one of the three bytes this head's own
/// decoder has no arm for, so it could never have arrived as a `Key` at all — see
/// `Terminal::raw_keys`.
///
/// # And the act is a DETACH — the operator's *"but i dont want it to exit"*
///
/// This test used to assert `Action::TermClose` here, which is the defect the whole split
/// exists to remove: leaving a pane ended its cgroup, so leaving `nano` killed it. What is
/// asserted now is the negative the requirement is made of — **nothing leaves the head** —
/// and the positive that makes it a detach rather than a disappearance: the pane is still
/// held, so the program is still running and `!term` has something to come back to.
#[test]
fn the_panes_keys_go_down_verbatim_and_ctrl_backslash_detaches() {
    let mut a = app();
    pane(&mut a, b"mc");

    let keys = vec![0x1b, b'O', b'A', 0x03, b'x', 0xe2];
    assert_eq!(
        a.pane_keys(&keys),
        vec![Action::TermInput {
            bytes: keys.clone()
        }],
        "the bytes, and not a key this head understood"
    );

    assert_eq!(
        a.pane_keys(b"hi\x1cz"),
        vec![Action::TermInput {
            bytes: b"hi".to_vec()
        }],
        "the bytes before the way out are the last the program gets, the key itself is never \
             one of them, and NOTHING ELSE is sent — no frame of any kind ends anything"
    );
    assert!(
        !a.pane_open(),
        "the rectangle comes back: the pane is hidden"
    );
    assert!(
        a.term.is_some(),
        "and the pane is KEPT — the program is still running, which is what `!term` attaches \
             back to"
    );
    assert_eq!(a.input(), "", "the composer saw none of it");
    // **The disclosure is the chrome line, and it is drawn while it is true** — see
    // [`App::detach`] for why the sentence is not a notice as well: a notice cannot be taken
    // back, and this one would have outlived the pane.
    let frame = a.screen(80, 24);
    assert!(
        frame.iter().any(|r| r.contains("a pane is running")
            && r.contains("!term mc")
            && r.contains("`!term close` ends it")),
        "the screen says the program is still running, and names both ways on: {frame:?}"
    );
    assert!(
        a.notes.is_empty(),
        "a detach files no row: it ends nothing, so there is no ending to disclose"
    );

    // **A detached pane forwards nothing**, which is the other half of *it is not on the
    // screen*: the keys belong to the composer again, so this is never even asked — and a
    // byte written into a pane nobody is drawing would be a keystroke the operator aimed at
    // the composer.
    assert!(
        a.pane_keys(b"more").is_empty(),
        "a detached pane takes no keys"
    );

    // The control that makes the interception mean something: with no pane, the same bytes
    // are the composer's and `0x1c` is a way out of nothing.
    let mut b = app();
    assert!(!b.pane_open());
    assert!(b.pane_keys(&keys).is_empty());
    assert!(b.pane_keys(b"\x1c").is_empty());
}

/// **A program that exits while the operator is away still leaves its row.**
///
/// The second half of *a detach must not hide anything*: the head keeps the pane while it
/// is detached (so it keeps feeding the screen from the frames that are still arriving),
/// and the ending therefore arrives with the last rows the program left — the row they
/// would have seen had they been looking.
///
/// **The register is the difference and it is asserted too**: this ending was not the
/// operator's act, so it is the notice register — the `×` a `!term close` does not get.
#[test]
fn a_program_that_exits_while_detached_still_leaves_its_ending_row() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    let _ = a.screen(80, 24);
    pane(&mut a, b"mc: starting\r\n");

    // The operator leaves: nothing is sent, the rectangle goes, the program keeps running.
    assert_eq!(
        a.pane_keys(b"\x1c"),
        Vec::new(),
        "a detach sends nothing at all"
    );
    assert!(!a.pane_open());

    // It writes while they are away — the frames still arrive, and the head still feeds the
    // screen it is holding. Then it exits.
    a.apply(ServerFrame::TermOutput {
        bytes: b"mc: not found\r\n".to_vec(),
    });
    a.apply(ServerFrame::TermEnded {
        reason: "the program exited with 127".into(),
    });

    assert!(!a.pane_open());
    assert!(a.term.is_none(), "the pane is over and dropped");
    let frame = a.screen(80, 24);
    assert!(
        frame
            .iter()
            .any(|r| r.contains("!term mc") && r.contains("the program exited with 127")),
        "the ending is a row, with the daemon's own sentence on it: {frame:?}"
    );
    assert!(
        frame.iter().any(|r| r.contains("mc: not found")),
        "and with the last thing the program printed — the rows a detach must not hide: \
             {frame:?}"
    );
    // **`×` and not `·`**: nobody chose this ending, so it is the answer to what the
    // operator is about to read rather than housekeeping.
    assert!(
        frame
            .iter()
            .any(|r| r.trim_start().starts_with('×') && r.contains("!term mc")),
        "an ending nobody asked for is the notice register: {frame:?}"
    );
}

/// **Leaving gives the conversation back, and the ending stays as a row.**
///
/// This test used to assert that the frame came back **byte for byte**, with the ending
/// cleared as a notice — and *that assertion was the defect*. A pane that ended left nothing
/// behind but a sentence that faded, so a program that died at once was invisible a few
/// seconds later and there was nothing to scroll back to. What is true now is the half that
/// matters and the half that changed:
///
/// * **the program's own drawing is gone** — the rectangle is the conversation's again, and
///   the rows the program painted are not in the frame;
/// * **the transcript is back**, which is the property this test has always been about;
/// * **and the ending is a row in it**, with the line that was run and the daemon's own
///   sentence — see [`Note::Pane`].
///
/// **The ending here is the deliberate one** (`!term close`, confirmed), which is why the
/// sentence is *"you closed the terminal"* and the register is the dim `·` — a detach would
/// have filed no row at all, and a program's own exit would have been the `×`.
#[test]
fn ending_the_pane_gives_the_conversation_back_and_the_ending_stays_as_a_row() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    shell_row(&mut a, 1, "u1", "user", operator_row("! ls -la"));
    shell_row(
        &mut a,
        3,
        "u2",
        "user",
        operator_row("what is in this tree?"),
    );
    let before = a.screen(80, 24);

    pane(&mut a, b"\x1b[2J\x1b[Hmc's screen\r\n");
    assert_ne!(
        a.screen(80, 24),
        before,
        "the pane really did replace the conversation"
    );

    // The operator ends it deliberately: `!term close` is typed at the composer (which a
    // drawn pane owns, so this is the DETACHED case — the head has the pane and the card
    // names it), then confirmed with the one key that means yes.
    a.detach();
    typed(&mut a, "!term close");
    assert_eq!(
        a.key(Key::Enter),
        None,
        "the verb asks; it does not end anything on its own"
    );
    assert!(a.term_ask.is_some(), "the confirmation is up");
    assert_eq!(
        a.key(Key::Char('y')),
        Some(Action::TermClose),
        "and `y` is the yes"
    );

    a.apply(ServerFrame::TermEnded {
        reason: "you closed the terminal".into(),
    });
    assert!(!a.pane_open(), "the pane is over");
    assert!(
        a.notice.is_none(),
        "an ending is not a notice: it is a row that is still there a minute later, and \
             the notice is what used to carry it and fade: {:?}",
        a.notice
    );
    let after = a.screen(80, 24);
    // **The program's own drawing is gone from the rectangle, and the only copy of it is
    // the ending's own quote of its last rows.** Asserted that way rather than as *the text
    // is nowhere*, because the row deliberately carries what the program printed — that is
    // the fix — and *the rectangle is the conversation's again* is the property.
    let heading = after
        .iter()
        .position(|r| r.contains("!term mc"))
        .expect("the ending is a row");
    assert!(
        after[heading].contains("you closed the terminal"),
        "the ending row carries the daemon's own sentence: {after:?}"
    );
    assert_eq!(
        after[heading + 1].trim(),
        "mc's screen",
        "and the program's last rows are quoted under it, indented — not drawn as the \
             rectangle they filled a moment ago: {after:?}"
    );
    assert_eq!(
        after.iter().filter(|r| r.contains("mc's screen")).count(),
        1,
        "one copy of what the program printed, and it is the ending's: {after:?}"
    );
    assert!(
        after.iter().any(|r| r.contains("! ls -la")),
        "and the transcript is back: {after:?}"
    );
}

/// **`!term close` asks before it ends anything, and only a deliberate yes ends it.**
///
/// The operator's rule, in their words: *"yeah it is pretty much a terminal emulator - if a
/// process runs then `ending` must ask"*. So the verb raises a card and sends **nothing**;
/// the frame leaves on `y` and on nothing else.
///
/// **Enter is deliberately not the yes**, and the two reasons are asserted here rather than
/// argued: Enter is the prompt card's own key (an empty line is a real answer there, so the
/// two cards would be answerable by the same keystroke) and it is the composer's, so a stray
/// one must not be able to kill a program. Esc cancels, and so does every other key — *the
/// safe default* is the whole shape of a destructive confirmation.
///
/// **And a detach never asks**, because it ends nothing: that is the point of it being the
/// default. Asserted beside the rest so the two acts are read together.
#[test]
fn a_term_close_asks_first_and_only_a_deliberate_yes_ends_anything() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    let _ = a.screen(80, 24);
    pane(&mut a, b"nano's screen\r\n");
    // The operator leaves first — a detach, and it raises no card at all.
    a.pane_keys(b"\x1c");
    assert!(!a.pane_open());
    assert!(
        a.term_ask.is_none(),
        "a detach ends nothing, so it asks nothing"
    );

    typed(&mut a, "!term close");
    assert_eq!(
        a.key(Key::Enter),
        None,
        "the verb itself sends nothing: it is the ASK"
    );
    let ask = a.term_ask.as_ref().expect("the confirmation is up");
    assert_eq!(
        ask.line, "!term mc",
        "the card names the program in the operator's own spelling"
    );
    let card = a.screen(80, 24);
    assert!(
        card.iter()
            .any(|r| r.contains("end the pane") && r.contains("!term mc")),
        "and it says what it is about to end: {card:?}"
    );
    assert!(
        card.iter().any(|r| r.contains("y ends it")),
        "both keys, and which one is the default: {card:?}"
    );

    // **Every key that is not a deliberate yes cancels**, Enter included — and the program
    // is still running afterwards.
    for k in [Key::Enter, Key::Esc, Key::Char('n'), Key::Up] {
        let mut b = app();
        b.session_id = "s".into();
        let _ = b.screen(80, 24);
        pane(&mut b, b"mc");
        // Detached first, because that is the only state `!term close` is reachable from:
        // a drawn pane owns the keyboard.
        b.pane_keys(b"\x1c");
        typed(&mut b, "!term close");
        assert_eq!(
            b.key(Key::Enter),
            None,
            "the verb itself sends nothing: it is the ASK"
        );
        assert!(b.term_ask.is_some(), "the confirmation is up");
        assert_eq!(
            b.key(k.clone()),
            None,
            "`{k:?}` must not end a program: the safe default is the cancel"
        );
        assert!(b.term_ask.is_none(), "and the card is down");
        assert!(
            b.term.is_some(),
            "`{k:?}`: the pane is still here — nothing was ended"
        );
    }

    // And the yes: the frame leaves, and the pane's keys stop while the kill is in flight.
    assert_eq!(a.key(Key::Char('Y')), Some(Action::TermClose));
    assert!(a.term_ask.is_none());
    assert!(
        a.pane_keys(b"x").is_empty(),
        "an ending is on its way: a byte written into a pty whose program is being \
             signalled is a byte nobody will read"
    );
}

/// **A close the head cannot answer from what it holds is ASKED FOR, not guessed.**
///
/// Two cases, and they are the reason [`PaneFact`] is a three-state: a session with no pane
/// (a sentence, and **nothing sent** — `TermClose` is quiet about there being nothing to
/// end, so a head that sent it would look like it had done something) and a pane the daemon
/// says is running in a head that does not hold it (a card that names `!term <command>`, the
/// string the daemon was handed).
///
/// The third state — *not asked yet* — is the one that would otherwise be read as *no pane*,
/// and it is asserted as the hold it is: the line goes out, and the answer runs the same
/// decision.
#[test]
fn a_close_the_head_cannot_answer_is_asked_for_and_not_guessed() {
    // No pane at all: the daemon said so.
    let mut a = app();
    a.session_id = "s".into();
    a.apply(ServerFrame::TermStatus { command: None });
    typed(&mut a, "!term close");
    assert_eq!(a.key(Key::Enter), None, "nothing is sent");
    assert!(a.term_ask.is_none(), "and no card: there is nothing to end");
    assert!(
        a.notice
            .as_deref()
            .is_some_and(|n| n.contains("no pane to end")),
        "the head says why rather than staying silent: {:?}",
        a.notice
    );

    // A pane the DAEMON holds and this head does not: the card names it.
    let mut b = app();
    b.session_id = "s".into();
    b.apply(ServerFrame::TermStatus {
        command: Some("mc /etc".into()),
    });
    typed(&mut b, "!term close");
    assert_eq!(b.key(Key::Enter), None);
    assert_eq!(
        b.term_ask.as_ref().map(|a| a.line.as_str()),
        Some("!term mc /etc"),
        "the card names what the daemon says is running"
    );
    assert_eq!(b.key(Key::Char('y')), Some(Action::TermClose));

    // **Not asked yet**: the read goes out and the line is HELD, then the same decision runs
    // on the answer. A head that read this as *no pane* would refuse to end a program the
    // operator can see.
    let mut c = app();
    c.session_id = "s".into();
    assert_eq!(c.term_fact, PaneFact::Unasked, "nothing has answered yet");
    typed(&mut c, "!term close");
    assert_eq!(
        c.key(Key::Enter),
        Some(Action::TermStatus),
        "the head asks rather than guessing"
    );
    assert!(c.close_pending, "and it holds the line");
    c.apply(ServerFrame::TermStatus {
        command: Some("nano notes.txt".into()),
    });
    assert!(!c.close_pending, "the answer runs the decision");
    assert_eq!(
        c.term_ask.as_ref().map(|a| a.line.as_str()),
        Some("!term nano notes.txt"),
        "and the card is the one the answer implies"
    );
}

/// **The pane's existence is drawn from the status read, and it is not a row.**
///
/// The operator's rule: a detach leaves no ending row, and *the pane's existence is a fact
/// the head draws from `TermStatus`*. So a head that is not drawing a pane the daemon says
/// is running draws **one line** above the composer, naming the program and both verbs, and
/// files nothing in the conversation; when the answer becomes `None` the line goes with it,
/// because it is a fact about now and not a disclosure about a moment.
#[test]
fn the_pane_line_is_drawn_from_the_status_read_and_is_not_a_row() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    let _ = a.screen(80, 24);
    assert!(
        !a.screen(80, 24)
            .iter()
            .any(|r| r.contains("a pane is running")),
        "nothing is drawn before the daemon has said anything"
    );

    a.apply(ServerFrame::TermStatus {
        command: Some("mc /etc".into()),
    });
    let frame = a.screen(80, 24);
    assert!(
        frame.iter().any(|r| r.contains("a pane is running")
            && r.contains("!term mc /etc")
            && r.contains("!term close")),
        "the line names what is running and both verbs: {frame:?}"
    );
    assert!(
        a.notes.is_empty(),
        "and it is NOT a row: a detach is not an event, so there is no ending to file"
    );

    // The daemon says there is nothing running any more: the line stops being true and goes.
    a.apply(ServerFrame::TermStatus { command: None });
    assert!(
        !a.screen(80, 24)
            .iter()
            .any(|r| r.contains("a pane is running")),
        "a fact that is no longer true is no longer drawn"
    );
}

/// **A question from the run takes the screen back from the confirmation.**
///
/// The operator's other rule: the two questions must not be confusable, and *neither may be
/// answerable by the other's keystroke*. They are exclusive by construction everywhere else —
/// the confirmation is typed at the composer and the prompt card owns the composer while it
/// is up — but a `PromptRequested` can arrive *while* the confirmation is standing, and then
/// `y` would mean two things: this card's yes and that card's text. So the confirmation
/// yields, with a sentence, and the program it was about is still running.
#[test]
fn a_question_from_the_run_takes_the_screen_back_from_the_confirmation() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    let _ = a.screen(80, 24);
    pane(&mut a, b"nano's screen\r\n");
    a.detach();
    typed(&mut a, "!term close");
    a.key(Key::Enter);
    assert!(a.term_ask.is_some());

    a.apply(ServerFrame::Event(env(
        1,
        SessionEvent::PromptRequested {
            req_id: "r1".into(),
            job: "j1".into(),
            command: "! sudo apt install mc".into(),
            question: Some("Continue? [Y/n]".into()),
        },
    )));
    assert!(a.term_ask.is_none(), "the confirmation yielded");
    assert!(a.prompt.is_some(), "and the program's question is up");
    assert!(
        a.notice
            .as_deref()
            .is_some_and(|n| n.contains("still running")),
        "the yield is said rather than silent: {:?}",
        a.notice
    );
    // **And `y` is the program's answer, not a kill**: the confirmation is gone, so the key
    // goes where the card that IS up says it goes.
    assert_eq!(a.key(Key::Char('y')), None);
    assert_eq!(a.prompt_buf, "y", "the letter reached the prompt card");
    assert!(a.term.is_some(), "nothing was ended");
}

/// **A bare `!term` after a detach attaches back to the SAME run.**
///
/// The operator's way back, and the whole of it is that the pane was never ended: the head
/// sends the bare verb, the daemon answers with what is running in the pane it kept and
/// replays the screen, and the head draws that screen again. A head that had *ended* the
/// pane on `ctrl-\` would be opening a new one here — or being refused.
#[test]
fn a_bare_term_line_after_a_detach_attaches_back_to_the_same_run() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    let _ = a.screen(80, 24);
    pane(&mut a, b"\x1b[2J\x1b[Hmc's screen\r\n");
    a.pane_keys(b"\x1c");
    assert!(!a.pane_open(), "detached");

    typed(&mut a, "!term");
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::TermOpen {
            line: "!term".into()
        }),
        "a bare `!term` is an attach: the daemon is asked for the pane it has"
    );
    assert!(
        a.pane_open(),
        "the rectangle is back before the daemon answers"
    );
    // The daemon's answer: the same command, and the screen it kept.
    a.apply(ServerFrame::TermAttached {
        command: "mc /etc".into(),
    });
    a.apply(ServerFrame::TermOutput {
        bytes: b"\x1b[2J\x1b[Hmc's screen\r\n".to_vec(),
    });
    assert_eq!(
        a.term.as_ref().map(|p| p.line.clone()),
        Some("!term mc /etc".into()),
        "and the line is the daemon's own name for the program — the same run"
    );
    assert!(
        a.screen(80, 24).iter().any(|r| r.contains("mc's screen")),
        "with the screen replayed into the rectangle"
    );
}

/// **A program that dies at once leaves its sentence and its status, and they stay.**
///
/// The operator's defect, in their words: *"i typed `!term mc`, it flashed and was gone"*.
/// The pane was taken, one sentence was posted as a **notice** — which lives for
/// `NOTICE_MS` of wall time — and what the program had printed went with the rectangle. A
/// person who looked a minute later, or who came back to the session, saw nothing at all.
///
/// So the assertion is on the **frame**, not on a notice: the row is still there when the
/// notice is cleared, it names the line that ran, the daemon's own sentence with the exit
/// status in it, and the last thing the program printed.
#[test]
fn a_pane_that_dies_at_once_leaves_a_row_with_its_sentence_and_its_status() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    a.clock(1_000);
    // **One frame before the key**, because a pane's rectangle is the *last frame's* —
    // `App::submit` says so, and it is what a head that has drawn anything always has. A
    // test that opened a pane before drawing would be asking a 1×1 screen what the program
    // left on it.
    let _ = a.screen(80, 24);
    pane(&mut a, b"mc: not found\r\n");
    a.apply(ServerFrame::TermEnded {
        reason: "the program exited with 127".into(),
    });
    assert!(!a.pane_open());

    // **A row and not a notice.** `say` is what carried this, and it is the whole reason
    // the ending was invisible: the notice is gone in `NOTICE_MS` and the row is not.
    assert!(
        a.notice.is_none(),
        "an ending is not a notice: {:?}",
        a.notice
    );
    a.clock(1_000 + 60_000);
    let frame = a.screen(80, 24);
    assert!(
        frame.iter().any(|r| r.contains("!term mc")),
        "the row names the line that was run: {frame:?}"
    );
    assert!(
        frame
            .iter()
            .any(|r| r.contains("the program exited with 127")),
        "and the daemon's own sentence, with the status in it: {frame:?}"
    );
    assert!(
        frame.iter().any(|r| r.contains("mc: not found")),
        "and the last thing the program printed — which is the sentence a person needs \
             when a program dies instantly: {frame:?}"
    );

    // **And a second pane that dies the same way is a second row.** The identity a note is
    // deduped by cannot tell two identical endings apart, so a pane's ending is filed without
    // the redelivery test — otherwise the second `!term mc` would be swallowed by the first.
    pane(&mut a, b"mc: not found\r\n");
    a.apply(ServerFrame::TermEnded {
        reason: "the program exited with 127".into(),
    });
    let rows = a
        .screen(80, 24)
        .iter()
        .filter(|r| r.contains("!term mc"))
        .count();
    assert_eq!(
        rows,
        2,
        "two endings are two rows, however alike they are: {:?}",
        a.screen(80, 24)
    );
}

/// **A program that ends on its own is the same frame as a refusal to start**, and the
/// sentence is the whole of the difference.
#[test]
fn a_pane_that_ends_on_its_own_closes_the_same_way_a_refusal_does() {
    let mut a = app();
    a.session_id = "s".into();
    a.head_id = "h1".into();
    pane(&mut a, b"bye\r\n");
    a.apply(ServerFrame::TermEnded {
        reason: "the program exited with 3".into(),
    });
    assert!(!a.pane_open());
    assert!(
        a.screen(80, 24)
            .iter()
            .any(|r| r.contains("the program exited with 3")),
        "the ending is a row, and the reason the daemon gave is on it: {:?}",
        a.screen(80, 24)
    );

    // And a `TermEnded` for a pane this head never opened — a second head attached to the
    // same session, which the frames are fanned out to — is dropped rather than said: it is
    // not this head's pane and it has no rectangle to restore.
    let mut b = app();
    b.session_id = "s".into();
    b.apply(ServerFrame::TermEnded {
        reason: "the program exited with 0".into(),
    });
    assert!(b.notice.is_none(), "{:?}", b.notice);
    // The same for the bytes: a pane nobody opened is not opened by them.
    b.apply(ServerFrame::TermOutput {
        bytes: b"nobody's screen".to_vec(),
    });
    assert!(!b.pane_open());
}

/// Drive an app from a hub the way the real driver does.
fn feed(app: &mut App, hub: &Hub, head_id: &str) -> (u64, u64) {
    let (mut r, mut f) = (0, 0);
    while let letibot_sessionlog::hub::Delivery::Events(b) = hub.next_batch(head_id, 512) {
        for env in b.events() {
            match app.apply(ServerFrame::Event(env.clone())) {
                Disposition::Rendered => r += 1,
                Disposition::Filtered => f += 1,
                Disposition::Control => {}
            }
        }
        if b.len() < 512 {
            break;
        }
    }
    (r, f)
}

/// **R10: a note the operator has read can be retired, and it stays retired.**
///
/// Four things, and they are one behaviour. A note is a **disclosure, not a
/// permanent record**: the session log holds the durable fact and the note is how a
/// head shows it once, so a reader must be able to retire one they have read. A
/// retired note must **stay** retired across a resync, a reattach and a **restart** —
/// a snapshot replanting what somebody just dismissed is the same defect as never
/// letting them dismiss it. And it must not **drop** the fact: hidden, counted and
/// findable, which is the rule `/status`'s own `filtered` counter already keeps.
///
/// **R19 moved the two halves of this test, and made the second of them harder.** The
/// note is filed **live** here, because a note that arrives with a snapshot is no
/// longer planted at all — so what has to be proved about the *resync* is now that a
/// retired note is not drawn, and what has to be proved about the *restart* is that a
/// retirement loaded from `head.toml` beats a **live** delivery, which is the one case
/// where nothing else would stop it. (The operator's own wall had none of this
/// retired: fault 1 is why it was up.)
/// **R22: clearing your own screen costs one key, and it keeps every rule R10 bought.**
///
/// The operator, on being told how to hide a note: *"typing `/notes dismiss all` is not
/// humane."* So the reflex is a chord — `ctrl-n` — and this test is the whole of what it
/// must not break: **retired is not deleted.** The notes stay, `/notes` prints them,
/// `/status` counts them, `/notes restore` brings them back, and the reflex survives a
/// restart (R19 part 3) so it does not have to be repeated.
///
/// The agreement with the other head is in `head-parity-2026-09-21.md` §R22 and is
/// asserted here as behaviour rather than restated: **all of them, not the newest**, and
/// the empty press says so.
#[test]
fn ctrl_n_retires_every_note_and_keeps_every_note() {
    let hub = Hub::new("s");
    hub.publish(testing::turn_started("t1"));
    let mut a = app();
    a.clock(1_000);
    a.apply(hello("s", vec![brief("s", "one", false)], hub.snapshot()));
    // Four notes, which is the shape the operator actually reported: R19's restart was
    // four notes at three lines each, and R10's wall was two.
    for (code, detail) in [
        (
            "gate_timeout",
            "denied: nobody answered before the deadline",
        ),
        ("daemon_stopping", "`dead` asked this daemon to stop"),
        ("compacted", "compacted: 940188 → 9181 tokens"),
        (
            "auto_compact",
            "938065 of 999999 tokens resident — compacting now",
        ),
    ] {
        let e = hub.publish(SessionEvent::Warning {
            code: code.into(),
            detail: detail.into(),

            compaction: None,
        });
        a.apply(ServerFrame::Event(e));
    }
    let before = a.screen(100, 30).join("\n");
    assert!(before.contains("gate_timeout"), "{before}");
    assert!(before.contains("auto_compact"), "{before}");

    // **One key, and the wall goes.**
    assert_eq!(a.key(Key::CtrlN), None, "the chord is not a daemon action");
    let after = a.screen(100, 30).join("\n");
    for code in [
        "gate_timeout",
        "daemon_stopping",
        "compacted",
        "auto_compact",
    ] {
        assert!(
            !after.contains(code),
            "`{code}` survived the press:\n{after}"
        );
    }
    // **And it says what it did, in the VERB's own words** — because it calls the verb
    // rather than composing a second sentence. That is the property worth asserting here:
    // a chord with its own wording is a chord that can come to disagree with `/notes
    // dismiss all` about what just happened. `(not saved: ...)` is in this frame because
    // this test's head has no `head.toml`; that suffix is the same writer's too.
    assert!(after.contains("retired 4 note(s)"), "{after}");
    assert!(after.contains("still counted on /status"), "{after}");

    // **Not deleted.** Every one is still held, still counted, still readable.
    assert_eq!(a.notes.len(), 4, "a note was dropped, not retired");
    assert_eq!(a.retired_notes(), 4);
    a.command("status");
    let stats = a.screen(120, 60).join("\n");
    assert!(stats.contains("4 retired"), "{stats}");
    a.key(Key::Esc);
    typed(&mut a, "/notes");
    a.key(Key::Enter);
    let listed = a.screen(120, 60).join("\n");
    assert!(listed.contains("nobody answered"), "{listed}");
    assert!(listed.contains("[retired]"), "{listed}");
    a.key(Key::Esc);

    // **A second press says there is nothing left to retire.** Not "retired 0 note(s)",
    // which is what the verb would say and is a sentence an operator should not be shown:
    // the notes are held but retired, so the count of what is LEFT is zero.
    assert_eq!(a.key(Key::CtrlN), None);
    let twice = a.screen(100, 30).join("\n");
    assert!(twice.contains("nothing to retire"), "{twice}");
    assert!(!twice.contains("retired 0 note(s)"), "{twice}");

    // **And back, if the reader was wrong** — the undo is exactly as cheap as the act.
    typed(&mut a, "/notes restore");
    a.key(Key::Enter);
    let back = a.screen(100, 30).join("\n");
    assert!(back.contains("gate_timeout"), "restore did nothing: {back}");
    assert!(
        back.contains("/notes restore") || back.contains("back on the screen"),
        "{back}"
    );
}

/// **The reflex survives a restart** (R22 + R19 part 3), which is the half that stops it
/// having to be repeated — and the half that used to be B's requirement and became A's
/// when the operator hit it.
#[test]
fn a_note_retired_with_ctrl_n_stays_retired_across_a_restart() {
    let hub = Hub::new("s");
    hub.publish(testing::turn_started("t1"));
    let clean = hub.snapshot();
    let mut a = app();
    a.apply(hello("s", vec![brief("s", "one", false)], clean.clone()));
    let live = hub.publish(SessionEvent::Warning {
        code: "gate_timeout".into(),
        detail: "denied: nobody answered before the deadline".into(),

        compaction: None,
    });
    a.apply(ServerFrame::Event(live.clone()));
    assert!(a.screen(100, 30).join("\n").contains("gate_timeout"));

    // A real file, because the property is about the file.
    let dir = std::env::temp_dir().join(format!("letibot-r22-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.join("head.toml");
    a.prefs_path = Some(path.clone());
    a.key(Key::CtrlN);
    assert!(
        !a.screen(100, 30).join("\n").contains("gate_timeout"),
        "the chord did not retire it"
    );
    assert!(path.is_file(), "the press did not reach head.toml");

    // A new head, the same file, the incident delivered **live** — the one delivery
    // nothing else suppresses (a snapshot's copy is prior, a redelivery is not filed
    // twice), so what stops it here is the persisted retirement and nothing else.
    let mut b = app();
    b.prefs_path = Some(path.clone());
    b.load_prefs();
    assert_eq!(b.dismissed.len(), 1, "{:?}", b.dismissed);
    b.apply(hello("s", vec![brief("s", "one", false)], clean));
    b.apply(ServerFrame::Event(live));
    let after = b.screen(100, 30).join("\n");
    assert!(
        !after.contains("gate_timeout"),
        "a restart replanted what ctrl-n retired:\n{after}"
    );
    assert_eq!(b.notes.len(), 1, "hidden, not dropped: {:?}", b.notes);
    let _ = std::fs::remove_dir_all(&dir);
}

/// **The chord is the head's, is named where it is advertised, and moves nothing else.**
///
/// Three separate things a chord has to get right, and each has already been got wrong
/// somewhere in this file: it must not type into the composer, it must be on the hint bar
/// where the operator can actually see it (the bar is longer than a terminal and trimmed),
/// and it must not move a fold or open a pane.
#[test]
fn the_notes_chord_is_advertised_where_it_can_be_seen_and_reaches_nothing_else() {
    let mut a = app();
    typed(&mut a, "hello");
    a.key(Key::CtrlN);
    assert_eq!(a.input(), "hello", "ctrl-n typed into the composer");
    assert_eq!(a.reasoning, Fold::Folded, "ctrl-n moved the thinking fold");
    assert_eq!(a.tools, Fold::Folded, "ctrl-n moved the tool-output fold");
    assert!(
        !a.jobs_pane && !a.todos_pane && !a.picker,
        "ctrl-n opened a pane"
    );
    assert!(!a.raw_calls, "ctrl-n toggled the raw view");

    // **On the bar, at 80 columns.** The bar is 151 columns now and the frame trims it,
    // so a chord appended to the end is a chord nobody can see — measured, not assumed.
    let bar = a.screen(80, 24).join("\n");
    assert!(
        bar.contains("ctrl-n notes"),
        "the chord is advertised but not visible at 80 columns:\n{bar}"
    );
    // And it does not push `ctrl-s` off, which is what the bar opens with.
    assert!(bar.contains("ctrl-s sessions"), "{bar}");

    // `/help` names it, with the rule that matters on the line.
    a.command("help");
    let help = a.screen(120, 60).join("\n");
    assert!(help.contains("ctrl-n"), "{help}");
    assert!(
        help.contains("Retired is not deleted"),
        "the row must carry the rule R10 bought: {help}"
    );
}

#[test]
fn a_note_the_operator_has_read_can_be_retired_and_stays_retired() {
    let hub = Hub::new("s");
    hub.publish(testing::turn_started("t1"));
    // **The snapshot from before the incident**, which is what the restarted head gets:
    // a head that attached and *then* watched it happen. Taken here rather than inside
    // the restart block below, because by then the hub carries the warning and a head
    // whose snapshot already holds it would not be the live case at all.
    let clean = hub.snapshot();

    let mut a = app();
    a.clock(1_000);
    // Attached *before* the warning exists, so the head is there to see it happen:
    // this is the live path, which is the only path that plants a note now.
    a.apply(hello("s", vec![brief("s", "one", false)], hub.snapshot()));
    let published = hub.publish(SessionEvent::Warning {
        code: "gate_timeout".into(),
        detail: "denied: nobody answered before the deadline".into(),

        compaction: None,
    });
    a.apply(ServerFrame::Event(published.clone()));
    let screen = a.screen(100, 30).join("\n");
    assert!(screen.contains("gate_timeout"), "{screen}");

    // **Retired, and the wall goes — including its blank line.** The sentence said
    // `/notes`, so that is the verb; `/dismiss` is the same act under the word a
    // person types at a red block.
    typed(&mut a, "/dismiss");
    assert_eq!(a.key(Key::Enter), None);
    let hidden = a.screen(100, 30).join("\n");
    assert!(
        !hidden.contains("gate_timeout"),
        "still on the screen: {hidden}"
    );
    assert!(!hidden.contains("nobody answered"), "{hidden}");

    // **Hidden is not deleted.** The note is still this head's, `/status` counts it,
    // and `/notes` lists it with its text under a marker — the rule `/status`'s own
    // `filtered` counter keeps, which is what makes "I chose not to show this" a
    // different statement from "nothing happened".
    assert_eq!(a.notes.len(), 1, "the note was dropped, not retired");
    assert_eq!(a.retired_notes(), 1);
    a.command("status");
    let stats = a.screen(120, 60).join("\n");
    assert!(stats.contains("1 retired"), "{stats}");
    a.key(Key::Esc);
    typed(&mut a, "/notes");
    a.key(Key::Enter);
    let listed = a.screen(120, 60).join("\n");
    assert!(listed.contains("nobody answered"), "{listed}");
    assert!(listed.contains("[retired]"), "{listed}");
    a.key(Key::Esc);

    // **The two things that used to replant it.** A resync replaces the head's whole
    // note list from a snapshot — *everything in a snapshot is history and none of it
    // is anchored* — so before R10 the wall came back at position 0, above the whole
    // conversation, on an operation the operator did not ask for. The identity is
    // built from the log (code, ts, detail) and not from the screen, so the snapshot's
    // copy is the same key and stays retired.
    let key = note_key(&a.notes[0].1);
    a.apply(ServerFrame::Resync {
        reason: "queue overflow".into(),
        dropped: 0,
        snapshot: Box::new(hub.snapshot()),
        scrubbed: Default::default(),
    });
    let after_resync = a.screen(100, 30).join("\n");
    assert!(
        !after_resync.contains("gate_timeout"),
        "a resync replanted what was dismissed: {after_resync}"
    );
    // A reattach is the same event from the other direction: the same `Hello`, the
    // same snapshot, a new window.
    a.apply(hello("s", vec![brief("s", "one", false)], hub.snapshot()));
    assert!(
        !a.screen(100, 30).join("\n").contains("gate_timeout"),
        "a reattach replanted it"
    );

    // **The restart, and the half R19 made harder.** The dismissals live in
    // `head.toml` and not in the process, and a head that has just started has shown
    // nothing — so the incident is delivered to `b` **live**, at a seam, which is the
    // one delivery nothing else would suppress: a snapshot's copy is not drawn for being
    // prior, and a redelivery is not filed twice. What stops it here is the retirement
    // this head read off the file, against the same `clean` snapshot (no warning in it)
    // that `a` attached to.
    let dir = std::env::temp_dir().join(format!("letibot-notes-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.join("head.toml");
    crate::prefs::save(
        &path,
        &crate::prefs::HeadPrefs {
            retired: vec![key.clone()],
            ..Default::default()
        },
    )
    .unwrap();
    let mut b = app();
    b.prefs_path = Some(path.clone());
    b.load_prefs();
    assert_eq!(
        b.dismissed,
        vec![key.clone()],
        "the file's retired set did not reach the head"
    );
    b.apply(hello("s", vec![brief("s", "one", false)], clean));
    b.apply(ServerFrame::Event(published.clone()));
    assert!(
        !b.screen(100, 30).join("\n").contains("gate_timeout"),
        "a restart replanted it: dismissed={:?} key={key:?}",
        b.dismissed
    );
    assert_eq!(b.notes.len(), 1, "hidden, not dropped: {:?}", b.notes);

    // **And back, if the reader was wrong.** Two ways, and both of them are the
    // reader's: no dismissal is ever final in a way they cannot undo.
    typed(&mut b, "/notes restore");
    b.key(Key::Enter);
    let back = b.screen(100, 30).join("\n");
    assert!(back.contains("gate_timeout"), "restore did nothing: {back}");
    // **And the FILE, which this test used to skip.** Restoring on the screen while the
    // file kept the key is the defect leticl reported: the two disagreed and the next
    // save by any head put the dismissal back, so `restore` lasted until somebody else
    // saved. Asserted here because the screen alone could not tell the two apart.
    let (p, _) = crate::prefs::load(&path);
    assert!(
        !p.retired.iter().any(|k| k == &key),
        "restore did not reach the file: {:?}",
        p.retired
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// **A dismissal unions; a restore replaces** — leticl's report, as a test.
///
/// leticl found this rather than fixing it, and the shape of the fault is worth keeping:
/// a union can only ever ADD a key, so under a union a restore's save wrote the file's own
/// keys straight back, the head's `dismissed` went to `[]` while the file kept the key, and
/// the two disagreed — which is the SAME class of fault `merge_retired` was written to end,
/// arriving from the other direction. A restore is an assertion of removal, and only a
/// replacement can say it.
#[test]
fn a_restore_replaces_the_files_set_and_a_dismissal_unions_with_it() {
    let dir = std::env::temp_dir().join(format!("letibot-restore-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.join("head.toml");

    // Another head retired one key before this head ever looked.
    crate::prefs::save(
        &path,
        &crate::prefs::HeadPrefs {
            retired: vec!["w|theirs|1|aaaa".into()],
            ..Default::default()
        },
    )
    .unwrap();

    let mut a = app();
    a.prefs_path = Some(path.clone());
    a.dismissed = vec!["w|mine|2|bbbb".into()];

    // A dismissal unions: the other head's key survives this head's save.
    let _ = a.save_prefs(RetiredWrite::Union);
    let (p, _) = crate::prefs::load(&path);
    assert!(
        p.retired.iter().any(|k| k == "w|theirs|1|aaaa"),
        "a dismissal discarded another head's key: {:?}",
        p.retired
    );
    assert!(
        p.retired.iter().any(|k| k == "w|mine|2|bbbb"),
        "{:?}",
        p.retired
    );

    // A restore replaces: this head's set is the whole truth, and nothing comes back.
    a.dismissed.clear();
    let _ = a.save_prefs(RetiredWrite::Replace);
    let (q, _) = crate::prefs::load(&path);
    assert!(
        q.retired.is_empty(),
        "a restore did not remove the keys — the next save by any head would put them \
             back and `restore` would be a verb whose effect lasts until somebody else \
             saves: {:?}",
        q.retired
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// **The operator's own state, reproduced from the measurement rather than guessed.**
///
/// 2026-09-22, on his screen: `/notes` said `7 note(s), 1 retired` and only one entry
/// carried `[retired]`, while `head.toml` held keys for the notes that were listed.
/// `cargo run --example dump_notes` put the two lists side by side against the live log
/// and found six of the seven keys **identical — code, clock and detail hash** — so the
/// file and the log agreed, and the odd one out was the head's own `dismissed`.
///
/// The six facts below are the real ones: the real clock and the real sentence, each
/// asserted against the key `head.toml` actually held. A transcription slip fails here
/// rather than passing quietly as a different incident.
#[test]
fn the_head_retires_every_note_the_file_it_wrote_says_it_retired() {
    let facts: [(&str, u64, &str); 6] = [
        (
            "mode_set",
            1790080806043,
            "this session is at `allow-all (this box, consented)` from the next call \
                 — nothing confines this box, and this point stands on your confirmation \
                 rather than on a boundary.",
        ),
        (
            "context_wall",
            1790104751092,
            "stopping this turn after 22 round(s)",
        ),
        (
            "auto_compact",
            1790104751092,
            "938785 of 999999 tokens resident",
        ),
        (
            "compacted",
            1790104765616,
            "compacted: 941052 → 8748 tokens",
        ),
        (
            "auto_compact",
            1790104765616,
            "compacted: 8748 tokens resident now",
        ),
        ("promote_idle", 1790108290718, "nothing was running to move"),
    ];

    // The shape the head's own file must have honoured: every one of them retired,
    // written as the file writes it and read back through the file's own parser.
    let dir = std::env::temp_dir().join(format!("letibot-operator-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.join("head.toml");
    let keys: Vec<String> = facts
        .iter()
        .map(|(code, ts, detail)| {
            note_key(&Note::Warned(Warned {
                code: (*code).into(),
                detail: (*detail).into(),
                ts: *ts,
            }))
        })
        .collect();
    crate::prefs::save(
        &path,
        &crate::prefs::HeadPrefs {
            retired: keys.clone(),
            ..Default::default()
        },
    )
    .unwrap();

    let mut a = app();
    a.prefs_path = Some(path.clone());
    a.load_prefs();
    assert_eq!(
        a.dismissed, keys,
        "the file's retired set did not reach the head"
    );

    // The same six, delivered as the log delivers them: a snapshot, with the clock
    // each envelope carried.
    let mut snapshot = Snapshot {
        session_id: "s".into(),
        seq: 1,
        dropped: 0,
        items_dropped: 0,
        items: Vec::new(),
        turn: None,
        open_decisions: Vec::new(),
        settled_decisions: Vec::new(),
        warnings: facts
            .iter()
            .map(|(code, ts, detail)| Warned {
                code: (*code).into(),
                detail: (*detail).into(),
                ts: *ts,
            })
            .collect(),
        heads: Vec::new(),
        subagents: Vec::new(),
    };
    snapshot.warnings.truncate(facts.len());
    a.apply(hello("s", vec![brief("s", "one", false)], snapshot));

    assert_eq!(a.notes.len(), facts.len(), "{:?}", a.notes);
    assert_eq!(
        a.retired_notes(),
        facts.len(),
        "the file says {} retired and the head retired {}: dismissed={:?}",
        facts.len(),
        a.retired_notes(),
        a.dismissed
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// **A dismissal a SECOND head made is honoured by this one, without a restart.**
///
/// The operator's report of 2026-09-22 — *"i dismissed letibot notes but they stay"*
/// — and the half of it that a shared file makes possible. `~/.config/letibot/head.toml`
/// is one file for every head on the box, and `load_prefs` runs **once, at startup**:
/// two heads were running (measured: pids 2076943 and 2350959), so what one of them
/// retired after the other had loaded was invisible to it for the rest of its life.
///
/// The path here is the operator's exactly: `a` loads the file, *then* the file gains a
/// key, and `a` is asked for the listing. Before `refresh_retired` the note was still on
/// the screen; the assertion is that it is not.
#[test]
fn a_dismissal_recorded_after_this_head_loaded_is_honoured_anyway() {
    let dir = std::env::temp_dir().join(format!("letibot-shared-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.join("head.toml");

    // One head, up first, attaching to a log that already holds one warning.
    let hub = Hub::new("s");
    let live = hub.publish(SessionEvent::Warning {
        code: "gate_timeout".into(),
        detail: "nobody answered within 300s".into(),

        compaction: None,
    });
    let mut a = app();
    a.prefs_path = Some(path.clone());
    a.load_prefs();
    a.apply(hello("s", vec![brief("s", "one", false)], hub.snapshot()));
    assert_eq!(a.notes.len(), 1);
    assert_eq!(a.retired_notes(), 0, "nothing retired yet");

    // **A second head retires it.** Not a call into `a` — a write to the file this
    // head will look at, which is the only thing the two processes share.
    let key = note_key(&a.notes[0].1);
    crate::prefs::save(
        &path,
        &crate::prefs::HeadPrefs {
            retired: vec![key.clone()],
            ..Default::default()
        },
    )
    .unwrap();

    // **Before it looks, this head does not know.** `dismissed` is what it loaded at
    // startup, and the file has moved since — which is the state the operator was in.
    assert_eq!(
        a.retired_notes(),
        0,
        "the premise is a head that has not read the file since it changed, and this \
             one already had: dismissed={:?}",
        a.dismissed
    );
    typed(&mut a, "/notes");
    a.key(Key::Enter);
    let listed = a.screen(120, 60).join("\n");
    assert!(
        listed.contains("[retired"),
        "the listing showed a note the file says is retired as live:\n{listed}"
    );
    assert!(listed.contains("1 retired"), "{listed}");
    let _ = std::fs::remove_dir_all(&dir);

    // And the same envelope arriving again lands retired rather than planting
    // itself — the redelivery half of R10, now with the key read off the file
    // rather than out of this head's own memory.
    a.key(Key::Esc);
    a.apply(ServerFrame::Event(live.clone()));
    let screen = a.screen(120, 60).join("\n");
    assert!(
        !screen.contains("nobody answered"),
        "a note retired by another head came back at a seam:\n{screen}"
    );
}

/// **One head's save does not discard another head's dismissals.**
///
/// The write half of the same repair, and the one that explains the operator seeing
/// MORE keys in `head.toml` than his head honoured. Both heads load once and each used
/// to write its own list back whole; `merge_retired` makes the file grow instead, so a
/// key survives a save that never heard of it.
#[test]
fn a_save_keeps_a_key_this_head_never_loaded() {
    let dir = std::env::temp_dir().join(format!("letibot-union-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.join("head.toml");

    // The other head got there first.
    crate::prefs::save(
        &path,
        &crate::prefs::HeadPrefs {
            retired: vec!["w|mode_set|1|aaaa".into()],
            ..Default::default()
        },
    )
    .unwrap();

    // This one loaded the file BEFORE that key existed, then saves for its own
    // reasons — a config row toggled, say.
    let mut a = app();
    a.prefs_path = Some(path.clone());
    a.dismissed = vec!["w|promote_idle|2|bbbb".into()];
    let _ = a.save_prefs(RetiredWrite::Union);

    let (p, _) = crate::prefs::load(&path);
    assert!(
        p.retired.iter().any(|k| k == "w|mode_set|1|aaaa"),
        "the save discarded another head's dismissal: {:?}",
        p.retired
    );
    assert!(
        p.retired.iter().any(|k| k == "w|promote_idle|2|bbbb"),
        "the save lost this head's own dismissal: {:?}",
        p.retired
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// **R19's first fault: history arrives as news.**
///
/// The operator restarted a head and was met by twelve red lines — four notes,
/// `daemon_stopping`, `compacted` and two `auto_compact`, folded correctly to three
/// lines each, at the top of a session that had just started: *"i dont want to see
/// that on restart."* **None of them had been dismissed**, which is why persisting a
/// retired set would not have helped. A head that has just attached has shown nothing,
/// so it was replaying hours of announcements as though they had just happened, above
/// a conversation they did not precede: *a warning is how a head shows a fact ONCE.*
///
/// Four assertions and a control: the screen has none of them; the head still holds
/// them; `/status` counts them; `/notes` lists them with their text; and a warning
/// that arrives **while the head is watching** is still drawn, because that is what a
/// note is for.
#[test]
fn a_fresh_attach_shows_the_conversation_and_not_what_came_before_it() {
    let hub = Hub::new("s");
    hub.publish(testing::turn_started("t1"));
    for (code, detail) in [
        (
            "daemon_stopping",
            "`dead` asked this daemon to stop. Every head detaches",
        ),
        (
            "auto_compact",
            "938065 of 999999 tokens resident — compacting now",
        ),
        (
            "compacted",
            "compacted: 940188 → 9181 tokens, on transcript s#t25",
        ),
    ] {
        hub.publish(SessionEvent::Warning {
            code: code.into(),
            detail: detail.into(),

            compaction: None,
        });
    }

    let mut a = app();
    a.apply(hello("s", vec![brief("s", "one", false)], hub.snapshot()));
    let screen = a.screen(100, 30).join("\n");
    for code in ["daemon_stopping", "auto_compact", "compacted"] {
        assert!(
            !screen.contains(code),
            "`{code}` was planted above a conversation it did not precede:\n{screen}"
        );
    }
    assert!(
        !screen.contains("940188"),
        "the note's text is on the screen, so it is not only the code that leaks:\n{screen}"
    );

    // **Held, counted, listed** — the three things R19 asks for instead of drawing
    // them. `/notes` is where the fix puts them and `/status` is how a reader knows
    // there is something there.
    assert_eq!(a.notes.len(), 3, "{:?}", a.notes);
    assert_eq!(a.notes_before(), 3);
    assert_eq!(a.retired_notes(), 0);
    a.command("status");
    let stats = a.screen(120, 60).join("\n");
    assert!(
        stats.contains("3 from before this window"),
        "`/status` must say why they are not on the screen:\n{stats}"
    );
    a.key(Key::Esc);
    typed(&mut a, "/notes");
    a.key(Key::Enter);
    let listed = a.screen(120, 60).join("\n");
    assert!(listed.contains("940188"), "{listed}");
    assert!(listed.contains("[before this window]"), "{listed}");
    a.key(Key::Esc);

    // **The control, and without it this test would pass on a head that draws no
    // notes at all.** A fact that happens while this head is watching is news, and
    // news is drawn where it happened.
    let live = hub.publish(SessionEvent::Warning {
        code: "context_wall".into(),
        detail: "stopping this turn: the window is full".into(),

        compaction: None,
    });
    a.apply(ServerFrame::Event(live));
    let after = a.screen(100, 30).join("\n");
    assert!(
        after.contains("context_wall"),
        "a warning that arrives live must still be drawn:\n{after}"
    );
    assert_eq!(a.notes.len(), 4);
    assert_eq!(a.notes_before(), 3, "only the snapshot's three are prior");
}

/// **Five facts, five lines — leticl's measurement, as a test.**
///
/// leticl ran three real `decision_requested` frames through a scratch head and read the
/// cards: **every field a head controls was identical** across *could not decide*,
/// *unreadable* and *out of room* — `would: "ask"`, `consulted: true`, `cites: []` — and
/// the card echoed the daemon's prose and authored nothing. `would: "ask"` is *also* what
/// `NotAuthorised` sets, so five distinct facts reached the glass as one line.
///
/// The assertion is **pairwise difference**: for each of the five, the rendered line must
/// differ from every other. A test that only checked "the field is carried" would pass
/// against a head that ignored it, which is the half that was already broken.
#[test]
fn the_five_facts_behind_one_ask_are_five_lines_on_the_card() {
    use letibot_sessionlog::event::OptionKind;
    let a = app();
    let rendered = |unsure: Option<&str>, would: &str| -> String {
        let mut d = decision_with(&[OptionKind::AllowOnce, OptionKind::RejectOnce]);
        d.advice = Some(letibot_sessionlog::event::ModelAdvice {
            consulted: true,
            would: would.into(),
            by: "model:test".into(),
            basis: "THE-BASIS".into(),
            cites: Vec::new(),
            unsure: unsure.map(str::to_string),
            latency_ms: 12,
        });
        a.decision_lines(&d, 100).join("\n")
    };

    // The four ways of NOT answering, and the fifth which is an answer.
    let five = [
        ("could_not_decide", "ask"),
        ("between_thresholds", "ask"),
        ("unreadable", "ask"),
        ("out_of_room", "ask"),
        // The fifth: consulted, answered, and the answer was no. `unsure: None`.
        ("", "ask"),
    ];
    let mut seen: Vec<(String, String)> = Vec::new();
    for (unsure, would) in five {
        let screen = rendered(
            if unsure.is_empty() {
                None
            } else {
                Some(unsure)
            },
            would,
        );
        assert!(
            screen.contains("THE-BASIS"),
            "the daemon's sentence must still be there ({unsure:?}):\n{screen}"
        );
        for (other_unsure, other_screen) in &seen {
            assert_ne!(
                &screen, other_screen,
                "`{unsure}` and `{other_unsure}` render identically — which is the five-\
                     facts-one-line defect this field exists to end"
            );
        }
        seen.push((unsure.to_string(), screen));
    }
    // And a kind this head does not know is shown rather than folded into one of the
    // four, so a daemon that gains a fifth is visible.
    let unknown = rendered(Some("fifth_kind"), "ask");
    assert!(unknown.contains("fifth_kind"), "{unknown}");
}

/// **R19's second fault: routine is painted as failure.**
///
/// `compacted` and `auto_compact` are the session doing exactly what it should, and
/// they arrived in the same red as a denial or a gate timeout — *the colour asserted a
/// severity the fact did not have*, which is why four notes read as a wall. **A
/// housekeeping notice and a refused call must not look alike.**
///
/// Asserted on the bytes rather than the look, and on both registers in one frame: a
/// routine code loses the `!` and the red, a failure keeps both. The split itself is
/// `letibot_sessionlog::warning`'s (the codes are the log's vocabulary and both heads
/// render them), so what this test pins is what *this* head does with it.
#[test]
fn a_routine_notice_is_not_drawn_in_the_failure_register() {
    const RED: &str = "\u{1b}[31m";
    let mut a = App::new(RenderConfig {
        width: 100,
        color: true,
        ..RenderConfig::default()
    });
    for (code, detail) in [
        ("compacted", "compacted: 940188 → 9181 tokens"),
        ("context_wall", "stopping this turn after 12 rounds"),
    ] {
        a.apply(ServerFrame::Event(env(
            1,
            SessionEvent::Warning {
                code: code.into(),
                detail: detail.into(),

                compaction: None,
            },
        )));
    }
    let frame = a.screen(100, 30);
    let line = |needle: &str| {
        frame
            .iter()
            .find(|l| l.contains(needle))
            .unwrap_or_else(|| panic!("nothing drew `{needle}`:\n{}", frame.join("\n")))
            .clone()
    };
    let routine = line("compacted");
    assert!(
        !routine.contains(RED),
        "a compaction was painted in the failure colour: {routine:?}"
    );
    assert!(
        routine.contains('·'),
        "not the routine register: {routine:?}"
    );
    assert!(
        !routine.contains('!'),
        "the alarm glyph is on a housekeeping line: {routine:?}"
    );
    let failure = line("context_wall");
    assert!(
        failure.contains(RED),
        "a wall must keep the red: {failure:?}"
    );
    assert!(
        failure.contains('!'),
        "a failure must keep the alarm glyph: {failure:?}"
    );
}

/// **R29 part two: the reader's own input refused is a THIRD register**, and it is
/// neither of the two above.
///
/// The operator, on a red note for a mistyped `/qwe` sitting in the same colour as
/// `ledger_chain_mismatch`: *"red is stop the world event … a mistyped /qwe is not a
/// session in trouble."* The census is 7 of 46 failure codes (`Class`'s docs), and this
/// asserts what the *head* does with them: its own mark, the notice colour, and neither
/// of the two things the other registers use.
///
/// **All three in one frame**, because the defect is a *comparison* — a reader learns the
/// register by seeing two notes side by side — and a test that drew them one at a time
/// could pass while they looked identical.
#[test]
fn the_three_registers_are_three_marks() {
    const RED: &str = "\u{1b}[31m";
    const YELLOW: &str = "\u{1b}[33m";
    let mut a = App::new(RenderConfig {
        width: 100,
        color: true,
        ..RenderConfig::default()
    });
    for (code, detail) in [
        ("compacted", "compacted: 940188 → 9181 tokens"),
        (
            "slash_refused",
            "/qwe is not a daemon verb; /help lists the head's",
        ),
        (
            "ledger_chain_mismatch",
            "row 41's head is not the one that was stored",
        ),
    ] {
        a.apply(ServerFrame::Event(env(
            1,
            SessionEvent::Warning {
                code: code.into(),
                detail: detail.into(),
                compaction: None,
            },
        )));
    }
    let frame = a.screen(100, 30);
    let line = |needle: &str| {
        frame
            .iter()
            .find(|l| l.contains(needle))
            .unwrap_or_else(|| panic!("nothing drew `{needle}`:\n{}", frame.join("\n")))
            .clone()
    };
    let (routine, refused, failure) = (
        line("compacted"),
        line("slash_refused"),
        line("ledger_chain_mismatch"),
    );
    // The three marks, and they are three DIFFERENT marks — which is what survives a
    // `--replay`, a pipe and a light theme, where the colours do not.
    assert!(routine.contains("· compacted"), "{routine:?}");
    assert!(refused.contains("× slash_refused"), "{refused:?}");
    assert!(failure.contains("! ledger_chain_mismatch"), "{failure:?}");
    // The colours: a typo is not red, and it is not the housekeeping dim either.
    assert!(
        !refused.contains(RED),
        "a typo in the failure colour: {refused:?}"
    );
    assert!(
        refused.contains(YELLOW),
        "not the notice register: {refused:?}"
    );
    assert!(
        failure.contains(RED),
        "the chain mismatch lost its red: {failure:?}"
    );
    // And the reason the register exists, in one assertion: the reader's own mistake is
    // not the same event as a session in trouble, and neither is housekeeping.
    assert_ne!(refused, failure);
    assert_ne!(refused, routine);
}

/// **The operator's own sentence, as the head draws it.**
///
/// The other half of `sudo_ask_live.rs`'s assertion, and it is here because this is where
/// the head is. That file measures the daemon — that `operator_run_unreadable` is
/// **published** on the session log for a run it may not look at — and cannot measure what
/// a screen does with it: `letibot-harnessd` has no head in it. So the one thing the
/// operator's report turns on is pinned on this side: the warning is not one of the codes
/// that is counted on the edge and never drawn, and it is not filtered as a duplicate of
/// something the turn already says.
///
/// The text is the real sentence, at its real length, because length is half of what could
/// go wrong: a note longer than the screen folds to its head, and a fold that lost the code
/// would leave the person with a paragraph and no name for it.
#[test]
fn the_sentence_for_a_run_the_daemon_may_not_look_at_is_drawn() {
    let sentence = "`sudo apt install mc` has been quiet for a beat and this daemon cannot \
                        tell whether it is waiting for a line: one of its processes belongs to \
                        another user, so `/proc` refuses for it. If it is waiting — `sudo` \
                        reaching `apt`'s `Continue? [Y/n]` is the case this was measured on — \
                        the way in is `!send <line>`, which needs no card. Until the command ends \
                        it holds this daemon's worker, so nothing else of yours runs either.";
    let mut a = App::new(plain_cfg(120));
    a.apply(ServerFrame::Event(env(
        1,
        SessionEvent::Warning {
            code: "operator_run_unreadable".into(),
            detail: sentence.into(),
            compaction: None,
        },
    )));
    let screen = a.screen(120, 20).join("\n");
    assert!(
        screen.contains("operator_run_unreadable"),
        "the sentence never reached the screen — which is the operator's own report, and \
             the whole of what this test is for:\n{screen}"
    );
    // **And it is a ROW, not a counter.** `ALARM_ONLY` moves a code out of the conversation
    // and onto the triangle; a fault drawn only as a number in `/status` is a fault nobody
    // reads, and this one is the pointer to `!send`.
    assert!(
        !letibot_sessionlog::warning::to_the_alarm("operator_run_unreadable"),
        "the code is edge-bound, so a head would never draw the way in"
    );
    // **And the way in survives the fold.** The sentence is a document and folds to its
    // head; what may not be folded away is the verb the person needs.
    assert!(
        screen.contains("!send") || a.notes_lines().iter().any(|l| l.contains("!send")),
        "neither the screen nor `/notes` kept the way in:\n{screen}"
    );
}

/// **A note that is a document folds to its head, and `/notes` still has all of it.**
///
/// The other half of R10: the operator's wall was *two* gate timeouts at about
/// thirteen lines each — *"how to remove this red wall?"*. The instrument is the one
/// every other long thing on this screen already uses (a card's diff rows, an
/// elision row naming where the rest is), and the fold must not be a cap on the
/// record: the whole sentence is one verb away.
#[test]
fn a_note_that_is_a_document_folds_to_its_head_and_the_verb_has_the_rest() {
    let mut a = app();
    let long = format!(
        "denied: the gate timed out before anybody answered, so the call did not run.\n{}",
        (1..12)
            .map(|i| format!("  line {i} of the rule it cites"))
            .collect::<Vec<_>>()
            .join("\n")
    );
    a.note(Note::Warned(Warned {
        code: "gate_timeout".into(),
        detail: long.clone(),
        ts: 7,
    }));
    let screen = a.screen(100, 40).join("\n");
    // The head of it, and a seam that names the verb.
    assert!(screen.contains("gate_timeout"), "{screen}");
    assert!(screen.contains("anybody answered"), "{screen}");
    assert!(screen.contains("· /notes"), "the seam is missing: {screen}");
    assert!(
        !screen.contains("line 11 of the rule it cites"),
        "the whole document is on the screen: {screen}"
    );
    // **Twelve lines is three plus nine**, so the seam counts what it took out.
    assert!(screen.contains("+9 lines"), "{screen}");
    // And the record is whole where the seam points.
    let listed = a.notes_lines().join("\n");
    assert!(listed.contains("line 11 of the rule it cites"), "{listed}");
    assert!(listed.contains("line 1 of the rule it cites"), "{listed}");
}

/// **R10's ruling on `ctrl-v`: one row, not the conversation.**
///
/// The chord flips the tool fold for the **whole** conversation while the pager's
/// own seam advertises it as `… +N lines · ctrl-v`, which reads per-row. The
/// operator was surprised *"that ctrl-t triggered the wall AT ALL"*, and the fix is
/// to keep the meaning a per-row seam can honestly name: the chord opens one row's
/// window, and the conversation-wide unfold keeps the verb it already had.
#[test]
fn ctrl_v_opens_one_rows_window_and_the_whole_folds_are_the_verb() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    let long: String = (0..40).map(|i| format!("line {i}\n")).collect();
    a_result_row(&mut a, 2, "i1", &long);

    // **The seam names the chord on the row the chord reaches**, and it is the only
    // long row here.
    let folded = a.screen(100, 40).join("\n");
    assert!(folded.contains("ctrl-v opens it"), "{folded:?}");

    // The chord opens that row's window and **does not unfold the other rows**: the
    // fold is the verb's, and one chord doing both is what made this a wall.
    a.key(Key::CtrlV);
    assert_eq!(a.payload_sel.as_deref(), Some("i1"));
    assert!(
        !a.tools.is_open(),
        "ctrl-t unfolded the whole conversation as well"
    );
    let open = a.screen(100, 40).join("\n");
    assert!(
        open.contains("pages down"),
        "the window did not open: {open:?}"
    );

    // Pressing it again closes the window and leaves everything else alone.
    a.key(Key::CtrlV);
    assert_eq!(a.payload_sel, None);
    assert!(!a.tools.is_open());

    // **And the conversation-wide unfold is `/t`**, which is where it already lived.
    assert_eq!(a.command("t"), None);
    assert!(a.tools.is_open(), "/t no longer unfolds tool output");
    assert_eq!(
        a.command("tools"),
        None,
        "`/tools` is the listing verb, not a second fold"
    );
}

/// **The keymap line is centred** — the operator's ask of 2026-10-04: *"please center the
/// keymap bottom line."*
///
/// The bar arrives already painted, so the centring is measured on the visible width and the
/// assertion is a BALANCE within one column — an odd remainder has to sit on one side, and
/// naming a side would be a rule nobody asked for. **An over-long bar centres to itself**
/// (pad 0) and keeps its head, which is the half naming the first keys: the same degradation
/// the left-aligned bar had, so a narrow screen loses the same end it always did.
#[test]
fn the_keymap_line_is_centred() {
    let mut a = app();
    for w in [40usize, 60, 80, 100, 120, 210] {
        let bar = a.hint_bar(w);
        let left = bar.chars().take_while(|c| *c == ' ').count();
        let right = w.saturating_sub(visible_width(&bar));
        assert!(
            left.abs_diff(right) <= 1,
            "w={w}: {left} left, {right} right — the bar is not centred: {bar:?}"
        );
    }
    // And the over-long case keeps its head rather than losing both ends to the middle.
    let narrow = a.hint_bar(20);
    assert_eq!(visible_width(&narrow), 20, "{narrow:?}");
    assert!(narrow.starts_with("ctrl-s"), "the head went: {narrow:?}");
}

/// **R40: the bar says what `ctrl-t` does, and names the verb that does the rest.**
///
/// The operator, reading a real screen: *"als why Ct stopped expanding tools??? at least in
/// letibt"*. Two defects, and only one of them was letibot's.
///
/// **This one was letibot's, and it is R29's rule failing on the bar instead of on a
/// note.** `ctrl-t` was narrowed deliberately (R10, above) — it opens one row's window and
/// the conversation-wide unfold is `/t` — and the bar still read `ctrl-t long output`,
/// which is the reading the ruling removed. So the key advertised at the bottom of the
/// screen did not do what the bar said, and `/t` was on the bar nowhere: the remedy the
/// operator needed was real, existed, and was not offered.
///
/// **The bar's own arithmetic is R22's and it is measured here rather than asserted.**
/// This bar is longer than 80 columns whatever it says — nine entries and room for about
/// five — so what is *visible* is a decision. Two of them are pinned (R22: `ctrl-s` first,
/// `ctrl-n` second, because a reflex worth advertising has to be inside the frame) and the
/// rest are ordered by what a reader cannot find out any other way. That is the test's last
/// assertion, and it is the reason `tab completes /commands` is the entry that gave way.
#[test]
fn the_bar_says_what_ctrl_v_does_and_names_the_verb_that_does_the_rest() {
    let mut a = app();
    let bar = a.screen(210, 24).pop().unwrap_or_default();

    // The words are true: one row, not the conversation.
    assert!(bar.contains("ctrl-v"), "the chord left the bar: {bar}");
    assert!(
        !bar.contains("long output"),
        "the bar still says the conversation-wide thing ctrl-t stopped doing: {bar}"
    );
    // And the verb that DOES fold the conversation is on it.
    assert!(
        bar.contains("/t"),
        "`/t` is the whole fold and the bar does not name it: {bar}"
    );
    // Adjacent, because they are the two a reader confuses: one result, all of them.
    assert!(
        bar.contains("ctrl-v newest result · /t all tool rows"),
        "the pair is not stated as a pair: {bar}"
    );

    // **Both halves of the claim are driven, on one screen.** A bar that is right about a
    // chord that does something else is the defect respelled.
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    let long: String = (0..40).map(|i| format!("line {i}\n")).collect();
    a_result_row(&mut a, 2, "i1", &long);
    a.key(Key::CtrlV);
    assert_eq!(
        a.payload_sel.as_deref(),
        Some("i1"),
        "the bar says `newest result` and ctrl-t opened no window"
    );
    assert!(
        !a.tools.is_open(),
        "the bar says one result and ctrl-t folded them all"
    );
    a.key(Key::CtrlV);
    assert_eq!(a.command("t"), None);
    assert!(
        a.tools.is_open(),
        "the bar says `/t all tool rows` and /t did not unfold them"
    );
    assert!(
        a.payload_sel.is_none(),
        "`/t` is the conversation-wide fold and it opened a row's window"
    );

    // **Tab gave up its space, and gets to keep its fact.** The bar no longer names it —
    // it is the entry that answers before it is named — and `/help` still does, on the row
    // a reader is looking at when they go there. Dropping it from both would have been a
    // different change.
    assert!(
        !bar.contains("tab completes"),
        "the bar still spends 23 columns on the one entry that needs no advertisement: {bar}"
    );
    assert!(
        !bar.contains("tab"),
        "tab is still on the bar under another spelling: {bar}"
    );
    let help = help_lines(&a.cfg, 140).join("\n");
    assert!(
        help.contains("tab"),
        "tab left the bar AND the help screen, which is not the trade: {help}"
    );
    assert!(
        bar.contains("/help"),
        "the index has to stay on the bar — R29's remedy rule needs it there: {bar}"
    );

    // **The measurement, recorded.** R22's arithmetic is that a chord past the frame's
    // width is a chord nobody has, so the numbers are pinned rather than remembered.
    // (`trim` is the frame's gutter, which is not the bar's own width.)
    //
    // **Re-measured 2026-10-03 for R56's rework**, which added `ctrl-p hold` and moved the
    // todos pane to `ctrl-t` and the payload window to `ctrl-v`: 146 → 160, the new entry's
    // own width. What is visible at 80 and at 120 is unchanged (the two pinned entries at 80,
    // the `ctrl-v newest result · /t all` pair whole at 120), which the assertions below keep.
    assert_eq!(
        bar.trim().chars().count(),
        160,
        "the bar's width changed; re-measure what is visible at 80: {bar}"
    );
    let at80 = a.screen(80, 24).pop().unwrap_or_default();
    assert!(
        at80.contains("ctrl-s sessions") && at80.contains("ctrl-n notes"),
        "R22's two pinned entries left the first 80 columns: {at80}"
    );
    assert!(
        !at80.contains("ctrl-v"),
        "the pair now fits at 80 — better than the measurement, so update it: {at80}"
    );
    let at120 = a.screen(120, 24).pop().unwrap_or_default();
    assert!(
        at120.contains("ctrl-v newest result · /t all"),
        "the pair is not whole at 120, which is where it was measured to be: {at120}"
    );
}

/// **A sub-session is listed under the conversation that spawned it, and it switches like any
/// other** — the operator's correction of 2026-10-03, and the half of it that is letibot's.
///
/// *"yes subagents are not even scratch session they are session, just sub sessions"*, and
/// *"why readonly? subagent session is more like you driving others via tmux"*. Two sites used to
/// drop every row with a parent — `Hello` and `Sessions` — so a session a head can post to, and
/// get an answer from, was thrown away on the way in. What that filter was protecting against was
/// noise, and the answer to noise is nesting rather than silence.
///
/// Four properties, and the third is the one a two-enumerations regression would break:
///
/// * **Kept**: both rows are in `sessions` after a `Hello`.
/// * **Collapsed by default**: one row drawn, so this screen looks exactly as it did before
///   sub-sessions were listed at all.
/// * **The listing and the keys agree**: the child is indented under its parent, and the cursor
///   that reaches it by `↓` is the row `Enter` switches to — both read from [`App::session_rows`].
/// * **`←` folds it back**, on whichever of the two rows the cursor is on.
#[test]
fn a_sub_session_is_listed_under_its_parent_and_switches_like_any_other() {
    let mut child = brief("s-child", "the child", false);
    child.parent_session_id = Some("s-root".into());
    let mut a = app();
    a.apply(hello(
        "s-root",
        vec![brief("s-root", "root", false), child],
        Hub::new("s-root").snapshot(),
    ));
    // **Kept.** The daemon told this head about two sessions and it holds two.
    assert_eq!(
        a.sessions.len(),
        2,
        "a sub-session was discarded on the way in"
    );
    a.picker = true;

    // **Collapsed by default**, which is the whole reason the default is not noisy.
    assert_eq!(a.session_rows().len(), 1, "the child is shown unexpanded");
    let closed = a.screen(100, 30).join("\n");
    assert!(
        !closed.contains("the child"),
        "a collapsed child was drawn anyway:\n{closed}"
    );

    // **The fold, on the row the cursor is on** — it starts on the session this head is in.
    assert_eq!(a.key(Key::Right), None, "expanding is not a daemon action");
    assert_eq!(a.session_rows().len(), 2, "expanding shows the child");
    let open = a.screen(100, 30).join("\n");
    assert!(
        open.contains("the child"),
        "the child is not drawn:\n{open}"
    );

    // **The cursor reaches it, and the row it reaches is the row Enter takes.** One
    // enumeration, so the indentation the eye sees and the row the key acts on cannot drift.
    assert_eq!(a.key(Key::Down), None);
    let picked = a.screen(100, 30).join("\n");
    let mark_at = |needle: &str| {
        picked
            .lines()
            .find(|l| l.contains(needle))
            .and_then(|l| l.find('\u{25b8}'))
    };
    assert!(
        mark_at("the child") > mark_at("root"),
        "the child is not indented under its parent:\n{picked}"
    );
    assert_eq!(
        a.key(Key::Enter),
        Some(Action::Switch("s-child".into())),
        "Enter on a sub-session must be an ordinary attach"
    );

    // **`←` folds it back** — and a child row closes its PARENT, so the key means *back up the
    // tree* on the row you just arrived at rather than nothing at all.
    a.key(Key::Left);
    assert_eq!(a.session_rows().len(), 1, "left did not fold the tree");
}

/// **The sessions pane's tree, as a picture** — an instrument, not an assertion.
///
/// MEASURED on this box 2026-10-05, because the numbers are not what the tests' fixtures
/// imply: **174 of the store's 280 sessions carry a `parent_session_id`**, this session has
/// 95 children of its own, the header reads `1/106`, and every one of those 174 is **one
/// level down** — there is no depth-2 row in the store at all. So the tree is the pane's
/// majority case rather than a corner, and the two things the fixtures do not exercise are
/// the ones an instrument is for: the **grandchild** (reached by a child's own `task`, which
/// no fixture on this box has produced) and the **three-digit row number** (106 roots, where
/// `{:>2}` gives rows 100+ one column more than rows 1–9).
///
/// Print it, do not assert it:
///
/// ```text
/// cargo test -p letibot-tui --lib -- --ignored --nocapture show_the_sessions_pane_tree
/// ```
#[test]
#[ignore]
fn show_the_sessions_pane_tree() {
    let mut grand = brief("s-grand", "the grandchild", false);
    grand.parent_session_id = Some("s-child-a".into());
    let mut child_a = brief("s-child-a", "the first child", true);
    child_a.parent_session_id = Some("s-root".into());
    let mut child_b = brief("s-child-b", "the second child", false);
    child_b.parent_session_id = Some("s-root".into());
    let mut far = brief("s-other-sub", "somebody else's child", false);
    far.parent_session_id = Some("s-other".into());
    // A hundred roots, so the numbering reaches three digits — the state this box is in.
    //
    // **`grand` IS IN THIS LIST, and the first draft of this instrument forgot it** — the
    // fixture built the grandchild, set its parent, and then never pushed it, so the depth-2
    // frame drew the whole daemon and the family frame drew 104 roots: two frames that looked
    // like pane defects and were the fixture lying. Which is the argument for an instrument
    // that prints rather than asserts — an assertion would have been written to match.
    let mut family = vec![
        brief("s-root", "this conversation", false),
        child_a,
        grand,
        child_b,
        brief("s-other", "another conversation", false),
        far,
    ];
    for i in 0..100 {
        family.push(brief(&format!("s-filler-{i:03}"), "a conversation", false));
    }

    let mut a = app();
    a.apply(hello(
        "s-root",
        family.clone(),
        Hub::new("s-root").snapshot(),
    ));
    a.picker = true;
    // **A ruler, because the question here is COLUMNS.** *Does the pane render the tree*
    // is a question about which column a row's name starts in, and an eyeball on a frame
    // answers it wrongly at one column per level — which is what the first look did.
    let ruler: String = (0..96)
        .map(|i| char::from_digit((i % 10) as u32, 10).unwrap())
        .collect();
    let show = |label: &str, a: &App| {
        eprintln!("\n──── {label} ────");
        eprintln!("|{ruler}");
        for l in a.picker_lines(96) {
            eprintln!("|{l}");
        }
    };

    show(
        "collapsed — 104 roots, and this one has two children folded into it",
        &a,
    );
    a.expanded.push("s-child-a".into());
    show("s-child-a expanded — the grandchild at depth 2", &a);
    a.expanded.push("s-root".into());
    show(
        "the root expanded too — both children, then the grandchild",
        &a,
    );
    a.expanded.clear();
    a.session_id = "s-grand".into();
    show(
        "standing IN the grandchild — the family view, not the daemon",
        &a,
    );
}

/// **R56: while the view is held, the head writes NOTHING** — so a mouse selection survives
/// a streaming turn, which is the whole of why the hold exists.
///
/// The contract has three clauses and this drives all three: the frame is composed once
/// (with the marker on it, the single write the freeze owes), every later call returns it
/// **byte for byte** while a turn streams and rows land, and the release says what arrived.
/// The zero-bytes claim is asserted the only way a frame test can: `screen` is what the
/// terminal diffs against the glass, so a frame that does not change is a frame that writes
/// no bytes at all.
#[test]
fn a_held_view_draws_the_same_frame_while_the_turn_streams() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    a.apply(ServerFrame::Event(env(
        2,
        testing::delta("t1", "the answer is"),
    )));
    assert!(!a.hold, "the premise: the view is following");

    // **The freeze, and the one write it owes** — the marker, on the hint bar's row.
    assert_eq!(a.key(Key::CtrlP), None, "the hold is not a daemon action");
    assert!(a.hold);
    let frozen = a.screen(100, 24);
    assert!(
        frozen.iter().any(|l| l.contains(HOLD_MARKER)),
        "the held frame does not say it is held:\n{}",
        frozen.join("\n")
    );

    // **And then nothing is written, however much arrives.** A turn streams, a round lands,
    // two rows are appended — the frame must not move by a byte.
    for i in 0..20u64 {
        a.apply(ServerFrame::Event(env(
            3 + i,
            testing::delta("t1", " more"),
        )));
    }
    a.apply(ServerFrame::Event(env(
        23,
        testing::appended("s.0", "assistant"),
    )));
    a.apply(ServerFrame::Event(env(
        24,
        testing::content("s.0", "an answer"),
    )));
    a.apply(ServerFrame::Event(env(
        25,
        testing::appended("u.1", "user"),
    )));
    assert_eq!(
        a.screen(100, 24),
        frozen,
        "the held frame moved while the turn streamed"
    );

    // **`redraw` cannot force a repaint behind the hold's back**, which is the other way
    // bytes could reach the glass: a full repaint writes every row.
    a.mark_redraw();
    assert!(
        !a.take_redraw(),
        "a held view let the glass be thrown away, so a full repaint is one frame away"
    );
    assert_eq!(a.screen(100, 24), frozen);

    // **The release follows again, and says how much arrived — once**, which is what makes
    // the count honest: a live count while held would be an animation.
    assert_eq!(a.key(Key::CtrlP), None);
    assert!(!a.hold, "the second press releases");
    let released = a.screen(100, 24);
    assert_ne!(released, frozen, "the view did not come back");
    let said = released.join("\n");
    assert!(
        said.contains("the view follows again — 2 rows arrived while it was held"),
        "the release did not count what arrived:\n{said}"
    );
    assert!(
        !said.contains(HOLD_MARKER),
        "the marker outlived the hold:\n{said}"
    );
}

#[test]
fn a_recorded_session_renders_without_a_daemon() {
    // W8 is a leaf: give it a recorded log and it is built and demoed before a
    // turn engine exists.
    let mut a = app();
    for e in testing::recorded_session() {
        a.apply(ServerFrame::Event(letibot_sessionlog::event::Envelope {
            session_id: "s".into(),
            seq: a.seq + 1,
            ts: 0,
            event: e,
        }));
    }
    for (id, item) in testing::recorded_items() {
        a.record_item(&id, item);
    }
    let screen = a.screen(80, 30);
    assert_eq!(screen.len(), 30);
    assert!(screen.iter().all(|l| line_width(l) <= 80));
    let joined = screen.join("\n");
    assert!(joined.contains("cached"), "the status of the turn is shown");
}

#[test]
fn a_head_that_filters_everything_still_says_so() {
    let mut a = app();
    a.visibility = Visibility::of(Profile::TERSE);
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    let before = a.filtered;
    for i in 0..10 {
        a.apply(ServerFrame::Event(env(
            2 + i,
            testing::reasoning("t1", "thinking "),
        )));
    }
    assert_eq!(a.filtered - before, 10);
    // Where it says so is `/status`, not the bottom border. §13.2b's rule is
    // about the moment the disclosure is READ — the count has to exist, be
    // exact, and be reachable without restarting anything. It was never an
    // argument for a resident row of zeros next to the prompt.
    a.command("status");
    let screen = a.screen(120, 40).join("\n");
    assert!(screen.contains("filtered"), "{screen}");
    assert!(screen.contains("10 (terse)"), "{screen}");
    // And a head that has lost nothing says nothing on the border.
    assert_eq!(a.status_line(200), "", "a clean head has a clean border");
}

/// The border is not silent about a counter that has **moved**.
///
/// The half of §13.2b that does belong on a resident row: a head that dropped
/// events is a head whose transcript has a hole in it, and that must not wait
/// for somebody to type a command.
#[test]
fn a_counter_that_has_moved_reaches_the_border_and_a_zero_one_does_not() {
    let hub = Hub::new("s");
    hub.publish(testing::turn_started("t1"));
    let mut a = app();
    assert_eq!(a.status_line(200), "");
    a.apply(ServerFrame::Resync {
        reason: "queue overflow".into(),
        dropped: 12,
        snapshot: Box::new(hub.snapshot()),
        scrubbed: Default::default(),
    });
    // The border says it with a triangle, pinned right — a fact that exists
    // only while it does, and never a resident sentence of bright yellow.
    let screen = a.screen(120, 24).join("\n");
    assert!(screen.contains('⚠'), "{screen}");
    assert!(
        !screen.contains("dropped 12"),
        "the numbers are /status's, not the border's: {screen}"
    );
    // The unboxed composer — no border to pin a triangle to — names them on a
    // line of its own, read HERE, before the screen below acknowledges the alarm
    // (R51 item 17; the assertion used to sit after the `/status` read).
    let border = a.status_line(200);
    assert!(border.contains("dropped 12"), "{border}");
    assert!(border.contains("resync 1"), "{border}");
    assert!(
        border.contains("/status"),
        "and says where the rest is: {border}"
    );
    // …where they keep their names and their counts.
    a.command("status");
    // **A taller window, because the panel is taller now.** MEASURED while landing this
    // (2026-10-05): the `filtered` row's gloss names the profile the head is on, so several
    // rows gained a line of wrap and the counters below `dropped` sit past a 40-row screen —
    // the `resync` row is still on the panel (it is the tenth row of `status_lines`), it was
    // simply under the fold. The subject of this assertion is the row, so it is given room
    // to be drawn rather than asked for off-screen.
    let stats = a.screen(120, 60).join("\n");
    let dropped_row = stats
        .lines()
        .find(|l| l.contains("dropped"))
        .expect("the dropped row is on the /status screen");
    assert!(dropped_row.contains("12"), "{dropped_row}");
    // **The panel's own row, not the notice line** — MEASURED while landing this
    // (2026-10-05). At HEAD the resync notice is live but NOT on this screen: the composer's
    // height ladder deletes the most expendable row first, and at 24 rows the notice is the
    // one that goes. This rewrite's row budget is one row larger, so the notice now fits on
    // the screen (`  · resync: queue overflow`) and `find(|l| l.contains("resync"))` — which
    // this test used to do — hit THAT line instead of the counter row it means to assert.
    // The assertion's subject is the counter, so it looks for the row's own shape: the panel
    // indents its rows, and the number follows the label.
    let resync_row = stats
        .lines()
        .find(|l| {
            // Painted rows carry SGR codes before the label, so the shape is read off the
            // plain text — the same stripper the pane uses on a name.
            let plain = without_control_lines(l);
            plain.trim_start().starts_with("resync") && plain.chars().any(|c| c.is_ascii_digit())
        })
        .expect("the resync row is on the /status screen");
    assert!(resync_row.contains('1'), "{resync_row}");

    // **And READING it acknowledged the alarm** — R51 item 17, in the test that already had
    // the whole story of one counter arriving. The numbers stay on the screen (asserted
    // above, after the read), the mark goes, and the screen says what it did.
    assert!(
        stats.contains("acknowledged"),
        "the screen did not say what opening it just did: {stats}"
    );
    a.command("status"); // close it again
    let screen = a.screen(120, 24).join("\n");
    assert!(
        !screen.contains('⚠'),
        "the mark outlived the reading: {screen}"
    );
    assert_eq!(a.status_line(200), "", "nor on the unboxed path");

    // **A counter that moves AFTER the reading is a new fact, and the mark comes back.**
    // This is the half that makes acknowledging safe rather than a way to switch the alarm
    // off and forget it.
    a.apply(ServerFrame::Resync {
        reason: "queue overflow again".into(),
        dropped: 3,
        snapshot: Box::new(hub.snapshot()),
        scrubbed: Default::default(),
    });
    let screen = a.screen(120, 24).join("\n");
    assert!(
        screen.contains('⚠'),
        "a NEW incident did not raise the alarm again: {screen}"
    );
}

/// **The acknowledgement is per counter and only up to what was read** — R51 item 17's
/// *must not differ*, stated as arithmetic rather than through a screen.
#[test]
fn acknowledging_a_counter_silences_it_only_up_to_the_value_that_was_seen() {
    let none = Counters::default();
    // Nothing has moved: no alarm, and reading a clean screen acknowledges nothing.
    assert!(!none.exceeds(none));
    // One incident, and the alarm.
    let one = Counters {
        resyncs: 1,
        ..Counters::default()
    };
    assert!(one.exceeds(none), "the first resync is news");
    // Read it: acknowledged, and STILL not news — the second reading of the same number is
    // what a reader does not need a second time.
    assert!(!one.exceeds(one));
    // A resync after the one that was read is a different fact.
    let two = Counters {
        resyncs: 2,
        ..Counters::default()
    };
    assert!(two.exceeds(one), "the second resync is news again");
    // **Per counter, not as a total.** A counter whose value went DOWN is not news — an alarm
    // that fired on a decrease would be a mark nobody could ever clear — and a DIFFERENT
    // counter reaching a value this one already has is still its own news.
    assert!(!none.exceeds(one), "a decrease is not an incident");
    assert!(
        Counters {
            gaps: 1,
            ..Counters::default()
        }
        .exceeds(one),
        "`1 gap` is not silenced by having read `1 resync`"
    );
}

/// **A frame this head cannot read is said, counted, and not fatal.**
///
/// Requirement R3, and the two failures it sits between: a head that exits on an
/// unparseable frame takes the session down and says nothing, and a head that steps
/// over one in silence is the same failure more quietly — *"this daemon is sending
/// me something I do not understand"* becomes indistinguishable from quiet. So:
/// the sentence is in the transcript, the counter moves, `/status` has the bucket
/// at zero **and** after, and nothing about it touches the read mark.
#[test]
fn an_unreadable_frame_is_said_counted_and_survived() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // **The bucket exists before anything lands in it.** §13.2b: an absent field
    // and a zero field must not look the same, and a head that does not count
    // these at all is what every head was until now.
    a.command("status");
    // **Taller than 40 rows on purpose.** `/status` is a scrolling pane, and R10
    // added a row to it (the notes the reader has retired) — so a test that asserts
    // a row is *on the screen* has to give the pane room for all of them rather than
    // depend on where the list happens to end.
    let zero = a.screen(120, 120).join("\n");
    let row = zero
        .lines()
        .find(|l| l.contains("unreadable"))
        .unwrap_or_else(|| panic!("/status has no bucket for this: {zero}"));
    assert!(row.contains('0'), "{row}");
    a.key(Key::Esc);
    assert_eq!(a.status_line(200), "", "a clean head has a clean border");

    // A daemon one version ahead sends a frame from the future.
    let before = (a.seq, a.rendered, a.filtered);
    a.unreadable(Unreadable {
        line: r#"{"frame":"peeked_v2","rows":[]}"#.into(),
        detail: "unknown variant `peeked_v2`, expected one of `hello`, `bye`".into(),
    });
    assert_eq!(a.unreadable, 1);
    // **Nothing was parsed, so nothing is claimed.** The read mark is untouched
    // and neither ack counter moved: `filtered` is "events I chose not to show",
    // and inventing a seq here would rewind the mark over frames already read.
    assert_eq!((a.seq, a.rendered, a.filtered), before);

    // The sentence is in the conversation: what it was, that this is almost always
    // a newer daemon, and that this head is still attached.
    let screen = a.screen(120, 60).join("\n");
    assert!(screen.contains("peeked_v2"), "{screen}");
    assert!(screen.contains("cannot read"), "{screen}");
    assert!(screen.contains("newer"), "{screen}");
    assert!(
        screen.contains(&format!(
            "protocol {}",
            letibot_sessionlog::protocol::PROTOCOL_VERSION
        )),
        "{screen}"
    );

    // And the head is still running: the next frame applies as though nothing had
    // happened, which is the whole point of surviving one.
    a.apply(ServerFrame::Event(env(9, testing::turn_started("t1"))));
    assert!(a.turn_busy(), "the head kept working");

    // A second one counts twice, and the border names it now that it has moved.
    a.unreadable(Unreadable {
        line: r#"{"frame":"another"}"#.into(),
        detail: "unknown variant `another`".into(),
    });
    assert_eq!(a.unreadable, 2);
    let border = a.status_line(200);
    assert!(border.contains("unreadable 2"), "{border}");
    assert!(border.contains("/status"), "{border}");
    a.command("status");
    // **Taller than a screen, for the reason stated above.** `/status` is a scrolling pane
    // and it has gained a row since this test was written (R10's retired notes, then the
    // unfilled-rows row); a test asserting a row is on the screen has to give the pane room
    // for all of them rather than depend on where the list happens to end.
    let stats = a.screen(120, 140).join("\n");
    let unreadable_rows: Vec<&str> = stats.lines().filter(|l| l.contains("unreadable")).collect();
    assert!(
        unreadable_rows.iter().any(|l| l.contains('2')),
        "{unreadable_rows:?}"
    );
}

/// **The version the daemon is TOLD to be is checked at the handshake, and a skew is
/// said rather than fatal.**
///
/// leticl does this on `Hello` and this head did not, which left the skew announcing
/// itself on the first frame that failed to parse — the expensive moment, one frame
/// late, and phrased as a decoder's complaint. The `Hello` is the cheap moment: nothing
/// has been read yet and the direction is known.
///
/// Three things are asserted together, because they are one behaviour: a matching
/// version says **nothing at all** (a line here would be furniture), a differing one
/// says which way round it is in the transcript, and **the head stays attached** — a
/// skew is usually survivable, which is R3's whole argument, so exiting here would be
/// the failure framing the fix.
#[test]
fn a_protocol_skew_is_said_at_the_handshake_and_the_head_stays_attached() {
    let hub = Hub::new("s");

    // The normal case: both halves the same build, and nothing is said. §13.2b cuts
    // both ways — a field that is always zero is no more readable than one that is
    // absent, and a head that announces "versions match" on every attach teaches the
    // operator that this line can be skipped.
    let mut a = app();
    a.apply(hello_at(
        "s",
        vec![brief("s", "one", false)],
        hub.snapshot(),
        letibot_sessionlog::protocol::PROTOCOL_VERSION,
    ));
    assert_eq!(
        a.daemon_protocol,
        Some(letibot_sessionlog::protocol::PROTOCOL_VERSION)
    );
    assert!(
        a.notes.is_empty(),
        "nothing to say, so nothing said: {:?}",
        a.notes
    );
    a.command("status");
    // **Taller than it was, again.** `/status` is a scrolling pane, and the row this test
    // reads is near its end: R17 added three rows (gaps, behind, orphan) and this change
    // added a fourth (`first byte`, the counter `model_slow_first_byte` now lands in) plus
    // its gloss. A frame that used to reach the bottom of the list does not, and the
    // failure is a missing row rather than a wrong one.
    let status = a.screen(120, 96).join("\n");
    let row = status
        .lines()
        .find(|l| l.contains("protocol"))
        .unwrap_or_else(|| panic!("/status does not name the version: {status}"));
    assert!(row.contains("same build"), "{row}");
    a.key(Key::Esc);

    // A NEWER daemon: a reading problem, and this head can survive it.
    let newer = letibot_sessionlog::protocol::PROTOCOL_VERSION + 3;
    let mut a = app();
    a.apply(hello_at(
        "s",
        vec![brief("s", "one", false)],
        hub.snapshot(),
        newer,
    ));
    let said = a
        .notes
        .last()
        .map(|(_, n)| note_lines_unfolded(&a.cfg, n).join(" "))
        .unwrap_or_default();
    assert!(said.contains(&newer.to_string()), "{said}");
    assert!(said.contains("NEWER"), "{said}");
    assert!(said.contains("Restarting the daemon"), "{said}");
    // It says what it will do about them, which is the part the operator needs to
    // know before the first one arrives.
    assert!(said.contains("skipped"), "{said}");
    // And the head is still here, still drawing, still able to take a frame.
    assert!(!a.should_quit());
    assert_eq!(a.session_id, "s");
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    assert!(a.turn_busy(), "the head kept working");

    // An OLDER daemon: a writing problem, and quiet until it is fatal — so this is the
    // sentence that matters most.
    let older = letibot_sessionlog::protocol::PROTOCOL_VERSION - 1;
    let mut a = app();
    a.apply(hello_at(
        "s",
        vec![brief("s", "one", false)],
        hub.snapshot(),
        older,
    ));
    let said = a
        .notes
        .last()
        .map(|(_, n)| note_lines_unfolded(&a.cfg, n).join(" "))
        .unwrap_or_default();
    assert!(said.contains("OLDER"), "{said}");
    assert!(
        said.contains("closing the socket"),
        "it must say the session can end on the next command, not merely that the \
             daemon is old: {said}"
    );
    assert!(!a.should_quit());
    // `/status` names the direction too, and has it after the note has scrolled away.
    a.command("status");
    // **Taller than it was**: `/status` gained three rows in R17 (gaps, behind,
    // orphan), and a fixed-height frame that used to reach the bottom of the list
    // no longer does.
    // **And the same height for the same reason.**
    let status = a.screen(120, 96).join("\n");
    let row = status
        .lines()
        .find(|l| l.contains("protocol"))
        .unwrap_or_else(|| panic!("{status}"));
    assert!(row.contains("OLDER"), "{row}");
    assert!(row.contains(&older.to_string()), "{row}");
}

/// **A `Switch` re-reads the same `Hello`, so the sentence is filed once.** The
/// daemon answers a switch with a second `Hello` on the same connection — that is the
/// whole of this head's switch path — and a skew announced twice would read as two
/// skews. `note` dedupes on `(code, detail, ts)`, which is what makes that true, and
/// this pins it rather than trusting it.
#[test]
fn a_version_skew_is_said_once_however_many_hellos_arrive() {
    let hub = Hub::new("s");
    let mut a = app();
    let newer = letibot_sessionlog::protocol::PROTOCOL_VERSION + 1;
    for _ in 0..3 {
        a.apply(hello_at(
            "s",
            vec![brief("s", "one", false)],
            hub.snapshot(),
            newer,
        ));
    }
    assert_eq!(a.notes.len(), 1, "said three times: {:?}", a.notes);
}

/// **A head that outlives its daemon notices, says so, and re-asks.**
///
/// The operator's box: three `letibot-tui` processes alive (ages 15d, 1d18h, 21h) while the
/// daemon was replaced this afternoon. A head outlives the daemon that gave it its facts, and
/// the registry is in memory — so a daemon that comes back is not the one whose answers are
/// still on the screen. The head went on drawing them without ever saying the party it was
/// talking to had changed.
///
/// **The identity is `SO_PEERCRED` and the protocol**, which is what the head has: the pid is
/// the kernel's answer for *this socket*, re-read by the caller on every connection, and the
/// version rides the `Hello`. Both halves are asserted, because either alone can be wrong —
/// a pid is reused, and a rebuild that keeps its number is still a different daemon.
#[test]
fn a_replaced_daemon_is_noticed_said_and_re_asked() {
    let hub = Hub::new("s");
    // The daemon this head attached to.
    let mut a = app();
    a.set_daemon_pid(Some(4242));
    a.apply(hello("s", a_family(), hub.snapshot()));
    assert!(
        !a.notes
            .iter()
            .any(|(_, n)| matches!(n, Note::Warned(w) if w.code == "daemon_replaced")),
        "the first attach has nothing to compare against: {:?}",
        a.notes
    );
    a.take_actions();

    // **A switch on the same socket, by the same process, is not a replacement.** This is the
    // half that keeps the note from firing on every keystroke-shaped `Hello`.
    a.apply(hello("s", a_family(), hub.snapshot()));
    assert!(
        !a.notes
            .iter()
            .any(|(_, n)| matches!(n, Note::Warned(w) if w.code == "daemon_replaced")),
        "the same daemon answered the same session twice: {:?}",
        a.notes
    );

    // **The socket died and the driver came back to a different process.** `head.rs` re-reads
    // `SO_PEERCRED` on the new connection before the `Hello` is folded — that is the caller's
    // order and this test's, because the arm reads `self.daemon_pid`.
    a.link_down("the daemon closed the connection");
    a.reconnect_sent();
    a.set_daemon_pid(Some(5151));
    a.apply(hello("s", a_family(), hub.snapshot()));

    let said = a
        .notes
        .iter()
        .find_map(|(_, n)| match n {
            Note::Warned(w) if w.code == "daemon_replaced" => Some(w.detail.clone()),
            _ => None,
        })
        .unwrap_or_else(|| panic!("a different daemon went unremarked: {:?}", a.notes));
    assert!(
        said.contains("pid 4242"),
        "it does not name the one that went: {said}"
    );
    assert!(
        said.contains("pid 5151"),
        "nor the one that arrived: {said}"
    );
    assert!(
        said.contains("in memory"),
        "it does not say WHY the old answers are no longer good: {said}"
    );

    // **And the refetch ran**, which is the other half of the requirement: the head does not
    // keep drawing the old picture, it asks again. The same three reads as any seating.
    let asked = a.take_actions();
    for want in [Action::ListSessions, Action::ListJobs, Action::Settings] {
        assert!(
            asked.contains(&want),
            "a head under a new daemon did not re-ask for {want:?}: {asked:?}"
        );
    }

    // **A rebuild that moved the wire is a replacement too**, even at the same pid — which is
    // the reason the identity is a pair rather than the number alone.
    let mut b = app();
    b.set_daemon_pid(Some(4242));
    b.apply(hello_at(
        "s",
        a_family(),
        hub.snapshot(),
        letibot_sessionlog::protocol::PROTOCOL_VERSION,
    ));
    b.apply(hello_at(
        "s",
        a_family(),
        hub.snapshot(),
        letibot_sessionlog::protocol::PROTOCOL_VERSION + 1,
    ));
    assert!(
        b.notes
            .iter()
            .any(|(_, n)| matches!(n, Note::Warned(w) if w.code == "daemon_replaced")),
        "the same pid speaking a different protocol is still a different daemon: {:?}",
        b.notes
    );
}

/// **A pid the kernel would not name is said as such, not as a number.** R30's rule on the
/// farewell, kept on the other sentence that names a pid: a head that printed a zero would
/// send the operator to `ps` for a process that is not there.
#[test]
fn a_replacement_between_two_unnamed_peers_says_so_rather_than_inventing_a_pid() {
    let hub = Hub::new("s");
    let mut a = app();
    // No `set_daemon_pid` at all: the kernel declined to name the peer.
    a.apply(hello_at(
        "s",
        a_family(),
        hub.snapshot(),
        letibot_sessionlog::protocol::PROTOCOL_VERSION,
    ));
    a.apply(hello_at(
        "s",
        a_family(),
        hub.snapshot(),
        letibot_sessionlog::protocol::PROTOCOL_VERSION - 1,
    ));
    let said = a
        .notes
        .iter()
        .find_map(|(_, n)| match n {
            Note::Warned(w) if w.code == "daemon_replaced" => Some(w.detail.clone()),
            _ => None,
        })
        .expect("the protocol moved, so the daemon did");
    assert!(
        said.contains("the kernel did not name"),
        "an unnamed peer was rendered as a pid: {said}"
    );
    assert!(!said.contains("pid 0"), "a zero is not a pid: {said}");
}

/// **A head whose daemon goes away says so, keeps its screen, and does not exit.**
///
/// The defect this is against: `client.ack(...)?` propagated out of the driver's
/// loop, through `main`, and the process was gone — the operator's view of a
/// conversation that was still on disk, taken with a socket that had merely been
/// closed. The half a test can hold on this side is the head's: the *state* is on
/// the head, the conversation is not cleared, the line says what happened, and a
/// prompt typed at it is refused rather than shown as sent.
#[test]
fn a_head_with_no_daemon_says_so_keeps_its_screen_and_holds_the_line() {
    let hub = Hub::new("s");
    hub.publish(testing::turn_started("t1"));
    hub.publish(testing::delta("t1", "the answer I already have"));
    let mut a = app();
    a.clock(1_000);
    a.apply(hello("s", vec![brief("s", "one", false)], hub.snapshot()));
    let before = a.screen(100, 24).join("\n");
    assert!(before.contains("the answer I already have"), "{before}");

    // The socket goes: the reader notices, and says what it can.
    a.link_down("the daemon closed the connection");
    assert!(a.detached());
    assert!(
        !a.should_quit(),
        "a dropped socket is not a reason to leave"
    );

    // **The screen it had is still the screen it has.** The transcript is not
    // cleared, the turn is not forgotten, and nothing is redrawn as if the session
    // had ended — plus one line saying what is wrong, above the composer where the
    // eye crosses on the way to typing.
    let after = a.screen(100, 24).join("\n");
    assert!(
        after.contains("the answer I already have"),
        "the conversation was taken away: {after}"
    );
    assert!(
        after.contains("daemon connection is down"),
        "nothing said the link was down: {after}"
    );
    assert!(after.contains("reconnecting"), "{after}");
    // And the keys still work: this is a head, not a corpse.
    assert!(!after.contains("esc closes this"), "{after}");

    // **A line typed here must not look sent.** The trap is the echo: `submit`
    // pushes it into `pending_prompts`, the screen draws `queued · <their words>`,
    // and there is no queue anywhere — so when the daemon comes back the sentence is
    // gone and it was on the screen as held the whole time.
    typed(&mut a, "did that go anywhere?");
    assert_eq!(a.key(Key::Enter), None, "nothing may leave a dead link");
    assert!(
        a.pending_prompts.is_empty(),
        "shown as queued with no queue behind it: {:?}",
        a.pending_prompts
    );
    let said = a.notice.clone().unwrap_or_default();
    assert!(said.contains("no daemon connection"), "{said}");
    // The words are still theirs, in the field they typed them into.
    assert_eq!(a.input(), "did that go anywhere?");

    // **The daemon comes back, and the recovery is the protocol's own.** The `Hello`
    // is what says the link is up — it is the frame that seats the connection — and
    // it says so into the conversation, with the seq it asked from, because the gap
    // is about to be filled with events and unexplained events are noise.
    a.clock(1_000 + 4_400);
    a.apply(hello("s", vec![brief("s", "one", false)], hub.snapshot()));
    assert!(!a.detached());
    let back = a.screen(100, 24).join("\n");
    assert!(!back.contains("daemon connection is down"), "{back}");
    assert!(back.contains("daemon is back after 4.4s"), "{back}");
    assert!(back.contains("Resuming from seq"), "{back}");
    // The ordinary reconnect succeeds on its first try, so there is no attempt count
    // to show — and the sentence must not show an empty one.
    assert!(
        back.contains("the daemon is back after 4.4s."),
        "no empty brackets: {back}"
    );
}

/// **R6: a named fill's line is the daemon's count, not a count of unfilled rows.**
///
/// The whole of the ruling: an indicator must be the fact, not a rendering of the
/// fact. Counting the rows still lacking a body would (a) name the wrong operation —
/// an ordinary reply is not an import (see `MIN_FILLING`) — and (b) draw *"never
/// filled in"* three seconds into a healthy generation. So the daemon names the
/// operation and counts it, and the head draws exactly that.
#[test]
fn an_import_draws_the_importers_own_counter_and_clears_when_it_is_done() {
    let mut a = app();
    a.clock(1_000);
    let tick = |done: u64| SessionEvent::Filling {
        what: "importing an opencode conversation".into(),
        unit: "parts".into(),
        done,
        total: 9_570,
    };
    assert!(
        !a.screen(100, 30).join("\n").contains("parts"),
        "no fill line before one is running"
    );

    a.apply(ServerFrame::Event(env(1, tick(0))));
    let start = a.screen(100, 30).join("\n");
    assert!(start.contains("0 of 9570 parts"), "{start}");
    assert!(
        start.contains("importing an opencode conversation"),
        "{start}"
    );

    a.apply(ServerFrame::Event(env(2, tick(4_790))));
    let mid = a.screen(100, 30).join("\n");
    assert!(mid.contains("4790 of 9570 parts"), "{mid}");

    // **The last tick clears the line.** The daemon's durable finish note is what
    // says the fill finished, and a bar left at `total of total` would sit on the
    // screen for ever.
    a.apply(ServerFrame::Event(env(3, tick(9_570))));
    let done = a.screen(100, 30).join("\n");
    assert!(
        !done.contains("parts"),
        "the line goes when the fill is done: {done}"
    );
}

/// **R6: a line typed while the conversation is still being imported is held.**
///
/// The daemon answers a prompt sent mid-import against the whole history — the import
/// is one worker job, so a prompt cannot interleave — but the head must not show one as
/// `queued` for a turn nobody has started. So it is refused and the words go back to the
/// field they were typed in: the §4.2 behaviour (`7b9ca62`), reused, because answering
/// against a half-adopted transcript and then appending the rest would put the
/// conversation in the wrong order (R2's rule with the whole history missing).
#[test]
fn a_line_typed_during_an_import_is_held_in_the_composer() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(
        1,
        SessionEvent::Filling {
            what: "importing an opencode conversation".into(),
            unit: "parts".into(),
            done: 0,
            total: 100,
        },
    )));
    for c in "hold me".chars() {
        a.key(Key::Char(c));
    }
    assert_eq!(
        a.key(Key::Enter),
        None,
        "nothing leaves the head while an import is running"
    );
    assert_eq!(
        a.input(),
        "hold me",
        "the words are still the operator's, in the field they typed them into"
    );
    let s = a.screen(100, 30).join("\n");
    assert!(s.contains("still being imported"), "{s}");
}

/// **`reconnecting…` is a state with a clock, not a word.**
///
/// Under the impatient threshold the line says what happened; past it the operator is
/// told how long, how many attempts, and what they can do — because a head that has
/// been saying one word for a minute has told them nothing they could not see, and is
/// indistinguishable from a head that is about to come back.
#[test]
fn a_link_that_stays_down_stops_saying_reconnecting_and_starts_saying_how_long() {
    let mut a = app();
    a.clock(1_000);
    a.link_down("the daemon closed the connection");

    // Twelve seconds in: still "reconnecting", and no advice yet — under the
    // threshold a drop is usually over before the sentence is read.
    a.clock(13_000);
    let soon = a.screen(120, 24).join("\n");
    assert!(soon.contains("reconnecting"), "{soon}");
    assert!(
        !soon.contains("letibot --status"),
        "advice nobody needs yet: {soon}"
    );

    // Past it: the elapsed time, the attempts, and the two commands that answer
    // "is the daemon gone".
    a.clock(1_000 + LINK_IMPATIENT_MS + 1);
    a.reconnect_failed("connection refused");
    a.reconnect_failed("connection refused");
    let mut a2 = a;
    a2.clock(1_000 + 72_000);
    let long = a2.screen(120, 24).join("\n");
    assert!(long.contains("trying for 1m12s"), "{long}");
    assert!(long.contains("2 attempts"), "{long}");
    assert!(long.contains("letibot --status"), "{long}");
    assert!(
        long.contains("keeps trying"),
        "it must not read as having given up: {long}"
    );

    // And when it *does* get back after those two failures, the count is shown —
    // once, in brackets, not an empty pair.
    a2.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    let up = a2.screen(120, 24).join("\n");
    assert!(
        up.contains("daemon is back after 1m12s (2 attempts)"),
        "{up}"
    );
}

/// **The backoff is the head's, and it is flat.** A caller asks once per pass and the
/// head answers whether the two seconds are up; two attempts inside one window would
/// be a busy loop against a socket that is not there.
#[test]
fn the_head_asks_for_a_reconnect_only_after_the_backoff() {
    let mut a = app();
    a.clock(1_000);
    assert!(!a.should_reconnect(), "attached heads reconnect never");
    a.link_down("the daemon closed the connection");
    assert!(
        !a.should_reconnect(),
        "the first attempt waits out the same backoff"
    );
    a.clock(1_000 + RECONNECT_BACKOFF_MS);
    assert!(a.should_reconnect());

    // A failed attempt pushes the window out again and counts itself.
    a.reconnect_failed("connection refused");
    assert!(!a.should_reconnect());
    a.clock(1_000 + RECONNECT_BACKOFF_MS + RECONNECT_BACKOFF_MS);
    assert!(a.should_reconnect());
    let drawn = a.screen(120, 24).join("\n");
    assert!(drawn.contains("connection refused"), "{drawn}");
}

/// **A `Bye` does not answer a stop this head asked for, and it does not silence the
/// farewell.**
///
/// The operator's second report, in one test: *"it reports the server exited within a
/// second — while `harnessd` is in fact hung and has to be killed with `--force`."*
///
/// The `Bye` on this path is published by the daemon's **connection thread** the moment
/// the `Stop` is taken (`registry.close()`), and the **worker** running the operator's
/// command is a different thread that has not ended. MEASURED on a live daemon,
/// 2026-10-06: `Bye` at 519 µs after the stop, the daemon's process still in `/proc`.
///
/// So both halves are asserted here, and both were wrong before the change: the head
/// used to leave on the `Bye` (`should_quit` true), and it used to say **nothing at
/// all** on the way out (`stop_farewell` `None`), which a person reads as *it stopped*.
#[test]
fn a_bye_does_not_report_a_stop_that_has_not_happened() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    // The head asks, and the daemon does what it does: the ack, then the goodbye from
    // the connection thread — with the worker still inside the command.
    a.stop_began("dead", true, Some(4242), 1_000);
    a.apply(ServerFrame::Bye {
        reason: "daemon shutting down".into(),
    });
    a.clock(1_200);

    assert!(
        !a.should_quit(),
        "the daemon's process has NOT gone — `gone` is false and nothing has observed \
             it leave — so the head must not leave on a frame that the connection thread \
             published before the worker ended. This is the lie: it reported the server \
             exited within a second."
    );

    // And when the deadline passes with the process still there, the head says what it
    // saw rather than nothing.
    a.clock(1_000 + STOP_DEADLINE_MS + 1);
    assert!(a.should_quit(), "the deadline is the head's own way out");
    let said = a
        .stop_farewell()
        .expect("a stop that did not happen must be said on the way out");
    assert!(
        said.contains("began shutting down"),
        "the daemon DID hear the request — that is what the goodbye is evidence for, \
             and it is the useful half: {said}"
    );
    assert!(
        said.contains("still there"),
        "the sentence is about the PROCESS, and the process is still there: {said}"
    );
    assert!(said.contains("4242"), "and it names it: {said}");
    assert!(
        said.contains("--force"),
        "`--force` is the next move and it is said as what it is: {said}"
    );
}

/// **And when the process really has gone, there is nothing to say.** The correction
/// above must not turn every orderly stop into a warning.
#[test]
fn a_stop_whose_process_is_gone_says_nothing_even_after_a_bye() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.stop_began("dead", true, Some(4242), 1_000);
    a.apply(ServerFrame::Bye {
        reason: "daemon shutting down".into(),
    });
    // What `Link::watch_stop` observes on every tick, and the only thing that is a fact
    // about the process.
    a.stopping_mut().expect("a stop is in flight").gone = true;
    a.clock(1_200);
    assert!(
        a.should_quit(),
        "the process has gone, so the question is answered"
    );
    assert_eq!(
        a.stop_farewell(),
        None,
        "a stop that worked is not worth a sentence"
    );
}

/// **A `Bye` is final and a dropped socket is not.** The daemon saying goodbye is the
/// end of the conversation — a refusal, a skew, a shutdown — and the head leaves with
/// the reason on it. Turning that into a retry is leticl's measured defect: a refusal
/// the daemon meant as final became a two-second loop under a head that never
/// attached and never exited.
///
/// **And it is still final for a head that did not ask for the stop**, which is the
/// half the correction above must not break: a skew, a refusal and another head's stop
/// all arrive this way, with no `stopping` in flight, and none of them is a question
/// this head is waiting on.
#[test]
fn a_bye_leaves_and_never_looks_like_a_link_to_reconnect() {
    let mut a = app();
    a.apply(hello(
        "s",
        vec![brief("s", "one", false)],
        Hub::new("s").snapshot(),
    ));
    a.apply(ServerFrame::Bye {
        reason: "protocol version 19, this daemon speaks 22".into(),
    });
    assert!(a.should_quit(), "a goodbye is the end");
    assert_eq!(
        a.farewell().map(str::to_string),
        Some("protocol version 19, this daemon speaks 22".into()),
        "and the reason outlives the screen"
    );
    // The pump dies right after the `Bye`, and the driver reports that as well: it
    // must not turn a head that is leaving into one that is reconnecting.
    a.link_down("the daemon closed the connection");
    assert!(!a.detached(), "a head on its way out does not reconnect");
    assert!(
        a.screen(100, 24)
            .join("\n")
            .contains("daemon: protocol version")
    );
}

