#[test]
fn a_tool_call_the_head_never_saw_proposed_still_names_its_target() {
    // The reattach case, which is the common one: a head that joins after a
    // turn has no proposal event to have learned the target from, and the
    // arguments on the settled row are the only place it survives. It uses the
    // *same* function the wire does, so both renderings agree.
    let mut a = app();
    a.apply(ServerFrame::Event(env(
        1,
        testing::appended("t1.0", "assistant"),
    )));
    a.apply(ServerFrame::Event(env(
        2,
        SessionEvent::TranscriptContent {
            item_id: "t1.0".into(),
            item: Box::new(TranscriptItem::Assistant {
                text: String::new(),
                tool_calls: vec![letibot_transcript::ToolCall {
                    id: "c1".into(),
                    name: "read".into(),
                    arguments: r#"{"path":"crates/ui/src/style.rs"}"#.into(),
                }],
                truncated: false,
            }),
        },
    )));
    let screen = a.screen(120, 24).join("\n");
    assert!(screen.contains("→ Read crates/ui/src/style.rs"), "{screen}");
    assert!(
        !screen.contains("(c1)"),
        "the id is not shown when a name is: {screen}"
    );
}

/// Two rounds of one turn, both numbering their calls from `call_0`, which is
/// what `letibot_turn::items` does whenever the wire format carries no id.
///
/// Taken from the operator's own session (`s-1788987496351498881`, fourteen
/// rounds of `call_0`/`call_1`/`call_2`) and reduced to the two rows that make
/// the defect: the head kept one session-wide table keyed on the call id, so
/// the later round's paths overwrote the earlier round's and every settled card
/// read back the survivor. On screen that was `▸ Read TODO.md · ok · 143 lines`
/// above a body beginning `# rano` — the payload of `README.md`.
///
/// It is a correctness test, not a layout one. A card that names a file the
/// tool did not open is the head telling the operator something false about
/// what a tool returned.
#[test]
fn a_second_round_of_calls_does_not_relabel_the_first_rounds_results() {
    fn call(id: &str, name: &str, arguments: &str) -> letibot_transcript::ToolCall {
        letibot_transcript::ToolCall {
            id: id.into(),
            name: name.into(),
            arguments: arguments.into(),
        }
    }
    fn assistant(a: &mut App, seq: u64, id: &str, calls: Vec<letibot_transcript::ToolCall>) {
        a.apply(ServerFrame::Event(env(
            seq,
            testing::appended(id, "assistant"),
        )));
        a.apply(ServerFrame::Event(env(
            seq + 1,
            SessionEvent::TranscriptContent {
                item_id: id.into(),
                item: Box::new(TranscriptItem::Assistant {
                    text: String::new(),
                    tool_calls: calls,
                    truncated: false,
                }),
            },
        )));
    }
    fn result(a: &mut App, seq: u64, id: &str, call_id: &str, name: &str, payload: &str) {
        a.apply(ServerFrame::Event(env(
            seq,
            testing::appended(id, "tool_result"),
        )));
        a.apply(ServerFrame::Event(env(
            seq + 1,
            SessionEvent::TranscriptContent {
                item_id: id.into(),
                item: Box::new(TranscriptItem::ToolResult {
                    call_id: call_id.into(),
                    name: name.into(),
                    outcome: letibot_transcript::ToolOutcome::Ok,
                    payload: payload.into(),
                    edit: None,
                    origin: None,
                    media: None,
                }),
            },
        )));
    }

    let mut a = app();
    assistant(
        &mut a,
        1,
        "r1.a",
        vec![call("call_0", "read", r#"{"path":"README.md"}"#)],
    );
    // Two lines each, so the payload is a body under a header rather than
    // inlined onto it — the pairing is what is under test, and it is only
    // visible when the two are separate rows.
    result(
        &mut a,
        3,
        "r1.t",
        "call_0",
        "read",
        "FIRST-ROUND-PAYLOAD\nmore\n",
    );
    assistant(
        &mut a,
        5,
        "r2.a",
        vec![call("call_0", "read", r#"{"path":"TODO.md"}"#)],
    );
    result(
        &mut a,
        7,
        "r2.t",
        "call_0",
        "read",
        "SECOND-ROUND-PAYLOAD\nmore\n",
    );

    // A tall enough screen that both rounds are on it at once, which is the
    // only way the pairing is visible at all.
    let lines = a.screen(120, 60);
    // The card a payload is sitting under: the nearest header above it.
    let label = |needle: &str| -> String {
        let i = lines
            .iter()
            .position(|l| l.contains(needle))
            .unwrap_or_else(|| panic!("{needle} is not on the screen:\n{}", lines.join("\n")));
        lines[..i]
            .iter()
            .rev()
            .find(|l| l.contains('▸') || l.contains('▾'))
            .cloned()
            .unwrap_or_default()
    };
    let screen = lines.join("\n");
    assert!(
        label("FIRST-ROUND-PAYLOAD").contains("README.md"),
        "round one's payload is under `{}`:\n{screen}",
        label("FIRST-ROUND-PAYLOAD")
    );
    assert!(
        label("SECOND-ROUND-PAYLOAD").contains("TODO.md"),
        "round two's payload is under `{}`:\n{screen}",
        label("SECOND-ROUND-PAYLOAD")
    );
}

/// A settled call is **one** row, not two.
///
/// It used to be two: `→ Read TODO.md` from the assistant row, then
/// `▸ Read TODO.md · ok · 129 lines · ctrl-t` from the result row three lines
/// below, saying the same thing with an outcome attached. Four calls cost
/// eight rows of a thirty-four-row terminal before any output was on it.
#[test]
fn a_settled_call_is_one_row_and_the_row_is_the_one_with_the_result_on_it() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(
        1,
        testing::appended("r.a", "assistant"),
    )));
    a.apply(ServerFrame::Event(env(
        2,
        SessionEvent::TranscriptContent {
            item_id: "r.a".into(),
            item: Box::new(TranscriptItem::Assistant {
                text: String::new(),
                tool_calls: vec![letibot_transcript::ToolCall {
                    id: "call_0".into(),
                    name: "read".into(),
                    arguments: r#"{"path":"TODO.md"}"#.into(),
                }],
                truncated: false,
            }),
        },
    )));
    let before = a.screen(120, 40).join("\n");
    assert_eq!(
        before.matches("TODO.md").count(),
        1,
        "a call with no result yet is announced exactly once:\n{before}"
    );
    assert!(
        before.contains("no result"),
        "and says it has none:\n{before}"
    );

    a.apply(ServerFrame::Event(env(
        3,
        testing::appended("r.t", "tool_result"),
    )));
    a.apply(ServerFrame::Event(env(
        4,
        SessionEvent::TranscriptContent {
            item_id: "r.t".into(),
            item: Box::new(TranscriptItem::ToolResult {
                call_id: "call_0".into(),
                name: "read".into(),
                outcome: letibot_transcript::ToolOutcome::Ok,
                payload: "# rano TODO\n".into(),
                edit: None,
                origin: None,
                media: None,
            }),
        },
    )));
    let after = a.screen(120, 40).join("\n");
    assert_eq!(
        after.matches("TODO.md").count(),
        1,
        "and once the result lands the proposal does not stay beside it:\n{after}"
    );
    assert!(after.contains("▸ Read TODO.md · ok"), "{after}");
    assert!(
        !after.contains("no result"),
        "a call that returned does not still read as one that did not:\n{after}"
    );
}

/// The same claim, with a row above the round so the narrowed invalidation
/// cannot fall back on "rewind to zero".
///
/// `a_settled_call_is_one_row_…` starts at the assistant row, so its round
/// head is index 0 and every invalidation in it is a full rebuild — which is
/// exactly the path that was never narrowed. Put a user row in front and the
/// rewind is a real one. Found by diffing the byte stream of a replay against
/// the same replay with the narrowing switched off: 59 frames of 1028 showed
/// a different screen, and the first of them had `→ Listed * · no result`
/// sitting above `▸ Listed * · ok`.
#[test]
fn a_settled_call_is_one_row_when_the_round_does_not_start_at_row_zero() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(1, testing::appended("u", "user"))));
    a.apply(ServerFrame::Event(env(
        2,
        SessionEvent::TranscriptContent {
            item_id: "u".into(),
            item: Box::new(TranscriptItem::User {
                speaker: Default::default(),
                parts: vec![UserPart::Text {
                    text: "what is in the tree".into(),
                }],
            }),
        },
    )));
    // A pane, because `drawn_live` and `superseded` are inputs to the walk and
    // a test without a turn exercises neither. The daemon's order, from
    // `docs/tui-testing.md`: the round's own rows, then the terminal event,
    // then the result rows.
    a.apply(ServerFrame::Event(env(3, testing::turn_started("t1"))));
    a.apply(ServerFrame::Event(env(
        4,
        testing::appended("r.a", "assistant"),
    )));
    a.apply(ServerFrame::Event(env(
        5,
        SessionEvent::TranscriptContent {
            item_id: "r.a".into(),
            item: Box::new(TranscriptItem::Assistant {
                text: String::new(),
                tool_calls: vec![letibot_transcript::ToolCall {
                    id: "call_0".into(),
                    name: "read".into(),
                    arguments: r#"{"path":"TODO.md"}"#.into(),
                }],
                truncated: false,
            }),
        },
    )));
    a.apply(ServerFrame::Event(env(6, testing::turn_finished("t1"))));
    // The walk has to have RENDERED the round before the result lands, or the
    // rewind has nothing to rewind and the bug hides.
    let before = a.screen(120, 40).join("\n");
    assert!(before.contains("no result"), "{before}");

    a.apply(ServerFrame::Event(env(
        7,
        testing::appended("r.t", "tool_result"),
    )));
    let _ = a.screen(120, 40);
    a.apply(ServerFrame::Event(env(
        8,
        SessionEvent::TranscriptContent {
            item_id: "r.t".into(),
            item: Box::new(TranscriptItem::ToolResult {
                call_id: "call_0".into(),
                name: "read".into(),
                outcome: letibot_transcript::ToolOutcome::Ok,
                payload: "# rano TODO\n".into(),
                edit: None,
                origin: None,
                media: None,
            }),
        },
    )));
    let after = a.screen(120, 40).join("\n");
    assert_eq!(
        after.matches("TODO.md").count(),
        1,
        "the proposal does not stay beside its own answer:\n{after}"
    );
    assert!(
        !after.contains("no result"),
        "a call that returned does not still read as one that did not:\n{after}"
    );
}

/// **Every pane swallows the wheel, and the list is checked against the
/// panes that exist** rather than against the ones somebody remembered.
///
/// `mode_picker` arrived after the wheel router did and was added to the Esc
/// handler, the render dispatch and the footer — but not here, so a wheel in
/// the mode picker scrolled the transcript underneath and closing it left the
/// operator parked in the scrollback. That is the defect the subagent view
/// already paid for once. A test per pane, so the next one added fails here
/// rather than on somebody's screen.
#[test]
fn no_pane_lets_the_wheel_through_to_the_conversation() {
    let panes: [(&str, fn(&mut App)); 8] = [
        ("help", |a| a.help = true),
        ("picker", |a| a.picker = true),
        ("mode_picker", |a| a.pick = Some(Pick::Mode)),
        ("stats", |a| a.stats = true),
        ("todos_pane", |a| a.todos_pane = true),
        ("subagents_pane", |a| a.subagents_pane = true),
        ("jobs_pane", |a| a.jobs_pane = true),
        ("config_pane", |a| a.config_pane = true),
    ];
    for (name, set) in panes {
        let mut a = app();
        for i in 0..40u64 {
            a.apply(ServerFrame::Event(env(
                i * 2 + 1,
                testing::appended(&format!("u.{i}"), "user"),
            )));
            a.apply(ServerFrame::Event(env(
                i * 2 + 2,
                testing::content(&format!("u.{i}"), &format!("line {i}")),
            )));
        }
        let _ = a.screen(80, 24);
        set(&mut a);
        a.key(Key::WheelUp);
        a.key(Key::PageUp);
        assert_eq!(a.scroll, 0, "{name} let the wheel reach the conversation");
    }
}

/// A wheel in the subagent output view scrolls that view, and leaves the
/// conversation under it where it was.
#[test]
fn the_wheel_in_the_subagent_view_does_not_move_the_conversation_underneath() {
    let mut a = app();
    for i in 0..60u64 {
        a.apply(ServerFrame::Event(env(
            i * 2 + 1,
            testing::appended(&format!("u.{i}"), "user"),
        )));
        a.apply(ServerFrame::Event(env(
            i * 2 + 2,
            testing::content(&format!("u.{i}"), &format!("line {i}")),
        )));
    }
    let _ = a.screen(80, 24);
    assert_eq!(a.scroll, 0, "following the stream");
    a.sub_out = Some(SubOut {
        session_id: "sub-1".into(),
        lines: (0..100).map(|i| format!("out {i}")).collect(),
        degraded: false,
        scroll: 0,
        spill: None,
        dropped: 0,
    });
    a.key(Key::WheelUp);
    a.key(Key::PageUp);
    // **A page is a screen here too.** The constant was ten, so this read `13`; a pager's
    // PageUp moves a page, and the subagent view is a pager. Asserted as the sum rather
    // than a literal so the two keys stay distinguishable — a PageUp that moved nothing
    // would still make this check meaningful.
    let page = a.screen_rows;
    assert!(
        page > 10,
        "the fixture's screen is not tall enough to tell the two apart"
    );
    assert_eq!(
        a.sub_out.as_ref().unwrap().scroll,
        3 + page,
        "the view scrolled a wheel notch and a page"
    );
    assert_eq!(a.scroll, 0, "the conversation did not");
    a.key(Key::Esc);
    assert!(a.sub_out.is_none());
    assert_eq!(
        a.scroll, 0,
        "and coming back lands at the tail, not in the scrollback"
    );
    // A screen on top with no scroll of its own swallows the wheel.
    a.todos_pane = true;
    a.key(Key::WheelUp);
    assert!(a.following(), "a pane on top swallowed the wheel");
    a.todos_pane = false;
    a.key(Key::WheelUp);
    // **R36 made this the assertion**: the wheel takes the viewport OFF the stream, and
    // `following` is where that state lives. It used to be `scroll == 3` — a count, and
    // the count is exactly what the requirement stops trusting: it is derived by the
    // frame, so between a key and a paint it is the previous frame's number.
    assert!(
        !a.following(),
        "with nothing on top the wheel moves the conversation"
    );
}

/// A block of calls with a slow one in the middle: the fast ones go green
/// as they finish, not when the block does.
///
/// Measured 2026-09-17 in the operator's session: `todo_write`, then a
/// `task` that ran a subagent for fifteen minutes, then three searches. The
/// pane retired the moment the assistant row's body landed — which is
/// before the calls run — and the transcript row, which draws a call from
/// its result row, showed all five as `no result` until the batch landed.
#[test]
fn a_finished_call_is_finished_while_the_call_beside_it_still_runs() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(1, testing::turn_started("t1"))));
    a.apply(ServerFrame::Event(env(
        2,
        testing::appended("r.a", "assistant"),
    )));
    a.apply(ServerFrame::Event(env(
        3,
        SessionEvent::TranscriptContent {
            item_id: "r.a".into(),
            item: Box::new(TranscriptItem::Assistant {
                text: String::new(),
                tool_calls: vec![
                    letibot_transcript::ToolCall {
                        id: "call_0".into(),
                        name: "todo_write".into(),
                        arguments: r#"{"todos":[]}"#.into(),
                    },
                    letibot_transcript::ToolCall {
                        id: "call_1".into(),
                        name: "task".into(),
                        arguments: r#"{"prompt":"fix the compaction bug"}"#.into(),
                    },
                ],
                truncated: false,
            }),
        },
    )));
    a.apply(ServerFrame::Event(env(
        4,
        testing::proposed("t1", "call_0", "todo_write"),
    )));
    a.apply(ServerFrame::Event(env(
        5,
        testing::proposed("t1", "call_1", "task"),
    )));
    a.apply(ServerFrame::Event(env(6, testing::turn_finished("t1"))));
    // The daemon's order: call_0 starts and finishes in a millisecond,
    // call_1 starts and stays running. No result row lands for either yet.
    a.apply(ServerFrame::Event(env(
        7,
        SessionEvent::ToolStarted {
            turn_id: "t1".into(),
            call_id: "call_0".into(),
            name: "todo_write".into(),
            access: Default::default(),
        },
    )));
    a.apply(ServerFrame::Event(env(
        8,
        SessionEvent::ToolFinished {
            turn_id: "t1".into(),
            call_id: "call_0".into(),
            outcome: letibot_transcript::ToolOutcome::Ok,
            payload_digest: "fnv1a:1".into(),
            inline_bytes: 12,
            full_bytes: 12,
            spill: None,
            repairs: 0,
            edit: None,
        },
    )));
    a.apply(ServerFrame::Event(env(
        9,
        SessionEvent::ToolStarted {
            turn_id: "t1".into(),
            call_id: "call_1".into(),
            name: "task".into(),
            access: Default::default(),
        },
    )));
    let screen = a.screen(120, 40).join("\n");
    assert!(
        !screen.contains("no result"),
        "a call that finished, and one still running, and neither is `no result`:\n{screen}"
    );
    assert!(
        screen.contains("● todo_write"),
        "the finished call is drawn finished:\n{screen}"
    );
    assert!(
        screen.contains("◐ task"),
        "and the running one running:\n{screen}"
    );
}

/// A message the operator sends while the calls run lands BETWEEN the calls
/// and their results. It is not the end of the round.
///
/// Measured in the store 2026-09-17: `assistant (5 calls), user, user,
/// tool_result ×10`. The results after the user rows still answer the calls
/// above them — a user cannot produce a tool result — and stopping at the
/// user row left every call `→ no result` after the model had moved on.
#[test]
fn a_message_sent_mid_round_does_not_orphan_the_rounds_results() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(
        1,
        testing::appended("r.a", "assistant"),
    )));
    a.apply(ServerFrame::Event(env(
        2,
        SessionEvent::TranscriptContent {
            item_id: "r.a".into(),
            item: Box::new(TranscriptItem::Assistant {
                text: String::new(),
                tool_calls: vec![letibot_transcript::ToolCall {
                    id: "call_0".into(),
                    name: "read".into(),
                    arguments: r#"{"path":"TODO.md"}"#.into(),
                }],
                truncated: false,
            }),
        },
    )));
    a.apply(ServerFrame::Event(env(3, testing::appended("u", "user"))));
    a.apply(ServerFrame::Event(env(
        4,
        SessionEvent::TranscriptContent {
            item_id: "u".into(),
            item: Box::new(TranscriptItem::User {
                speaker: Default::default(),
                parts: vec![UserPart::Text {
                    text: "continue".into(),
                }],
            }),
        },
    )));
    let _ = a.screen(120, 40);
    a.apply(ServerFrame::Event(env(
        5,
        testing::appended("r.t", "tool_result"),
    )));
    a.apply(ServerFrame::Event(env(
        6,
        SessionEvent::TranscriptContent {
            item_id: "r.t".into(),
            item: Box::new(TranscriptItem::ToolResult {
                call_id: "call_0".into(),
                name: "read".into(),
                outcome: letibot_transcript::ToolOutcome::Ok,
                payload: "# rano TODO\n".into(),
                edit: None,
                origin: None,
                media: None,
            }),
        },
    )));
    let after = a.screen(120, 40).join("\n");
    assert!(
        !after.contains("no result"),
        "the result after the operator's message still answers the call:\n{after}"
    );
    assert_eq!(after.matches("TODO.md").count(), 1, "{after}");
}

/// One turn, with all four of its levels on the screen at once.
///
/// The operator's report was that a turn has no shape: *"user message, then a
/// flat wall of cards"*. What answers it is a step, not a glyph — the
/// question and the answer at the body's own column, the working one step in
/// under them.
#[test]
fn a_turn_is_a_question_a_step_of_working_and_an_answer_back_at_the_margin() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(1, testing::appended("u", "user"))));
    a.apply(ServerFrame::Event(env(
        2,
        SessionEvent::TranscriptContent {
            item_id: "u".into(),
            item: Box::new(TranscriptItem::User {
                speaker: Default::default(),
                parts: vec![UserPart::Text {
                    text: "what crates are in this workspace".into(),
                }],
            }),
        },
    )));
    a.apply(ServerFrame::Event(env(
        3,
        testing::appended("t", "tool_result"),
    )));
    a.apply(ServerFrame::Event(env(
        4,
        SessionEvent::TranscriptContent {
            item_id: "t".into(),
            item: Box::new(TranscriptItem::ToolResult {
                call_id: "call_0".into(),
                name: "read".into(),
                outcome: letibot_transcript::ToolOutcome::Ok,
                payload: "one\ntwo\nthree\n".into(),
                edit: None,
                origin: None,
                media: None,
            }),
        },
    )));
    a.apply(ServerFrame::Event(env(
        5,
        testing::appended("s", "assistant"),
    )));
    a.apply(ServerFrame::Event(env(
        6,
        SessionEvent::TranscriptContent {
            item_id: "s".into(),
            item: Box::new(TranscriptItem::Assistant {
                text: "There are twelve.".into(),
                tool_calls: vec![],
                truncated: false,
            }),
        },
    )));
    let screen = a.screen(120, 40);
    let at = |needle: &str| -> usize {
        let l = screen
            .iter()
            .find(|l| l.contains(needle))
            .unwrap_or_else(|| panic!("{needle} missing:\n{}", screen.join("\n")));
        l.len() - l.trim_start().len()
    };
    let question = at("what crates are in this workspace");
    let working = at("Read (call_0)");
    let answer = at("There are twelve.");
    assert_eq!(
        question, answer,
        "the question and the answer share a column"
    );
    assert_eq!(
        working,
        question + card::REASONING_RAIL_WIDTH,
        "and the working is one step in under them:\n{}",
        screen.join("\n")
    );
}

/// [`Palette::None`] is not a monochrome theme, it is the `--replay`, pipe and
/// CI case: **no sequences at all**. The accent glyphs are what survive it, and
/// they are why the hierarchy above is carried by a step and a word rather than
/// by a colour.
#[test]
fn the_plain_palette_emits_no_escapes_and_keeps_the_glyphs() {
    let mut a = app();
    a.apply(ServerFrame::Event(env(1, testing::appended("u", "user"))));
    a.apply(ServerFrame::Event(env(
        2,
        SessionEvent::TranscriptContent {
            item_id: "u".into(),
            item: Box::new(TranscriptItem::User {
                speaker: Default::default(),
                parts: vec![UserPart::Text {
                    text: "hello".into(),
                }],
            }),
        },
    )));
    a.apply(ServerFrame::Event(env(
        3,
        testing::appended("r", "reasoning"),
    )));
    a.apply(ServerFrame::Event(env(
        4,
        SessionEvent::TranscriptContent {
            item_id: "r".into(),
            item: Box::new(TranscriptItem::Reasoning {
                text: "working it out".into(),
                field: letibot_transcript::ReasoningField::ReasoningContent,
                truncated: false,
            }),
        },
    )));
    a.apply(ServerFrame::Event(env(
        5,
        testing::appended("t", "tool_result"),
    )));
    a.apply(ServerFrame::Event(env(
        6,
        SessionEvent::TranscriptContent {
            item_id: "t".into(),
            item: Box::new(TranscriptItem::ToolResult {
                call_id: "call_0".into(),
                name: "grep".into(),
                outcome: letibot_transcript::ToolOutcome::Failed {
                    reason: "no such path".into(),
                },
                payload: "a\nb\n".into(),
                edit: None,
                origin: None,
                media: None,
            }),
        },
    )));
    a.reasoning = Fold::Open;
    let screen = a.screen(120, 40).join("\n");
    assert!(!screen.contains('\x1b'), "{screen:?}");
    for glyph in ["▌", "▸", "┃", "╭", "│", "╰"] {
        assert!(screen.contains(glyph), "{glyph} is missing:\n{screen}");
    }
    assert!(
        screen.contains("failed"),
        "and the word survives too:\n{screen}"
    );
    assert!(screen.contains("no such path"), "{screen}");
}

/// Size tells you what matters before you read a word — by **attribute**, so
/// it survives a terminal-native theme, and never by a cube colour.
#[test]
fn a_big_result_weighs_more_than_a_small_one_and_costs_no_cube_colour() {
    let mut a = App::new(RenderConfig {
        width: 120,
        color: true,
        ..RenderConfig::default()
    });
    let mut add = |seq: u64, id: &str, n: usize| {
        a.apply(ServerFrame::Event(env(
            seq,
            testing::appended(id, "tool_result"),
        )));
        a.apply(ServerFrame::Event(env(
            seq + 1,
            SessionEvent::TranscriptContent {
                item_id: id.into(),
                item: Box::new(TranscriptItem::ToolResult {
                    call_id: "call_0".into(),
                    name: "grep".into(),
                    outcome: letibot_transcript::ToolOutcome::Ok,
                    payload: "x\n".repeat(n),
                    edit: None,
                    origin: None,
                    media: None,
                }),
            },
        )));
    };
    add(1, "small", 3);
    add(3, "big", 236);
    let screen = a.screen(120, 40);
    let row = |needle: &str| {
        screen
            .iter()
            .find(|l| l.contains(needle))
            .cloned()
            .unwrap_or_else(|| panic!("{needle}: {}", screen.join("\n")))
    };
    assert!(
        row("236 lines").contains("\x1b[1m"),
        "a big result is bold: {:?}",
        row("236 lines")
    );
    assert!(
        !row("3 lines").contains("\x1b[1m"),
        "a small one is not: {:?}",
        row("3 lines")
    );
    let joined = screen.join("\n");
    for cube in ["38;5;", "48;5;", "38;2;"] {
        assert!(
            !joined.contains(cube),
            "{cube} is not a theme slot: {joined:?}"
        );
    }
}

/// A subject that does not fit takes the shortening, and the outcome does not.
